INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-7cd4281e-f384-58a0-92df-f4e661d69a1a','org-46a50a28-efd7-5664-aa1f-36fc15533c82','nike-tennis-camp-at-virginia-commonwealth-university-day-camp-june-1-5-2026','Nike Tennis Camp at Virginia Commonwealth University - Day Camp (June 1ΓÇô5, 2026)','camp','camp_sports','["tennis"]','Clinic Options Available! Sign up for after-school clinics led by the VCU coaching staff! Choose from flexible options ranging from 2-day to 8-day sessions. These clinics focus on high-level skill development and competitive play, all guided by Division I collegiate coaches. Players will work on technique, strategy, and tactics while learning a variety of drills designed to improve consistency and ball control. Summer Camp 2026 Join us for an action-packed Nike Tennis Camp at VCU in the heart of Richmond, Virginia! This camp is a Full Day camp, providing a fantastic opportunity for young athletes to learn from experienced coaches in a beautiful campus setting. This coed camp is for beginner, intermediate and advanced players, ages 11-17. Camp Director Dimitar Kutrovsky and his expert coaching staff are dedicated to helping campers develop essential tennis skills, refine their technique, and improve their point-play strategies. Whether focusing on fundamentals or advanced tactics, players will receive personalized attention and a comprehensive training experience. *If you are a returning camper, feel free to sign up via phone at (800) 645-3226 for a much quicker enrollment process*',11,17,'all','2026-06-01','2026-06-05',709.0,'per_session','$709','https://www.ussportscamps.com/tennis/nike/nike-tennis-camp-at-vcu#session-79414-1213036',NULL,'open','day',0,0,NULL,NULL,'scraped','inactive',60,'ussportscamps.com','live','5943295a-ed45-4110-8c79-124fd56f5dd5','nike-tennis-camp-at-virginia-commonwealth-university-day-camp-june-1-5-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-ce26d1d0-8101-5a2c-b76a-5c310ad1bf4f','org-68fe6687-b900-55fa-9f2d-f9bf79820be3','nike-soccer-swim-camp-with-hub-sports-at-windgate-ranch-june-1-5-2026','Nike Soccer & Swim Camp with HUB Sports at Windgate Ranch -  (June 1ΓÇô5, 2026)','camp','camp_sports','["soccer"]','Experience the ultimate summer training adventure as HUB Sports and Nike Soccer Camps team up to deliver an energizing mix of outdoor soccer development and refreshing pool time at Windgate Ranch in Scottsdale, AZ. Set on a beautifully maintained event field and featuring a stunning resortΓÇæstyle swimming pool, this camp offers the perfect combination of highΓÇælevel instruction, competitive play, and summer fun. This unique Soccer &amp; Swim program keeps players active, engaged, and cool under the Scottsdale sun. Campers will enjoy a dynamic blend of technical training, smallΓÇæsided games, and skillΓÇæbuilding challenges, followed by scheduled swim sessions designed to help athletes beat the heat, recover, and have fun in a safe and supervised environment. With topΓÇætier coaching, a vibrant outdoor setting, and the added bonus of pool time, this camp delivers an unforgettable summer experience where kids can learn, grow, and stay cool all week long. DonΓÇÖt miss your chance to train, play, and splash your way into the best week of the summer! Note: Swim instruction is available exclusively during summer camp weeks. Soccer/swim availability is listed on the schedule for each session.',5,14,'all','2026-06-01','2026-06-05',299.0,'per_session','$299','https://www.ussportscamps.com/soccer/nike/nike-soccer-swim-camp-hub-sports-windgate-ranch-scottsdale',NULL,'open','day',0,0,NULL,NULL,'scraped','inactive',60,'ussportscamps.com','live','bba32667-fead-4278-89fc-d48dd9736fdc','nike-soccer-swim-camp-with-hub-sports-at-windgate-ranch-june-1-5-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-f8ce3b5f-18b9-50d5-bbbd-2f5518e78104','org-e2aec79a-7384-5718-b643-64898b229d71','nike-soccer-camp-at-admiral-farragut-academy-june-1-5-2026','Nike Soccer Camp at Admiral Farragut Academy -  (June 1ΓÇô5, 2026)','camp','camp_sports','["soccer"]','Join us for an exciting week of soccer this summer at the Nike Soccer Camp at Admiral Farragut Academy, led by CoΓÇæDirectors Luke Sheekey, Head WomenΓÇÖs Soccer Coach at Eckerd College, and Joe Ilett, Head MenΓÇÖs Soccer Coach at Eckerd College. Both Luke and Joe are highly respected youthΓÇædevelopment coaches with extensive experience directing camps that blend modern coaching methodologies with a fun, competitive atmosphere. The campΓÇÖs curriculum merges modern, playerΓÇæcentric coaching, highΓÇæenergy activities, and exciting competitions, including our alwaysΓÇæpopular multiΓÇæteam World Showcase Tournament event. Every session is structured to help players sharpen their skills, improve decisionΓÇæmaking, and thrive in a positive, developmentΓÇæfocused environment. Campers will also enjoy the outstanding facilities at Admiral Farragut Academy, featuring pristine naturalΓÇægrass fields, plenty of shaded outdoor space, and refreshing access to the pool and indoor facilities to comfortably beat the Florida heat. These amenities create the perfect balance of safety, comfort, and highΓÇæquality training throughout the day. Whether your player is new to the game or preparing for higherΓÇælevel competition, this camp offers an unforgettable week filled with learning, excitement, and growth. Coach Luke Sheekey and Joe Ilett will also be running camps at Eckerd College in St. Petersburg! Details can be found HERE',5,14,'all','2026-06-01','2026-06-05',299.0,'per_session','$299-$445','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-st-petersburg-admiral-farragut-academy',NULL,'open','day',0,0,NULL,NULL,'scraped','inactive',60,'ussportscamps.com','live','5d3b00d7-853c-4daa-a055-c328b58ae033','nike-soccer-camp-at-admiral-farragut-academy-june-1-5-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-5316ff83-d6ce-5a36-a9b3-4b90f93ea23f','org-ee67587d-6dbe-5c1d-80ff-e828cab30553','nike-soccer-camp-at-dallas-college-north-lake-june-1-5-2026-0snd','Nike Soccer Camp at Dallas College - North Lake -  (June 1ΓÇô5, 2026)','camp','camp_sports','["soccer"]','Get ready for an unforgettable soccer experience at the Nike Soccer Camp at Dallas College North Lake in Irving, TX! This actionΓÇæpacked camp is powered by Pro Level Training and led by renowned local player development experts Keondra Mallard and Eder Falcon, two highly respected coaches with proven experience training youth, high school, collegiate, and even professional athletes. Their coaching approach blends elite instruction with a strong focus on developing confident, intelligent, and technically skilled players. Campers will train on the conveniently located, premier athletic facilities at Dallas College North Lake, creating the perfect environment for learning, competing, and having fun. Designed for boys and girls ages 6ΓÇô16, this week-long program features a dynamic and progressive curriculum that emphasizes skill development, highΓÇæenergy drills, gameΓÇæbased learning, and nonstop excitement. Players will sharpen their technique, improve their soccer IQ, and enjoy fastΓÇæpaced activities that keep them engaged from start to finish. Join us this summer and take your game to the next level with one of the top training experiences in Texas!',6,16,'all','2026-06-01','2026-06-05',399.0,'per_session','$399','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-dallas-college-northlake',NULL,'open','day',0,0,NULL,NULL,'scraped','inactive',60,'ussportscamps.com','live','1faff1c7-6070-4fd0-bd49-af17a3eb842d','nike-soccer-camp-at-dallas-college-north-lake-june-1-5-2026-0snd','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
