INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-d6f3fcc2-bb72-5d61-8570-b01f1074e7ce','org-81896ee4-1687-5d46-b29a-ac3f8b5c39c8','nike-soccer-camp-in-norman-oklahoma-june-7-9-2026','Nike Soccer Camp in Norman Oklahoma -  (June 7ΓÇô9, 2026)','camp','camp_sports','["soccer"]','Join us for an incredible camp experience at the Nike Soccer Camp at the University of Oklahoma in Norman, OK. Hosted on the OU campus, this camp gives players the opportunity to train in a true collegiate environment, utilizing top-tier athletic facilities and fields while experiencing the energy and tradition of a major Division I program. Team up with Camp Director and University of Oklahoma WomenΓÇÖs Soccer Head Coach Matt Mott and his staff for the ultimate soccer training experience. Led by Oklahoma coaches, the camp provides players with direct insight into the standards, training methods, and expectations of high-level college soccer. With a blend of traditional and modern coaching methodologies, the curriculum is designed to help every camper continue progressing to the next level of play. This is a fully residential overnight camp experience, with campers staying in campus housing and fully immersing themselves in life as a college athlete. From dorm living to training on campus fields, players gain a firsthand understanding of what it takes to compete at the collegiate level while building independence, friendships, and lasting summer memories. Sure to be a summer highlight, this camp offers a unique and exciting opportunity for aspiring soccer players ages 10ΓÇô16 to train in a FUN, engaging, and collegiate-level setting. Throughout the week, campers will develop new skills, refine techniques, expand their game knowledge, and enjoy the game alongside players from across the region.',10,16,'all','2026-06-07','2026-06-09',554.0,'per_session','$554','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-at-the-university-of-oklahoma#session-82750-1218097',NULL,'open','day',0,0,NULL,NULL,'scraped','inactive',60,'ussportscamps.com','live','9077d073-e27d-47c2-a0d5-0be9229682af','nike-soccer-camp-in-norman-oklahoma-june-7-9-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
