per_session','$155','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-las-vegas-nv#session-80429-1215077',NULL,'open','day',0,0,NULL,NULL,'scraped','inactive',60,'ussportscamps.com','live','a8b82ef9-38e9-4d67-be97-0c5cfcedbb11','nike-soccer-camp-with-jm-soccer-academy-in-las-vegas-june-8-12-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
