INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-79baca8a-ab6b-5a8b-a732-34450386d62e','org-939d5756-c9ba-5c6d-9b73-f3e75cf0e1b6','nike-tennis-camp-at-virginia-commonwealth-university-day-camp-june-8-12-2026','Nike Tennis Camp at Virginia Commonwealth University - Day Camp (June 8ΓÇô12, 2026)','camp','camp_sports','["tennis"]','Clinic Options Available! Sign up for after-school clinics led by the VCU coaching staff! Choose from flexible options ranging from 2-day to 8-day sessions. These clinics focus on high-level skill development and competitive play, all guided by Division I collegiate coaches. Players will work on technique, strategy, and tactics while learning a variety of drills designed to improve consistency and ball control. Summer Camp 2026 Join us for an action-packed Nike Tennis Camp at VCU in the heart of Richmond, Virginia! This camp is a Full Day camp, providing a fantastic opportunity for young athletes to learn from experienced coaches in a beautiful campus setting. This coed camp is for beginner, intermediate and advanced players, ages 11-17. Camp Director Dimitar Kutrovsky and his expert coaching staff are dedicated to helping campers develop essential tennis skills, refine their technique, and improve their point-play strategies. Whether focusing on fundamentals or advanced tactics, players will receive personalized attention and a comprehensive training experience. *If you are a returning camper, feel free to sign up via phone at (800) 645-3226 for a much quicker enrollment process*',11,17,'all','2026-06-08','2026-06-12',709.0,'per_session','$709','https://www.ussportscamps.com/tennis/nike/nike-tennis-camp-at-vcu#session-79416-1213038',NULL,'open','day',0,0,NULL,NULL,'scraped','inactive',60,'ussportscamps.com','live','7d02c05e-5fd0-4d9d-84d1-22dc80ce6171','nike-tennis-camp-at-virginia-commonwealth-university-day-camp-june-8-12-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
