INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-0ad0127e-280a-5e3a-b696-2f815c0c33a4','org-480a29e2-e2f8-590c-8da8-e8897690dca1','nike-soccer-camp-at-cabrillo-college-june-8-12-2026-xku1','Nike Soccer Camp at Cabrillo College -  (June 8ΓÇô12, 2026)','camp','camp_sports','["soccer"]','Get ready for an unforgettable summer of soccer at the Nike Soccer Camp at Cabrillo College in Aptos, California, a program so popular that many camp weeks have sold out the past two years! Boys and girls ages 7ΓÇô14 will train on the beautiful, stateΓÇæofΓÇætheΓÇæart fields of Cabrillo CollegeΓÇÖs stunning coastal campus, creating the perfect backdrop for elite coaching, highΓÇæenergy development, and nonstop fun. Led by Cabrillo College MenΓÇÖs Soccer Head Coach Paolo Carbone, this camp delivers a topΓÇætier training experience powered by a blend of timeΓÇætested methodologies and modern playerΓÇædevelopment techniques. Coach Carbone and his experienced staff create an environment where every athlete, whether brandΓÇænew to the game or pushing toward competitive levels, can confidently elevate skills, improve soccer IQ, and unlock their full potential. Each day features dynamic technical drills, fastΓÇæpaced activities, smallΓÇæsided games, and competitive gameplay designed to inspire creativity, sharpen decisionΓÇæmaking, and build a true love for the sport. Combined with Cabrillo CollegeΓÇÖs premium training facilities and an upbeat, supportive camp culture, this program offers one of the most exciting and soughtΓÇæafter youth soccer experiences in the Santa Cruz and Monterey Bay region. Join us this summer and experience why the Nike Soccer Camp at Cabrillo College continues to sell out every yearΓÇötrain with elite coaches, develop your game, and enjoy an unforgettable week of soccer excellence!',7,14,'all','2026-06-08','2026-06-12',325.0,'per_session','$325-$435','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-cabrillo-college',NULL,'open','day',0,0,NULL,NULL,'scraped','inactive',60,'ussportscamps.com','live','1a85bae0-6394-402d-b60b-4ad057def20f','nike-soccer-camp-at-cabrillo-college-june-8-12-2026-xku1','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
