INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-fe353061-baaf-57f0-ada1-71094f206f00','org-5afdfc99-6bd1-5bcf-b216-e3284ca29e3f','nike-soccer-camp-at-university-of-wisconsin-parkside-june-15-18-2026','Nike Soccer Camp at University of Wisconsin - Parkside -  (June 15ΓÇô18, 2026)','camp','camp_sports','["soccer"]','Give your young athlete an unforgettable week of soccer development and fun this summer at the Nike Soccer Camp at UWΓÇæParkside! Open to boys and girls ages 6ΓÇô14, this coed camp is designed for all skill levels, whether your child is brandΓÇænew to the game or looking to take their skills to the next level. Led by Head WomenΓÇÖs Coach Brittany Nikolic and Head MenΓÇÖs Coach Jason Zitzke, campers will train with UWΓÇæParksideΓÇÖs topΓÇætier coaching staff and college players, known for their energy, expertise, and passion for helping young athletes grow. Hosted on the beautiful UWΓÇæParkside campus, this camp delivers the perfect blend of highΓÇælevel instruction, ageΓÇæappropriate challenges, and nonstop fun. Players will sharpen their technique, build confidence, and enjoy an inspiring environment where teamwork, encouragement, and love for the game come first. If your child wants to improve their soccer skills, make new friends, or enjoy an exciting week outdoors, the Nike Soccer Camp at UWΓÇæParkside offers an incredible experience from the opening whistle to the final celebration. Hear from Head Coach Brittany Nikolic: "Our coaching staff is made up of current college coaches and college players. We love to teach technique and game concepts so the kids build confidence and in turn have a great time. We strongly believe in teamwork and respect and know that through sport these kids are developing important life skills."',6,14,'all','2026-06-15','2026-06-18',245.0,'per_session','$245','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-uw-parkside#session-79297-1212839',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','bbeee7db-55b5-4a7a-81e8-d3faba83f0a3','nike-soccer-camp-at-university-of-wisconsin-parkside-june-15-18-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
