INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-6544e719-43c5-5a37-835a-5c1fac12f041','org-a3a5942b-5c1f-59df-8ee9-8c29f1fd8a48','nike-boys-soccer-camp-at-university-of-portland-june-15-18-2026','Nike Boys Soccer Camp at University of Portland -  (June 15ΓÇô18, 2026)','camp','camp_sports','["soccer"]','Nike Boys Soccer Camp at University of Portland was voted a top 10 Nike Soccer Camp in 2025 by players and parents! Nike Boys Soccer Camp at University of Portland provides exceptional coaching and a welcoming atmosphere that helps players of all levels grow. With engaging drills, supportive instructors, and a strong emphasis on teamwork, it creates an exciting environment where kids can build confidence, improve their skills, and have a great time on the field. Join us this summer for the Nike Soccer Camp at the University of Portland, led by the U. of Portland Men''s coaching staff! Offering youth day camps and collegiate experience residential camps. Designed for dedicated young players, the youth day camps blend traditional and modern coaching techniques to maximize skill development. Train with top coaches and players in a competitive yet supportive environment, gaining advanced technical skills, tactical awareness, and a deeper passion for the game. Don''t miss this chance to elevate your game and take the next step in your soccer journey!',6,13,'all','2026-06-15','2026-06-18',409.0,'per_session','$409-$519','https://www.ussportscamps.com/soccer/nike/nike-boys-soccer-camp-university-of-portland',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','e1ed3b9c-ed80-442a-a245-59793a8e346e','nike-boys-soccer-camp-at-university-of-portland-june-15-18-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-833db146-8548-5608-a49c-0c7c8bf1f5e8','org-5afdfc99-6bd1-5bcf-b216-e3284ca29e3f','nike-soccer-camp-at-university-of-wisconsin-parkside-june-15-18-2026-arm8','Nike Soccer Camp at University of Wisconsin - Parkside -  (June 15ΓÇô18, 2026)','camp','camp_sports','["soccer"]','Give your young athlete an unforgettable week of soccer development and fun this summer at the Nike Soccer Camp at UWΓÇæParkside! Open to boys and girls ages 6ΓÇô14, this coed camp is designed for all skill levels, whether your child is brandΓÇænew to the game or looking to take their skills to the next level. Led by Head WomenΓÇÖs Coach Brittany Nikolic and Head MenΓÇÖs Coach Jason Zitzke, campers will train with UWΓÇæParksideΓÇÖs topΓÇætier coaching staff and college players, known for their energy, expertise, and passion for helping young athletes grow. Hosted on the beautiful UWΓÇæParkside campus, this camp delivers the perfect blend of highΓÇælevel instruction, ageΓÇæappropriate challenges, and nonstop fun. Players will sharpen their technique, build confidence, and enjoy an inspiring environment where teamwork, encouragement, and love for the game come first. If your child wants to improve their soccer skills, make new friends, or enjoy an exciting week outdoors, the Nike Soccer Camp at UWΓÇæParkside offers an incredible experience from the opening whistle to the final celebration. Hear from Head Coach Brittany Nikolic: "Our coaching staff is made up of current college coaches and college players. We love to teach technique and game concepts so the kids build confidence and in turn have a great time. We strongly believe in teamwork and respect and know that through sport these kids are developing important life skills."',6,14,'all','2026-06-15','2026-06-18',245.0,'per_session','$245-$335','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-uw-parkside',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','e68d0100-d9b6-44cc-86bd-103eed467310','nike-soccer-camp-at-university-of-wisconsin-parkside-june-15-18-2026-arm8','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
