INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-b92141ce-e221-5131-a73f-3a5e35c46205','org-34f5bf24-47ec-5bbe-b0da-14ec5091b85d','nike-soccer-camp-at-university-of-charleston-june-15-19-2026','Nike Soccer Camp at University of Charleston -  (June 15ΓÇô19, 2026)','camp','camp_sports','["soccer"]','Experience an unforgettable week of soccer at the Nike Soccer Camp at the University of Charleston, one of West VirginiaΓÇÖs premier training destinations for young athletes ages 6ΓÇô16! Join Camp Director and Assistant MenΓÇÖs Soccer Coach Corbin Bowers for a highΓÇæenergy, immersive camp designed to accelerate player development for beginners through advanced competitors. Train like a Golden Eagle as you learn from a program recognized for excellence, including the 2017 &amp; 2019 NCAA Division II National Championships and the reigning 8ΓÇætime consecutive MEC Tournament Champions. Under Coach Bowers and the Charleston staff, campers will benefit from a curriculum that blends modern training methodology, technical repetition, and gameΓÇærealistic instruction, ensuring every player has the opportunity to grow, develop, and reach the next level. Throughout the week, campers will sharpen their footwork, improve decisionΓÇæmaking, build confidence, and compete in fun, fastΓÇæpaced drills and scrimmages, all on the beautiful University of Charleston campus. With the full Nike Soccer Camp experience, players will not only elevate their skills but also make new friends, grow their love for the game, and create memories that last a lifetime. Hear directly from Coach Cobrin Bowers: "Our camp is a true balance of skill development, learning within the game, and having as much fun as possible. Players will learn a variety of skills, get to apply them in game-like scenarios, and boost their soccer confidence on a daily basis. We want everyone that joins us for camp to feel like they had the best soccer week of the summer and will be itching to come back year after year." DonΓÇÖt miss your chance to train with championshipΓÇæcaliber coaches in Charleston, WV, secure your spot today!',6,16,'all','2026-06-15','2026-06-19',255.0,'per_session','$255','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-university-of-charleston-wv#session-81747-1216760',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','04f5cdea-b846-42a3-8278-9a90dc26dd76','nike-soccer-camp-at-university-of-charleston-june-15-19-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
