INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-7af9b9d6-9a73-5ecd-bd14-18f78e597955','org-701570f4-c59d-57dc-8bd5-b370a68a4ae9','nike-tennis-camp-at-the-tennis-academy-of-utah-june-15-19-2026','Nike Tennis Camp at The Tennis Academy of Utah -  (June 15ΓÇô19, 2026)','camp','camp_sports','["tennis"]','Join us for an action-packed Nike Tennis Camp at The Tennis Academy of Utah! This camp offers a full day option, providing a fantastic opportunity for young athletes to learn from experienced coaches in a fun and competitive setting. This coed camp is for players of all abilities, ages 8-18. Camp Director Yhale Scott and his expert coaching staff are dedicated to helping campers develop essential tennis skills, refine their technique, and improve their point-play strategies. Whether focusing on fundamentals or advanced tactics, players will receive personalized attention and a comprehensive training experience.',8,18,'all','2026-06-15','2026-06-19',479.0,'per_session','$479','https://www.ussportscamps.com/tennis/nike/nike-tennis-camp-at-the-tennis-academy-of-utah#session-82902-1218295',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','a28f2df8-1c20-456e-a859-7a462712a4de','nike-tennis-camp-at-the-tennis-academy-of-utah-june-15-19-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-6b0e5a37-941e-5c18-bda1-9889f3fe3140','org-4aa2b1d3-a129-59ab-81ec-cbe006289330','nike-tennis-camp-at-virginia-commonwealth-university-day-camp-june-15-19-2026','Nike Tennis Camp at Virginia Commonwealth University - Day Camp (June 15ΓÇô19, 2026)','camp','camp_sports','["tennis"]','Clinic Options Available! Sign up for after-school clinics led by the VCU coaching staff! Choose from flexible options ranging from 2-day to 8-day sessions. These clinics focus on high-level skill development and competitive play, all guided by Division I collegiate coaches. Players will work on technique, strategy, and tactics while learning a variety of drills designed to improve consistency and ball control. Summer Camp 2026 Join us for an action-packed Nike Tennis Camp at VCU in the heart of Richmond, Virginia! This camp is a Full Day camp, providing a fantastic opportunity for young athletes to learn from experienced coaches in a beautiful campus setting. This coed camp is for beginner, intermediate and advanced players, ages 11-17. Camp Director Dimitar Kutrovsky and his expert coaching staff are dedicated to helping campers develop essential tennis skills, refine their technique, and improve their point-play strategies. Whether focusing on fundamentals or advanced tactics, players will receive personalized attention and a comprehensive training experience. *If you are a returning camper, feel free to sign up via phone at (800) 645-3226 for a much quicker enrollment process*',11,17,'all','2026-06-15','2026-06-19',709.0,'per_session','$709','https://www.ussportscamps.com/tennis/nike/nike-tennis-camp-at-vcu#session-79418-1213040',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','ff13325f-ce5d-4add-9c33-0f7a228ef2b4','nike-tennis-camp-at-virginia-commonwealth-university-day-camp-june-15-19-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-ed144c7b-ac6f-557b-a035-7f66250f3f6f','org-f1a9d64b-3222-5dcd-84d0-423a99769f10','nike-baseball-camp-in-phoenix-all-skills-camp-june-16-19-2026','Nike Baseball Camp in Phoenix - All Skills Camp (June 16ΓÇô19, 2026)','camp','camp_sports','["baseball_softball"]','Our staff is dedicated to making your time with us this summer the single most important days in your baseball career. The purpose of our camps is to teach the fundamentals of baseball to various age levels, helping each participant to better understand the game both mentally and physically. Joining us will also allow players to further develop individual skills through instruction, individual and multi-player drills and game experience as well as interaction with players off the field in a comfortable camp setting. Players will work hard while having fun at the same time.',7,18,'all','2026-06-16','2026-06-19',399.0,'per_session','$399','https://www.ussportscamps.com/baseball/nike/baseball-camp-phoenix',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','04f86e81-e7e7-413c-869b-caa8a2c526cc','nike-baseball-camp-in-phoenix-all-skills-camp-june-16-19-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-db33b80a-ac28-548f-84af-eb36b3262fc8','org-4afc6d43-ebd0-55f5-a233-f78da76d58e3','nike-baseball-camp-central-park-june-15-19-2026','Nike Baseball Camp Central Park -  (June 15ΓÇô19, 2026)','camp','camp_sports','["baseball_softball"]','Join Nike Baseball Camps in Central Park (Manhattan), hosted by New York Empire Baseball. This intensive 5-day Camp will group players by both age and skill, and players will be trained by some of the most well-trained and certified coaches in youth baseball - using the most advanced technology and engaging and in-depth instruction available. The Camp will be led by New York Empire Baseball''s advanced instructional staff - one of the most highly trained and certified in the baseball industry. The coaching staff will be led by Director of Research &amp; Training, Coach Jordan Baltimore. Coach Baltimore was the worldΓÇÖs first coach to receive Driveline Certification, is on the Blast Motion Advisory Board, and is also certified by OnBaseU, K-Motion, and Rapsodo Sports. He''s also the PItching Consultant to the NYU Langone Sports Performance Center, and was named to the New York City Mayor''s Baseball Advisory Commission at the Office of Sports, Wellness, and Recreation. He was previously the New York Area Director for the National Pitching Association. Instructors will utilize New York Empire Baseball''s proprietary Player Development Platform along with Blast Motion Bat Sensors and high-speed video analysis, among other technologies, to measure, assess, and define unique development programs for every player. This Camp will be rain or shine - as in the event of rain, Camp will move indoors to New York Empire Baseball''s High-Tech indoor home, The Arena. Players will begin their week-long experience with a complete Assessment and Baseline Hitting &amp; Pitching analysis before receiving their personalized Camp training program. All players will then engage in 5 days of small group sessions in Hitting, Throwing, Infielding, Outfielding, Baserunning, and Game Situations. Each day will focus on healthy athletic development and skill acquisition in a fun &amp; engaging environment that will also teach the mental/emotional approach needed to eliminate performance anxiety and fear of failure. Players will develop skills that scale, and receive an individualized post-Camp training routine to continue their own development.',8,18,'all','2026-06-15','2026-06-19',1269.0,'per_session','$1269','https://www.ussportscamps.com/baseball/nike/nike-baseball-camp-central-park',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','7cd0fe26-7dec-443a-a7d6-afdb654e989d','nike-baseball-camp-central-park-june-15-19-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-f05ecc0c-eeb5-57cb-a199-001262a8ac11','org-f5847ea4-94bb-58c1-91c6-b5d3323ee66e','nike-baseball-camp-at-eckerd-college-june-15-19-2026','Nike Baseball Camp at Eckerd College -  (June 15ΓÇô19, 2026)','camp','camp_sports','["baseball_softball"]','Get ready for the Nike Baseball Camps at the Eckerd College in St. Petersburg, FL! All baseball players that attend will learn valuable skills that they can transfer into their game to help them become better baseball players. Instruction will cover all aspects of baseball including fielding, hitting, baserunning, and team play. Summer is the perfect time to continue perfecting your love of the game and Director Josh Beauregard is confident he can help your camper reach their goals. Coach Beauregard is heading into his 9th season as the Head Coach and is looking forward to welcoming campers of all abilities to the Eckerd College baseball diamond. Our campers are getting the best when it comes to coaching experience and guys who want our campers to have fun learning our great game.',7,13,'all','2026-06-15','2026-06-19',369.0,'per_session','$369','https://www.ussportscamps.com/baseball/nike/nike-baseball-camp-eckerd-college',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','c752e936-cc42-4a17-96de-0eeb80a79bb6','nike-baseball-camp-at-eckerd-college-june-15-19-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
