un.',8,18,'all','2026-06-21','2026-06-24',545.0,'per_session','$545-$829','https://www.ussportscamps.com/soccer/nike/nike-boys-soccer-camp-sacred-heart-university',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','4dcce2c2-ad7e-4e81-b7b5-39581b6efc61','nike-boys-soccer-camp-sacred-heart-university-june-21-24-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
