INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-62df7f38-7181-56b7-9caf-eaabf2087569','org-1f6f51ae-01d6-5b25-8579-b51f490fb0de','nike-baseball-camp-at-san-marcos-high-school-june-22-25-2026','Nike Baseball Camp at San Marcos High School -  (June 22ΓÇô25, 2026)','camp','camp_sports','["baseball_softball"]','Join our Nike Baseball Camp at San Marcos High School in Santa Barbara, California! Athletes of all abilities are encouraged to join us this winter to gain valuable baseball experience and create lasting memories. Quality facilities, knowledgeable coaches, and a positive environment are characteristics of this camp. Whether it be long-term or short-term goals you have set for yourself, Coach Tom Myers and staff are determined to help you get a step closer to your accomplishments. Directing the camp is Tom Myers, an Area Scout for the Los Angeles Dodgers. The goal is for every camper to take their game to the next level, create friendships, and have a great time.',8,10,'all','2026-06-22','2026-06-25',429.0,'per_session','$429','https://www.ussportscamps.com/baseball/nike/nike-baseball-camp-san-marcos-high-school',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','47ce3ad4-eaa5-4cbe-8bd2-4f43fda21b91','nike-baseball-camp-at-san-marcos-high-school-june-22-25-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-1e361dfc-e6e7-5f86-811d-fb4c7cf4f8b3','org-2ddcb612-58af-5e6c-9c17-67d223788f16','nike-baseball-camp-at-adventhealth-stadium-directed-by-rome-emperors-june-23-25-','Nike Baseball Camp at AdventHealth Stadium, directed by Rome Emperors -  (June 23ΓÇô25, 2026)','camp','camp_sports','["baseball_softball"]','Nike Baseball Camps is thrilled to return to host camp with the Rome Emperors the High-A Affiliate of the Atlanta Braves! The Emperors staff and players are ready to provide a great learning environment and give each camper the proper tools to excel at the next level. Campers age 7-13 will have have the opportunity to learn how to approach the sport the right way as they fine-tune their fielding, hitting, base-running skills, and enhance their knowledge of the game, all while having an awesome time and making new friends. Campers will also have the opportunity to attend a Rome Emperors each day after camp!',7,13,'all','2026-06-23','2026-06-25',299.0,'per_session','$299','https://www.ussportscamps.com/baseball/nike/nike-baseball-camp-rome-emperors',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','f10ab9e4-3c4c-4e1b-8dff-aedabe20795f','nike-baseball-camp-at-adventhealth-stadium-directed-by-rome-emperors-june-23-25-','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
