INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-a9d29ce3-8d83-5707-9685-85e3a47205c6','org-c6a19cf4-2d29-5bed-b166-354120bb638a','summer-camp-rock-ropes-1-tacoma','Summer Camp - Rock & Ropes 1 - Tacoma','camp','camp_general',NULL,'Five-day Tacoma day camp at the Mountaineers Tacoma Program Center for kids in grades 1-7 focused on introduction to rock climbing. Campers learn to belay, tie climbing knots, rappel, prusik, and try basic anchor work. Each group gets one outdoor climbing field trip during the week to Exit 38 near North Bend. Friday meets at Point Defiance Park for a hike, picnic, and beach time. Camp runs 8:30am to 4:30pm Monday through Thursday. Led by Sarah Holt.',6,13,'beginner','2026-06-22','2026-06-26',385.0,'per_session','$385 members / $410 guests','https://www.mountaineers.org/locations-lodges/tacoma-branch/committees/tacoma-youth-outreach-committee/course-templates/summer-camp-rock-ropes-1-tacoma/summer-camp-rock-ropes-1-tacoma-2026',NULL,'waitlist','day',0,0,NULL,NULL,'scraped','active',90,'mountaineers.org','live','22fa967f-2c8e-4fdb-bcc4-e16c931d8958','summer-camp-rock-ropes-1-tacoma','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-6865ed17-86e1-5b7a-9ab2-fba8d3357de7','org-b81ef3c2-3888-5339-bd89-a7f6feec0012','sound-life-day-camp-week-1-animal-life','Sound Life Day Camp - Week 1: Animal Life','camp','camp_general',NULL,'Tacoma Christian day camp with daily off-site field trips. Week 1 themed Animal Life with trips to Kopachuck wildlife area, Northwest Trek Wildlife Park, Woodland Park Zoo, Tahoma Alpaca Mill, and Friday swimming. Camp hours 8:15am to 4:30pm with free before-care 7:30 to 8:15am and aftercare 4:30 to 5:30pm. One-time $30 registration fee per camper. Campers should bring lunch, water bottle, walking shoes, Bible, and swim suit when needed.',6,13,'all','2026-06-22','2026-06-26',220.0,'per_session','$220/week plus $30 registration','https://www.soundlifedaycamp.com/tacoma',NULL,'open','day',0,0,NULL,NULL,'scraped','active',90,'soundlifedaycamp.com','live','3444685e-818e-4920-a13e-c2fc0219b8c9','sound-life-day-camp-week-1-animal-life','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
