INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-451c1cbb-a983-59ec-82b5-d8b5b3eb1ce8','org-5dd6ba25-5dae-5661-acbd-13792d03e323','nike-soccer-camp-with-tacoma-stars-at-tacoma-soccer-center','Nike Soccer Camp with Tacoma Stars at Tacoma Soccer Center','camp','camp_sports','["soccer"]','Nike Soccer Camp coached by Tacoma Stars pro indoor staff and run through US Sports Camps. Five-day day camp held on indoor turf at the Tacoma Soccer Center. Future Stars program for ages 4-6 runs as a half day. Player Development for ages 7-15 is offered as half day ($280) or full day ($390). Camp Director is Alex Caceres. Curriculum focuses on technical precision, quick decision-making, and indoor-style training.',4,15,'all','2026-06-22','2026-06-26',280.0,'per_session','$280-$390','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-tacoma-stars-tacoma-soccer-center',NULL,'open','day',0,0,NULL,NULL,'scraped','active',90,'ussportscamps.com','live','14c32db7-b2e6-480f-89ff-10ed88cdfb45','nike-soccer-camp-with-tacoma-stars-at-tacoma-soccer-center','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-33893a6f-47fd-5aaf-adb8-6def24f8ebb6','org-1ea62c0b-58e9-50af-a50e-46d55bd3825b','challenger-sports-foundational-skills-camp-dupont-week-1','Challenger Sports Foundational Skills Camp - DuPont Week 1','camp','camp_sports','["soccer"]','Challenger Sports Foundational Skills Camp held at DuPont Powder Works Park in coordination with DuPont Park & Recreations. Five-day day camp where international coaching staff lead age-grouped technical training and small-sided games for ages 3 to 14. Sessions emphasize ball control, dribbling, passing, and game understanding. Shin guards are required for ages 6 and up or any session over three hours.',3,14,'all','2026-06-22','2026-06-26',119.0,'per_session','$119-$349','https://challengersports.com/camps/dupont-park-and-recreations-week-1-dupont-wa/',NULL,'open','day',0,0,NULL,NULL,'scraped','active',90,'challengersports.com','live','c7a3518e-b5e0-49b2-9c0b-8d1f333f0136','challenger-sports-foundational-skills-camp-dupont-week-1','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-d89b65e3-88e9-5f24-a209-343ab2e0eda1','org-289e7e05-6857-567b-b9eb-510996cbc0b0','summer-at-annie-wright-grade-1-2-mixed-athletics-swimming-volleyball-june-22-26','Summer at Annie Wright - Grade 1-2 Mixed Athletics: Swimming & Volleyball (June 22-26)','camp','camp_general',NULL,'Half-day weeklong athletics camp at Annie Wright Schools for students entering grades 1-2 in fall. Activities split between volleyball and swimming, held at the Murray Barbey Family Pool and adjacent gym on the AWS campus. Run by AWS faculty and local coaches. Half-day morning session 9:00 AM to 12:00 PM. Full-day options available with afternoon arts session add-on. Home-packed lunch required for full day attendees.',6,8,'beginner','2026-06-22','2026-06-26',185.0,'per_session','$185','https://www.hisawyer.com/annie-wright-schools/schedules/activity-set/1834496?source=camps',NULL,'open','day',0,0,NULL,NULL,'scraped','active',90,'hisawyer.com','live','344d9bac-afcb-4cea-a2d4-04ea0d8894d0','summer-at-annie-wright-grade-1-2-mixed-athletics-swimming-volleyball-june-22-26','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-19c2c758-7e5a-5aa2-9416-19e63e743c29','org-86de58dc-9929-57bd-896a-8be4f81920a1','summer-at-annie-wright-grade-3-6-athletics-soccer-june-22-26','Summer at Annie Wright - Grade 3-6 Athletics: Soccer (June 22-26)','camp','camp_sports','["soccer"]','Half-day weeklong soccer camp at Annie Wright Schools for students entering grades 3-6 in fall. Held outdoors at James Memorial Field on the AWS campus. Morning session 9:00 AM to 12:00 PM, Monday through Friday. Local coaches and AWS faculty lead skill-building, small-sided play, and team activities. Full-day options available by adding an afternoon arts session.',8,11,'all','2026-06-22','2026-06-26',185.0,'per_session','$185','https://www.hisawyer.com/annie-wright-schools/schedules/activity-set/1834500?source=camps',NULL,'open','day',0,0,NULL,NULL,'scraped','active',90,'hisawyer.com','live','4ab8890e-d262-48b7-a542-52a3dd11aacb','summer-at-annie-wright-grade-3-6-athletics-soccer-june-22-26','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
