INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-d895dd4b-8320-5f3d-80ee-806105629b50','org-5da2c189-050f-5711-a8ad-950ab1f9bdcd','cwa-summer-camp-sports-camp-volleyball-grades-1-2','CWA Summer Camp - Sports Camp: Volleyball (Grades 1-2)','camp','camp_sports','["volleyball"]','Half-day weeklong volleyball camp at Charles Wright Academy for students entering grades 1-2 in fall. Held on the 107-acre CWA campus, Monday-Friday 8:30 AM to 11:30 AM. Combines an hour and a half of volleyball-focused instruction with general camp activities such as field games, forest exploration, and outdoor classroom time. Coaches lead skill-building, teamwork, and player safety. Aftercare is available until 5:30 PM at extra cost.',6,8,'beginner','2026-06-22','2026-06-26',250.0,'per_session','$250','https://www.homeroom.com/sites/charles-wright-academy-university-place/camp/sports-camps',NULL,'open','day',0,0,NULL,NULL,'scraped','active',90,'homeroom.com','live','1dde6672-8a44-449f-b1bd-0904587d24b9','cwa-summer-camp-sports-camp-volleyball-grades-1-2','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-96fbe84f-9e8b-5c56-a43f-6656e57808da','org-2523ca92-ceef-5c35-8e88-63de963fd2cd','nike-soccer-camp-at-furman-university-june-22-26-2026','Nike Soccer Camp at Furman University -  (June 22ΓÇô26, 2026)','camp','camp_sports','["soccer"]','Recognized as a Top-10 Rated Director Awards recipient, the Nike Soccer Camp at Furman University is consistently regarded as one of the premier youth soccer camps in the region and a trusted favorite among families year after year. Set on the beautiful Furman University campus, campers train in an inspiring collegiate environment led by Head Coach Andrew Burr and his experienced coaching staff. With a strong tradition of excellence, the staff brings a high level of expertise, energy, and care to every session. Open to boys and girls ages 4ΓÇô14 of all skill levels, campers are grouped by age and ability to ensure the right balance of challenge and support. The curriculum blends high-quality instruction with a fun, engaging atmosphere, helping players develop their skills, confidence, and love for the game Hear from Head Coach Andrew Burr: "Our coaches are high-energy and excited about creating a fun environment where campers will develop a love for soccer, and enjoy participating with passionate coaches and new friends. In addition to developing soccer players, we enjoy pouring into the kids with an emphasis on teamwork and how to treat others. Our staff consists of highly qualified coaches, but we also have members of our staff who are local school principals, teachers, and college professors. It makes for a well-rounded group that has expertise in working with children. This makes all aspects of the camp, from registration and check-in process, making the campers feel safe and comfortable, and emphasizing life skills."',4,14,'all','2026-06-22','2026-06-26',299.0,'per_session','$299','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-furman-university#session-79589-1213283',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','1d8c4d0c-59da-49bc-8bf7-ab48fe741229','nike-soccer-camp-at-furman-university-june-22-26-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
