INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-eff4d358-dc03-5e4e-bbee-cf8f89d0b304','org-12c72d62-3469-5203-869e-1e9fccaacad1','nike-soccer-camp-with-jm-soccer-academy-in-las-vegas-june-22-26-2026','Nike Soccer Camp with JM Soccer Academy in Las Vegas -  (June 22ΓÇô26, 2026)','camp','camp_sports','["soccer"]','Join us this summer at the Nike Soccer Camp at the beautiful Somerset Academy, Skypointe Campus in Las Vegas, NV! Designed for boys and girls ages 4ΓÇô14, this premier camp offers both morning and fullΓÇæday options for an unforgettable soccer experience. The outdoor morning camp runs from 8:00amΓÇô11:00am, perfect for training during the coolest part of the day, while the fullΓÇæday option adds exciting indoor futsal training, giving players fastΓÇæpaced, exclusive play while beating the heat. Directed by JM Soccer Academy and led by former professional player Jordan Murrell, the camp features modern, ageΓÇæappropriate coaching focused on technical skill, confidence, and creativity. A fun 90ΓÇæminute program for ages 4ΓÇô5 introduces the game through movement and foundational skills, while players ages 6ΓÇô14 enjoy highΓÇæenergy training with fastΓÇæpaced drills, smallΓÇæsided games, and competitive play, plus indoor futsal sessions for fullΓÇæday campers. With elite coaching, a premier campus setting, and the proven Nike Soccer Camps experience, this is one of the most exciting soccer camps in Las Vegas. Train. Play. Compete. And take your game to the next level this summer!',4,14,'all','2026-06-22','2026-06-26',155.0,'per_session','$155','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-las-vegas-nv#session-80430-1215078',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','844cad05-a96f-425c-a72c-80f0ff227de7','nike-soccer-camp-with-jm-soccer-academy-in-las-vegas-june-22-26-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
