INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-78e88ec8-f6ea-5219-9ba4-e1aed4b7c8cd','org-8593d604-d64e-553e-96ba-e5c113f1b809','nike-soccer-camp-in-winnetka-june-22-26-2026','Nike Soccer Camp in Winnetka -  (June 22ΓÇô26, 2026)','camp','camp_sports','["soccer"]','Soccer Skill Schools was voted a Top-10 Nike Soccer Camp in 2024 &amp; 2025 by players and parents! Join us for the Nike Soccer Camp in Winnetka with Kyle Jones, Director of Soccer Skill Schools. This camp welcomes players of all abilities, ages 6-16, to develop and refine their technical skills in a dynamic, competitive environment. It''s an exceptional opportunity for any player to train under top coaching professionals while having fun and pushing their game to the next level! Soccer Skill Schools'' "Numbers Approach Methodology" brings world-class skill development methods from Brazil, Holland, England, and Spain directly to the Midwest. The Soccer Skill School approach focuses on the individual player by guiding each athlete toward complete mastery of the ball, empowering them to make their own creative decisions, and equipping them with 65+ individual skills to win the one-on-one competitions that determine every game''s outcome. Led by experienced college coaches and current college players, the Soccer Skill Schools staff brings elite-level expertise and mentorship to every session. Training alongside coaches who compete at the collegiate level gives players invaluable insight into what it takes to elevate their game and succeed at the next level! Hear from Coach Kyle Jones: ΓÇ£We create an environment where players are challenged, supported, and inspired every day. Through high-quality coaching and a love for the game, our goal is to help each athlete build confidence, develop their skills, and leave camp better both on and off the field.ΓÇ¥',6,16,'all','2026-06-22','2026-06-26',529.0,'per_session','$529','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-winnetka-il#session-80860-1215442',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','deeb7b6e-c288-4062-97eb-7d68a7c78dcf','nike-soccer-camp-in-winnetka-june-22-26-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-1f3c8e9e-5472-5906-b47a-2cef1ba10dc0','org-d867ea3b-9483-5f35-9953-139d11157911','nike-soccer-camp-with-prospect-soccer-academy-laguna-niguel-june-22-26-2026','Nike Soccer Camp with Prospect Soccer Academy - Laguna Niguel -  (June 22ΓÇô26, 2026)','camp','camp_sports','["baseball_softball"]','Join us for another amazing summer at the Nike Soccer Camp with Prospect Soccer Academy in Laguna Niguel, led by Coach Harry Forrester. Open to boys and girls ages 6ΓÇô14 of all ability levels, this camp provides an outstanding opportunity for players to develop their technical, tactical, and physical skills while enhancing their overall soccer IQ in a fun, supportive environment. Prospect Soccer Academy is Southern CaliforniaΓÇÖs premier development program, led by former professional players who run a full-time soccer academy in Orange County. With a proven track record of developing players at every level, the coaching staff brings elite playing experience and a modern, player-focused approach to each session. Conveniently located in Laguna Niguel, this camp is ideal for families across Orange County and surrounding communities seeking high-quality youth soccer training close to home. The curriculum blends proven fundamentals with innovative, game-based training to improve technical ability, decision-making, and confidence on the ball. Led by coaches who train players year-round, campers benefit from a consistent, high-level development model that emphasizes accountability, growth, and enjoyment of the game. Join us in Laguna Niguel for a fun and competitive week of soccer, build lasting friendships, and take your game to the next level. Hear from Co-Owner of Prospect Soccer Academy and Camp Director Harry Forrester: "Our camps are delivered by seasoned professional players and coaches who bring real game experience into every session. Built around a proven, development-first philosophy, we prioritize technical excellence through high-repetition training and game-realistic scenarios such as 1v1 and 2v2, helping players build confidence, decision-making, and creativity under pressure. Just as important is the environment we create, structured, supportive, and professionally led, where players are encouraged to take risks, learn from mistakes, and grow. Our goal is for every player to leave not only as a more complete footballer, but with greater confidence, resilience, and a genuine love for the game.ΓÇ¥ Prospect Soccer Academy will be hosting camps in multiple other locations Click here for more info',6,14,'all','2026-06-22','2026-06-26',365.0,'per_session','$365','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-laguna-niguel-orange-county#session-82562-1217831',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','511bd834-dc23-46a5-b7e8-48b40735b8fb','nike-soccer-camp-with-prospect-soccer-academy-laguna-niguel-june-22-26-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
