INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-94a04dd2-cd20-58b6-951a-dfec12684bbe','org-dff86d3e-98c6-501e-be5a-bc99f6bee66c','nike-boys-soccer-camp-at-fairfield-university-june-22-26-2026','Nike Boys Soccer Camp at Fairfield University -  (June 22ΓÇô26, 2026)','camp','camp_sports','["soccer"]','Take your game to the next level this summer at the Nike Boys Soccer Camp at Fairfield University! Designed for boys ages 6ΓÇô14, this unforgettable camp is held on the beautiful Fairfield University campus, where players train on stateΓÇæofΓÇætheΓÇæart athletic facilities that create the perfect environment for growth, competition, and fun. Under the expert leadership of Head Men''s Coach Krystian Witowski and Associate Head Men''s Coach Johnny Raj, campers receive elite instruction from a topΓÇætier Division I coaching staff committed to developing confident, skillful, and passionate players. This highΓÇæenergy day camp is built for athletes of all experience levels, whether your player is stepping onto the field for the first time or striving to sharpen advanced techniques. Each day blends focused skill development with exciting, fastΓÇæpaced gameplay, giving campers the chance to learn, compete, and improve in a positive and supportive environment. With personalized coaching, engaging drills, and an emphasis on both fun and progress, the Nike Boys Soccer Camp at Fairfield University delivers the ultimate summer soccer experience where every player can grow, succeed, and fall in love with the game.',6,14,'all','2026-06-22','2026-0