INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-3301f721-df17-53ca-afc5-49a5bc5f9fbb','org-2523ca92-ceef-5c35-8e88-63de963fd2cd','nike-soccer-camp-at-furman-university-june-22-26-2026-yumx','Nike Soccer Camp at Furman University -  (June 22ΓÇô26, 2026)','camp','camp_sports','["soccer"]','Recognized as a Top-10 Rated Director Awards recipient, the Nike Soccer Camp at Furman University is consistently regarded as one of the premier youth soccer camps in the region and a trusted favorite among families year after year. Set on the beautiful Furman University campus, campers train in an inspiring collegiate environment led by Head Coach Andrew Burr and his experienced coaching staff. With a strong tradition of excellence, the staff brings a high level of expertise, energy, and care to every session. Open to boys and girls ages 4ΓÇô14 of all skill levels, campers are grouped by age and ability to ensure the right balance of challenge and support. The curriculum blends high-quality instruction with a fun, engaging atmosphere, helping players develop their skills, confidence, and love for the game Hear from Head Coach Andrew Burr: "Our coaches are high-energy and excited about creating a fun environment where campers will develop a love for soccer, and enjoy participating with passionate coaches and new friends. In addition to developing soccer players, we enjoy pouring into the kids with an emphasis on teamwork and how to treat others. Our staff consists of highly qualified coaches, but we also have members of our staff who are local school principals, teachers, and college professors. It makes for a well-rounded group that has expertise in working with children. This makes all aspects of the camp, from registration and check-in process, making the campers feel safe and comfortable, and emphasizing life skills."',4,14,'all','2026-06-22','2026-06-26',299.0,'per_session','$299-$429','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-furman-university',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','5aa65e59-0fb2-4c96-9316-7115e3875cf6','nike-soccer-camp-at-furman-university-june-22-26-2026-yumx','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-c73ad0d6-fe86-5d7d-a98b-9b7cbe3ebabd','org-e54e28b3-9423-57ad-9af7-71fd4c3806ac','nike-soccer-camp-in-west-seattle-all-skills-i-june-22-26-2026','Nike Soccer Camp in West Seattle - All Skills I (June 22ΓÇô26, 2026)','camp','camp_sports','["soccer"]','Rich Schreiner was voted a Top-10 Nike Soccer Camp Director in 2025 by players and parents! Join us for an exciting opportunity to elevate your game at the Nike Soccer Camp in West Seattle.. Supervised by the experienced coaching staff and players of Seattle University, this camp offers young soccer enthusiasts the chance to sharpen their skills in a dynamic, inclusive environment. Whether you''re looking to improve technical abilities, tactical understanding, or team coordination, you''ll be guided by passionate coaches in one of Seattle''s most vibrant communities. Don''t miss this chance to train like a pro, learn from the best, and enjoy the beautiful Pacific Northwest surroundings. This camp was held at Georgetown Playfield in 2023 but returned to Delridge Playfield in 2024 and 2025. This summer, we are offering three weeks at Del Ridge and one week at Hiawatha Playfield (July 13-17)',5,12,'all','2026-06-22','2026-06-26',339.0,'per_session','$339-$469','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-seattle-delridge-playfields',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','1fa11b41-5359-4b4f-a508-91fb7f507ec4','nike-soccer-camp-in-west-seattle-all-skills-i-june-22-26-2026','2026-06-