INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-fe18c208-5b93-53f7-a8b2-bc969cfe9a9b','org-b8391502-715c-51d1-93b1-8bbd9ac4518c','nike-soccer-swim-camp-with-hub-sports-at-windgate-ranch-june-22-26-2026','Nike Soccer & Swim Camp with HUB Sports at Windgate Ranch -  (June 22ΓÇô26, 2026)','camp','camp_sports','["soccer"]','Experience the ultimate summer training adventure as HUB Sports and Nike Soccer Camps team up to deliver an energizing mix of outdoor soccer development and refreshing pool time at Windgate Ranch in Scottsdale, AZ. Set on a beautifully maintained event field and featuring a stunning resortΓÇæstyle swimming pool, this camp offers the perfect combination of highΓÇælevel instruction, competitive play, and summer fun. This unique Soccer &amp; Swim program keeps players active, engaged, and cool under the Scottsdale sun. Campers will enjoy a dynamic blend of technical training, smallΓÇæsided games, and skillΓÇæbuilding challenges, followed by scheduled swim sessions designed to help athletes beat the heat, recover, and have fun in a safe and supervised environment. With topΓÇætier coaching, a vibrant outdoor setting, and the added bonus of pool time, this camp delivers an unforgettable summer experience where kids can learn, grow, and stay cool all week long. DonΓÇÖt miss your chance to train, play, and splash your way into the best week of the summer! Note: Swim instruction is available exclusively during summer camp weeks. Soccer/swim availability is listed on the schedule for each session.',5,14,'all','2026-06-22','2026-06-26',299.0,'per_session','$299','https://www.ussportscamps.com/soccer/nike/nike-soccer-swim-camp-hub-sports-windgate-ranch-scottsdale',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','53a576ed-c224-49b4-a974-b0625f6113e9','nike-soccer-swim-camp-with-hub-sports-at-windgate-ranch-june-22-26-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
