INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-1fa6e5ce-148d-5022-9410-aff87281740e','org-12c72d62-3469-5203-869e-1e9fccaacad1','nike-soccer-camp-with-jm-soccer-academy-in-las-vegas-june-22-26-2026-99sr','Nike Soccer Camp with JM Soccer Academy in Las Vegas -  (June 22ΓÇô26, 2026)','camp','camp_sports','["soccer"]','Join us this summer at the Nike Soccer Camp at the beautiful Somerset Academy, Skypointe Campus in Las Vegas, NV! Designed for boys and girls ages 4ΓÇô14, this premier camp offers both morning and fullΓÇæday options for an unforgettable soccer experience. The outdoor morning camp runs from 8:00amΓÇô11:00am, perfect for training during the coolest part of the day, while the fullΓÇæday option adds exciting indoor futsal training, giving players fastΓÇæpaced, exclusive play while beating the heat. Directed by JM Soccer Academy and led by former professional player Jordan Murrell, the camp features modern, ageΓÇæappropriate coaching focused on technical skill, confidence, and creativity. A fun 90ΓÇæminute program for ages 4ΓÇô5 introduces the game through movement and foundational skills, while players ages 6ΓÇô14 enjoy highΓÇæenergy training with fastΓÇæpaced drills, smallΓÇæsided games, and competitive play, plus indoor futsal sessions for fullΓÇæday campers. With elite coaching, a premier campus setting, and the proven Nike Soccer Camps experience, this is one of the most exciting soccer camps in Las Vegas. Train. Play. Compete. And take your game to the next level this summer!',4,14,'all','2026-06-22','2026-06-26',155.0,'per_session','$155-$385','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-las-vegas-nv',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','e35ada6d-a80b-464d-be99-71bf3b0d8810','nike-soccer-camp-with-jm-soccer-academy-in-las-vegas-june-22-26-2026-99sr','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-00782556-cc7b-5816-94d4-1855c673b194','org-8593d604-d64e-553e-96ba-e5c113f1b809','nike-soccer-camp-in-winnetka-june-22-26-2026-gjak','Nike Soccer Camp in Winnetka -  (June 22ΓÇô26, 2026)','camp','camp_sports','["soccer"]','Soccer Skill Schools was voted a Top-10 Nike Soccer Camp in 2024 &amp; 2025 by players and parents! Join us for the Nike Soccer Camp in Winnetka with Kyle Jones, Director of Soccer Skill Schools. This camp welcomes players of all abilities, ages 6-16, to develop and refine their technical skills in a dynamic, competitive environment. It''s an exceptional opportunity for any player to train under top coaching professionals while having fun and pushing their game to the next level! Soccer Skill Schools'' "Numbers Approach Methodology" brings world-class skill development methods from Brazil, Holland, England, and Spain directly to the Midwest. The Soccer Skill School approach focuses on the individual player by guiding each athlete toward complete mastery of the ball, empowering them to make their own creative decisions, and equipping them with 65+ individual skills to win the one-on-one competitions that determine every game''s outcome. Led by experienced college coaches and current college players, the Soccer Skill Schools staff brings elite-level expertise and mentorship to every session. Training alongside coaches who compete at the collegiate level gives players invaluable insight into what it takes to elevate their game and succeed at the next level! Hear from Coach Kyle Jones: ΓÇ£We create an environment where players are challenged, supported, and inspired every day. Through high-quality coaching and a love for the game, our goal is to help each athlete build confidence, develop their skills, and leave camp better both on and off the field.ΓÇ¥',6,16,'all','2026-06-22','2026-06-26',529.0,'per_session','$529','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-winnetka-il',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','7459042c-9707-4b8e-9bc9-b927fbae8309','nike-soccer-camp-in-winnetka-june-22-26-2026-gjak','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-66deedbd-d80a-571e-be9f-b31ddce71146','org-d867ea3b-9483-5f35-9953-139d11157911','nike-soccer-camp-with-prospect-soccer-academy-laguna-niguel-june-22-26-2026-mma5','Nike Soccer Camp with Prospect Soccer Academy - Laguna Niguel -  (June 22ΓÇô26, 2026)','camp','camp_sports','["baseball_softball"]','Join us for another amazing summer at the Nike Soccer Camp with Prospect Soccer Academy in Laguna Niguel, led by Coach Harry Forrester. Open to boys and girls ages 6ΓÇô14 of all ability levels, this camp provides an outstanding opportunity for players to develop their technical, tactical, and physical skills while enhancing their overall soccer IQ in a fun, supportive environment. Prospect Soccer Academy is Southern CaliforniaΓÇÖs premier development program, led by former professional players who run a full-time soccer academy in Orange County. With a proven track record of developing players at every level, the coaching staff brings elite playing experience and a modern, player-focused approach to each session. Conveniently located in Laguna Niguel, this camp is ideal for families across Orange County and surrounding communities seeking high-quality youth soccer training close to home. The curriculum blends proven fundamentals with innovative, game-based training to improve technical ability, decision-making, and confidence on the ball. Led by coaches who train players year-round, campers benefit from a consistent, high-level development model that emphasizes accountability, growth, and enjoyment of the game. Join us in Laguna Niguel for a fun and competitive week of soccer, build lasting friendships, and take your game to the next level. Hear from Co-Owner of Prospect Soccer Academy and Camp Director Harry Forrester: "Our camps are delivered by seasoned professional players and coaches who bring real game experience into every session. Built around a proven, development-first philosophy, we prioritize technical excellence through high-repetition training and game-realistic scenarios such as 1v1 and 2v2, helping players build confidence, decision-making, and creativity under pressure. Just as important is the environment we create, structured, supportive, and professionally led, where players are encouraged to take risks, learn from mistakes, and grow. Our goal is for every player to leave not only as a more complete footballer, but with greater confidence, resilience, and a genuine love for the game.ΓÇ¥ Prospect Soccer Academy will be hosting camps in multiple other locations Click here for more info',6,14,'all','2026-06-22','2026-06-26',365.0,'per_session','$365-$485','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-laguna-niguel-orange-county',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','67c73ecc-13ed-4344-a10d-bcdd757078d0','nike-soccer-camp-with-prospect-soccer-academy-laguna-niguel-june-22-26-2026-mma5','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
