INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-623f9b3e-a7f4-5439-8cb1-b3810f1421ea','org-5a91c87b-3a8f-552c-a038-9389adc4eb3e','nike-soccer-camp-at-ridgefield-academy-june-29-july-2-2026','Nike Soccer Camp at Ridgefield Academy -  (June 29ΓÇôJuly 2, 2026)','camp','camp_sports','["soccer"]','Next Step Training was voted a top 10 Nike Soccer Camp in 2025 by players and parents! Next Step''s soccer camps provide exceptional coaching and a welcoming atmosphere that helps players of all levels grow. With engaging drills, supportive instructors, and a strong emphasis on teamwork, it creates an exciting environment where kids can build confidence, improve their skills, and have a great time on the field. Join us at Nike Soccer Camp this summer at the beautiful Ridgefield Academy in Ridgefield, CT! A yearly favorite that sells out every summer, this camp offers a fun and engaging training experience for players ages 7ΓÇô14. Next Step''s soccer camps provide exceptional coaching and a welcoming atmosphere that helps players of all levels grow. With engaging drills, supportive instructors, and a strong emphasis on teamwork, it creates an exciting environment where kids can build confidence, improve their skills, and have a great time on the field. "At Next Step Soccer, our camps are built around one simple idea, develop the player, not just the session. Every activity is designed to improve how players think, move, and make decisions in the game, while building confidence and a genuine love for soccer. We create a high-energy, supportive environment where players are challenged, coached with purpose, and leave each day better than they arrived, both on and off the field." - Nick Woodruff, Camp Director &amp; Founder, Next Step Training',7,14,'all','2026-06-29','2026-07-02',405.0,'per_session','$405','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-ridgefield-academy#session-83235-1218765',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','ea96b4d6-6458-47c2-853d-190c64be70cc','nike-soccer-camp-at-ridgefield-academy-june-29-july-2-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
