INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-9cab0f78-c807-52e9-9a25-8275def90315','org-f880bfd8-b92f-577c-b380-4e612e8bd12a','nike-soccer-camp-with-ap2t-in-metuchen-half-day-camp-june-29-july-2-2026','Nike Soccer Camp with AP2T in Metuchen - Half Day Camp (June 29ΓÇôJuly 2, 2026)','camp','camp_sports','["soccer"]','Coach Matt Nigro and Nike Soccer Camps are thrilled to bring this camp to Metuchen, NJ for boys and girls ages 6ΓÇô13. Throughout the week, our coaches will follow a progressive, age-appropriate curriculum designed to build skills in a fun and supportive environment. Every camper will finish the week having grown as a soccer player, made new friends, and created lasting memories on and off the field.',6,13,'all','2026-06-29','2026-07-02',249.0,'per_session','$249','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-ap2t-metuchen#session-84358-1220292',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','49598063-df99-40f2-918b-bd8a9c4cbe1d','nike-soccer-camp-with-ap2t-in-metuchen-half-day-camp-june-29-july-2-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-16c5688d-b8c9-5485-9165-186b7cb47882','org-169876b8-cf30-557c-9cd4-5fd8d5aa14cf','nike-baseball-camp-at-university-of-denver-day-camp-june-29-july-2-2026','Nike Baseball Camp at University of Denver - Day Camp (June 29ΓÇôJuly 2, 2026)','camp','camp_sports','["football"]','Nike Baseball Camps is thrilled to return to University of Denver in 2026! Register today and enjoy elite-level training while making memories to last a lifetime. The camp offers a unique opportunity to train under the direction of dedicated coaches and current and former collegiate athletes who serve as counselors. The camp is open to athletes ages 8-17 (varies by program type). Overnight Camp Our overnight camp at University of Denver offers an immersive, on-campus experience where campers reside in the beautiful DU dormitories in adjacent rooms to the coaching staff while training during the daytime hours. The tuition includes all training, lodging, meals, fun evening activities, and more. This program is offered to boys ages 10-17. Day Camp (9:00am ΓÇô 4:00pm) Nike Baseball Camps also offers a day camp program for athletes who do not wish to stay overnight. The day camp program runs 9:00am-4:00pm each day and includes daytime training only. Campers can bring their own lunch or purchase on campus. The day camp program is open to boys ages 8-17. Nike Sports Camp Experience At University of Denver, Nike Sports Camps offers a unique experience with many sports (Baseball, Cross Country, Football, Golf, Softball, and Tennis) operating simultaneously. During the day, the athletes receive sport-specific coaching within their sport focus. In the evening, overnight campers across all sports come together for a special camp-wide experience which includes fun field games, educational seminars, and more. Baseball Complex/Transportation Information The camp will likely utilize the Denver Christian School Baseball Field (as it has in the past) for daily training. Campers and staff are transported by bus to and from the off-campus facilities for training each day. The 2026 athletic facilities will be confirmed in the spring. The Nike Baseball Camp at University of Denver is open to any and all entrants and limited only by number, age and gender. Athletic facilities and coaches are subject to change. The camp is not owned, sponsored, controlled or endorsed by University of Denver.',8,17,'all','2026-06-29','2026-07-02',639.0,'per_session','$639','https://www.ussportscamps.com/baseball/nike/nike-baseball-camp-university-of-denver#session-82183-1217327',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','2d9ab1ce-5693-4e7f-97a4-e7b3b4ca4288','nike-baseball-camp-at-university-of-denver-day-camp-june-29-july-2-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
