INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-f39d8f49-bd22-5e20-b30d-ae4296a45637','org-fcbabba7-5775-5222-b5d7-25e5079b315f','nbc-basketball-day-camp-at-regis-university-complete-skills-jr-june-29-july-2-20','NBC Basketball Day Camp at Regis University - Complete Skills Jr. (June 29ΓÇôJuly 2, 2026)','camp','camp_sports','["baseball_softball"]','NBC Complete Skills Basketball Day Camp is perfect for the beginner to intermediate player, ages 7-15. Regis University Women''s Basketball Coaches will help each athlete improve their fundamental skills and develop a desire to learn. Join us for a fun and encouraging week of basketball training in 2026!',7,15,'all','2026-06-29','2026-07-02',414.0,'per_session','$414','https://www.ussportscamps.com/basketball/nbc/nbc-basketball-camp-at-regis-university#session-84427-1220374',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','6b4445c5-e46c-4134-97fc-92a4f0a92c14','nbc-basketball-day-camp-at-regis-university-complete-skills-jr-june-29-july-2-20','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-f01c64c0-6cfc-5fac-b8fb-c7ea551702b4','org-216aa692-d2de-55af-aa3b-4d66a5b27bef','nike-tennis-camp-at-university-of-denver-day-overnight-camp-june-29-july-2-2026','Nike Tennis Camp at University of Denver - Day/Overnight Camp (June 29ΓÇôJuly 2, 2026)','camp','camp_sports','["football"]','Nike Tennis Camps is thrilled to return to University of Denver in Summer 2026! Register today and enjoy elite-level training while making memories to last a lifetime. The camp offers a unique opportunity to train under the direction of dedicated coaches and current and former collegiate athletes who serve as counselors. The camp is open to athletes ages 10-17. Overnight Camp Our overnight camp at University of Denver offers an immersive, on-campus experience where campers reside in the beautiful DU dormitories in adjacent rooms to the coaching staff while training during the daytime hours. The tuition includes all training, housing, meals, fun evening activities, as well as college recruiting seminars on Tuesday evening (parents are encouraged to attend the seminars). Day Camp (9:00am-4:00pm) Nike Tennis Camps also offers a summer day camp program for athletes who do not wish to stay overnight. This program runs 9:00am-4:00pm each day and includes daytime training only. Campers can bring their own lunch or purchase on campus. Nike Sports Camp Experience At University of Denver, Nike Sports Camps offers a unique experience with many sports (Baseball, Cross Country, Football, Golf, Softball, and Tennis) operating simultaneously. During the day, the athletes receive sport-specific coaching within their sport focus. In the evening, overnight campers across all sports come together for a special camp-wide experience which includes fun field games, educational seminars, and more. Tennis Complex/Transportation Information The camp utilizes a mix of the Englewood High School (3.5 miles away) and Denver South High School (1.5 miles away) tennis facilities off-campus. Campers and staff are transported to and from the tennis complexes for training sessions each day. The Nike Tennis Camp at University of Denver is open to any and all entrants and limited only by number, age and gender. Athletic facilities and coaches are subject to change. The camp is not owned, sponsored, controlled or endorsed by University of Denver.',10,17,'all','2026-06-29','2026-07-02',889.0,'per_session','$889','https://www.ussportscamps.com/tennis/nike/nike-tennis-camp-university-of-denver#session-81818-1216853',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','201da10c-375d-4429-896e-de95cb3d953e','nike-tennis-camp-at-university-of-denver-day-overnight-camp-june-29-july-2-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
