INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-5ced9f40-3041-597f-89df-ebf1c83fd5dc','org-1ab42458-e0b9-558b-b7bf-6979671e2609','nike-baseball-camp-at-san-marcos-high-school-june-29-july-2-2026','Nike Baseball Camp at San Marcos High School -  (June 29ΓÇôJuly 2, 2026)','camp','camp_sports','["baseball_softball"]','Join our Nike Baseball Camp at San Marcos High School in Santa Barbara, California! Athletes of all abilities are encouraged to join us this winter to gain valuable baseball experience and create lasting memories. Quality facilities, knowledgeable coaches, and a positive environment are characteristics of this camp. Whether it be long-term or short-term goals you have set for yourself, Coach Tom Myers and staff are determined to help you get a step closer to your accomplishments. Directing the camp is Tom Myers, an Area Scout for the Los Angeles Dodgers. The goal is for every camper to take their game to the next level, create friendships, and have a great time.',8,10,'all','2026-06-29','2026-07-02',429.0,'per_session','$429','https://www.ussportscamps.com/baseball/nike/nike-baseball-camp-san-marcos-high-school',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','dbcb44ee-ea06-443f-8bfa-3d47f46c0554','nike-baseball-camp-at-san-marcos-high-school-june-29-july-2-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
