INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-46edc04b-ef5e-599a-b563-c06713b39c7b','org-f0b2f248-b8ea-5153-be13-963e6a2358b4','nike-baseball-camp-st-ignatius-college-preparatory-june-29-july-2-2026-gba0','Nike Baseball Camp St. Ignatius College Preparatory -  (June 29ΓÇôJuly 2, 2026)','camp','camp_sports','["baseball_softball"]','The Nike Baseball Camps at St. Ignatius College Preparatory are sure to be a Bay Area favorite this summer. Camp Director, Brian Pollzzie, will lead two weeks of summer camp hosted at Fairmont Field. The camps will focus on all aspects of the game from individual position work, situation drills, hitting stations, and simulated games! Campers are sure to make new friends and have a memorable experience this summer!',8,14,'all','2026-06-29','2026-07-02',294.0,'per_session','$294-$464','https://www.ussportscamps.com/baseball/nike/nike-baseball-camp-st.-ignatius-college-preparatory',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','b7585d6a-b6a5-40b2-bd09-4688a1c3617c','nike-baseball-camp-st-ignatius-college-preparatory-june-29-july-2-2026-gba0','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-4197d8e9-9be5-543b-af3f-4c680b118d7d','org-169876b8-cf30-557c-9cd4-5fd8d5aa14cf','nike-baseball-camp-at-university-of-denver-day-camp-june-29-july-2-2026-9w2d','Nike Baseball Camp at University of Denver - Day Camp (June 29ΓÇôJuly 2, 2026)','camp','camp_sports','["football"]','Nike Baseball Camps is thrilled to return to University of Denver in 2026! Register today and enjoy elite-level training while making memories to last a lifetime. The camp offers a unique opportunity to train under the direction of dedicated coaches and current and former collegiate athletes who serve as counselors. The camp is open to athletes ages 8-17 (varies by program type). Overnight Camp Our overnight camp at University of Denver offers an immersive, on-campus experience where campers reside in the beautiful DU dormitories in adjacent rooms to the coaching staff while training during the daytime hours. The tuition includes all training, lodging, meals, fun evening activities, and more. This program is offered to boys ages 10-17. Day Camp (9:00am ΓÇô 4:00pm) Nike Baseball Camps also offers a day camp program for athletes who do not wish to stay overnight. The day camp program runs 9:00am-4:00pm each day and includes daytime training only. Campers can bring their own lunch or purchase on campus. The day camp program is open to boys ages 8-17. Nike Sports Camp Experience At University of Denver, Nike Sports Camps offers a unique experience with many sports (Baseball, Cross Country, Football, Golf, Softball, and Tennis) operating simultaneously. During the day, the athletes receive sport-specific coaching within their sport focus. In the evening, overnight campers across all sports come together for a special camp-wide experience which includes fun field games, educational seminars, and more. Baseball Complex/Transportation Information The camp will likely utilize the Denver Christian School Baseball Field (as it has in the past) for daily training. Campers and staff are transported by bus to and from the off-campus facilities for training each day. The 2026 athletic facilities will be confirmed in the spring. The Nike Baseball Camp at University of Denver is open to any and all entrants and limited only by number, age and gender. Athletic facilities and coaches are subject to change. The camp is not owned, sponsored, controlled or endorsed by University of Denver.',8,17,'all','2026-06-29','2026-07-02',639.0,'per_session','$639','https://www.ussportscamps.com/baseball/nike/nike-baseball-camp-university-of-denver',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','f82bcbb7-3981-4aa5-8217-9a25a6fc485e','nike-baseball-camp-at-university-of-denver-day-camp-june-29-july-2-2026-9w2d','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
