INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-e05cbb32-df89-5b89-9952-8348715b3fa0','org-991fb1c2-d36b-5848-bc46-4f39683ca2c8','nike-volleyball-camp-at-community-wellness-center-with-volleyball-elite-training','Nike Volleyball Camp at Community Wellness Center with Volleyball Elite Training - All Skills Camp (June 29ΓÇôJuly 2, 2026)','camp','camp_sports','["volleyball"]','Come elevate your game with the Volleyball Elite Training coaches and get the opportunity to be coached by LOVB Atlanta and Atlanta Vibe players! Our volleyball camp offers a fun and competitive environment where athletes will receive personalized coaching, improve their techniques, and engage in team-building activities. We will focus on developing key skills such as serving, passing, setting, hitting, blocking, and defensive strategies.',11,15,'all','2026-06-29','2026-07-02',529.0,'per_session','$529','https://www.ussportscamps.com/volleyball/nike/nike-volleyball-camp-community-wellness-center',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','59ff365d-a918-43f4-823d-dffe96225e7b','nike-volleyball-camp-at-community-wellness-center-with-volleyball-elite-training','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-c9896d72-1d74-5c4a-9817-56953d68c289','org-9a498801-b7fc-5aa6-9fe0-4931851f138c','nike-volleyball-camp-at-avenues-the-world-school-all-skills-camp-june-29-july-2-','Nike Volleyball Camp at Avenues The World School - All Skills Camp (June 29ΓÇôJuly 2, 2026)','camp','camp_sports','["volleyball"]','Join us for a fun and active volleyball camp at Avenues The World School in New York City! Open to boys and girls ages 10ΓÇô17, this camp is a great way for players to spend time on the court, learn new skills, and enjoy the game in a positive, supportive setting. Campers will work with experienced coaches through a mix of drills, games, and team play. Whether trying something new or continuing to build on existing skills, athletes can expect a high-energy camp experience filled with learning, movement, and plenty of volleyball fun.',10,17,'all','2026-06-29','2026-07-02',699.0,'per_session','$699','https://www.ussportscamps.com/volleyball/nike/nike-volleyball-camp-avenues-world-school',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','6a60f711-e8a5-47a4-8bd0-1cb5f71ea2f4','nike-volleyball-camp-at-avenues-the-world-school-all-skills-camp-june-29-july-2-','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-1a008e85-c540-5e56-a5b2-fc1c4cab77a2','org-c21c2216-0bcb-551d-b7db-1a1c7f594ecb','nike-soccer-camp-st-ignatius-college-preparatory-june-29-july-2-2026','Nike Soccer Camp St. Ignatius College Preparatory -  (June 29ΓÇôJuly 2, 2026)','camp','camp_sports','["soccer"]','Team up with the St. Ignatius soccer coaching staff this summer for these Nike Soccer Camps held at SI in San Francisco. This popular Bay Area Camp is a perfect opportunity for players of all abilities to work with a top coaching staff to refine technique, develop new skills and work on every aspect of the game, in a fun and competitive enviroment.',7,14,'all','2026-06-29','2026-07-02',294.0,'per_session','$294-$464','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-st.-ignatius-college-preparatory',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','43a9f504-2d5f-4757-877c-830586df6ac8','nike-soccer-camp-st-ignatius-college-preparatory-june-29-july-2-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-d5388f52-95a8-59f6-8882-e4160ee2b203','org-5a91c87b-3a8f-552c-a038-9389adc4eb3e','nike-soccer-camp-at-ridgefield-academy-june-29-july-2-2026-xryp','Nike Soccer Camp at Ridgefield Academy -  (June 29ΓÇôJuly 2, 2026)','camp','camp_sports','["soccer"]','Next Step Training was voted a top 10 Nike Soccer Camp in 2025 by players and parents! Next Step''s soccer camps provide exceptional coaching and a welcoming atmosphere that helps players of all levels grow. With engaging drills, supportive instructors, and a strong emphasis on teamwork, it creates an exciting environment where kids can build confidence, improve their skills, and have a great time on the field. Join us at Nike Soccer Camp this summer at the beautiful Ridgefield Academy in Ridgefield, CT! A yearly favorite that sells out every summer, this camp offers a fun and engaging training experience for players ages 7ΓÇô14. Next Step''s soccer camps provide exceptional coaching and a welcoming atmosphere that helps players of all levels grow. With engaging drills, supportive instructors, and a strong emphasis on teamwork, it creates an exciting environment where kids can build confidence, improve their skills, and have a great time on the field. "At Next Step Soccer, our camps are built around one simple idea, develop the player, not just the session. Every activity is designed to improve how players think, move, and make decisions in the game, while building confidence and a genuine love for soccer. We create a high-energy, supportive environment where players are challenged, coached with purpose, and leave each day better than they arrived, both on and off the field." - Nick Woodruff, Camp Director &amp; Founder, Next Step Training',7,14,'all','2026-06-29','2026-07-02',405.0,'per_session','$405-$565','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-ridgefield-academy',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','5d3bb5ce-44f7-45b5-a760-4dc787fd3891','nike-soccer-camp-at-ridgefield-academy-june-29-july-2-2026-xryp','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-6c437987-9d11-5f0d-bd94-57fa44f222ab','org-eb67b7d9-3db5-5ff7-9824-91917a1ee644','pearl-street-ymca-all-week-camp-holiday-hoopla','Pearl Street YMCA All Week Camp - Holiday Hoopla','camp','camp_general',NULL,'Week 2 of Pearl Street YMCA Summer Day Camp. Holiday-themed games and group activities run Tuesday through Friday (closed July 4 weekend). Campers age 7 and up pick a Specialty Camp from options like Backyard Games, Creative Creations, Game Show, Lego Creations, Soccer, or Ynews. Day runs 8:45 am to 4 pm with optional 7 am to 6 pm extended care. Pack a nut-free lunch.',5,12,'all','2026-06-30','2026-07-03',247.0,'per_session','$247 members, $352 community members','https://www.ymcapkc.org/camps/summer-day-camp/pearl-street-family-ymca',NULL,'open','day',0,1,NULL,NULL,'scraped','active',60,NULL,'live','58207ff9-7d11-4cfc-a718-dfc545eda88a','pearl-street-ymca-all-week-camp-holiday-hoopla','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
