INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-acbd32c3-abc1-5935-b956-5cf7defb0025','org-c6a19cf4-2d29-5bed-b166-354120bb638a','summer-camp-water-week-1-tacoma','Summer Camp - Water Week 1 - Tacoma','camp','camp_general',NULL,'Five-day Tacoma day camp at the Mountaineers Tacoma Program Center for kids in grades 1-7 with a focus on water skills and safety. Campers try river paddling on a guided river float field trip (Tuesday or Wednesday), tide pooling, climbing, hiking, navigation, first aid, and knots. Friday meets at Point Defiance Park. Camp runs 8:30am to 4:30pm Monday through Thursday. Led by Sarah Holt.',6,13,'beginner','2026-06-29','2026-07-03',410.0,'per_session','$410 members / $435 guests','https://www.mountaineers.org/locations-lodges/tacoma-branch/committees/tacoma-youth-outreach-committee/course-templates/water-week-tacoma/summer-camp-water-week-1-tacoma-2026',NULL,'waitlist','day',0,0,NULL,NULL,'scraped','active',90,'mountaineers.org','live','4bb20a07-4da8-490b-9e8a-177b34c947e3','summer-camp-water-week-1-tacoma','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
