INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-104f4596-612a-5176-8202-057e276bdb8a','org-cf77187d-333a-57bf-9bfa-5ae9d88e4d32','nike-soccer-camp-at-hilltop-heritage-middle-school-june-29-july-3','Nike Soccer Camp at Hilltop Heritage Middle School (June 29 - July 3)','camp','camp_sports','["soccer"]','Nike Soccer Camp run by US Sports Camps and directed by former Tacoma Stars professional Alex Megson. Five-day summer day camp at Hilltop Heritage Middle School. Two programs run side by side: Early Childhood Development for ages 5-6 (half day, 9 AM-12 PM, $280) and Player Development for ages 7-15 with half day ($280) or full day 9 AM-3 PM ($390). Campers are grouped by age, ability, and experience and work on technical training, small-sided games, and tactical work. Lunch is not provided.',5,15,'all','2026-06-29','2026-07-03',280.0,'per_session','$280-$390','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-hilltop-heritage-middle-school',NULL,'open','day',0,0,NULL,NULL,'scraped','active',90,'ussportscamps.com','live','1a658d22-56ac-4d39-b503-9f0f854b9f34','nike-soccer-camp-at-hilltop-heritage-middle-school-june-29-july-3','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-c3fe7ef1-ebd5-539f-a6bd-7a5b5ed6018a','org-59572b22-1a89-502e-beb2-7bf230a929f3','nike-soccer-camp-with-tacoma-stars-at-sera-sports-complex','Nike Soccer Camp with Tacoma Stars at SERA Sports Complex','camp','camp_sports','["soccer"]','Nike Soccer Camp coached by Tacoma Stars staff at SERA Sports Complex in Tacoma, run through US Sports Camps. Five-day day camp on turf with two programs: Future Stars for ages 4-6 (half day, $280) and Player Development for ages 7-15 (half day $280 or full day $390). Players are grouped by age and ability with a focus on indoor-style technical training, small-sided games, and tactical work.',4,15,'all','2026-06-29','2026-07-03',280.0,'per_session','$280-$390','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-tacoma-stars-sera',NULL,'open','day',0,0,NULL,NULL,'scraped','active',90,'ussportscamps.com','live','33d1ded7-d251-4962-8f3b-1b719dd024da','nike-soccer-camp-with-tacoma-stars-at-sera-sports-complex','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-6edfd83c-966b-51b3-90d1-3df8cb3be436','org-c2e1a281-f4f4-51d8-aa6c-a8644c35d87c','nike-soccer-camp-at-lake-forest-academy-day-camp-ii-june-29-july-3-2026','Nike Soccer Camp at Lake Forest Academy - Day Camp II (June 29ΓÇôJuly 3, 2026)','camp','camp_sports','["soccer"]','Soccer Skill Schools was voted a Top-10 Nike Soccer Camp in 2024 &amp; 2025 by players and parents! Join us for the Nike Soccer Camp at Lake Forest Academy with Kyle Jones, Director of Soccer Skill Schools. This camp welcomes players of all abilities, ages 6-16, to develop and refine their technical skills in a dynamic, competitive environment. It''s an exceptional opportunity for any player to train under top coaching professionals while having fun and pushing their game to the next level! Soccer Skill Schools'' "Numbers Approach Methodology" brings world-class skill development methods from Brazil, Holland, England, and Spain directly to the Midwest. The Soccer Skill School approach focuses on the individual player by guiding each athlete toward complete mastery of the ball, empowering them to make their own creative decisions, and equipping them with 65+ individual skills to win the one-on-one competitions that determine every game''s outcome. Led by experienced college coaches and current college players, the Soccer Skill Schools staff brings elite-level expertise and mentorship to every session. Training alongside coaches who compete at the collegiate level gives players invaluable insight into what it takes to elevate their game and succeed at the next level! Hear from Coach Kyle Jones: ΓÇ£We create an environment where players are challenged, supported, and inspired every day. Through high-quality coaching and a love for the game, our goal is to help each athlete build confidence, develop their skills, and leave camp better both on and off the field.ΓÇ¥',6,16,'all','2026-06-29','2026-07-03',549.0,'per_session','$549','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-lake-forest#session-79578-1213264',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','30b449f4-72a4-4c4d-b583-4a22e4932074','nike-soccer-camp-at-lake-forest-academy-day-camp-ii-june-29-july-3-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-08c0e9ac-a841-58f2-a205-5eb408ea2d6d','org-bf9555cb-c181-55e5-8ec5-87301ecfac1b','nike-indoor-soccer-camp-with-hub-sports-at-rancho-solano-prep-school-indoor-camp','Nike Indoor Soccer Camp with HUB Sports at Rancho Solano Prep School - Indoor Camp (June 29ΓÇôJuly 3, 2026)','camp','camp_sports','["soccer"]','Hosted at the great location of Rancho Solano Preparatory School, this coed indoor camp for players ages 5ΓÇô14 delivers a fun, highΓÇæenergy soccer experience in a fully airΓÇæconditioned indoor gym, allowing players to train comfortably while beating the Arizona summer heat. Led by HUB Sports, ArizonaΓÇÖs renowned leader in youth development training, this camp brings together expert coaching, engaging skill instruction, and exciting game play in an environment designed for players of all ability levels. Campers will build confidence, sharpen technical skills, and enjoy the game through ageΓÇæappropriate training and smallΓÇæsided gamesΓÇöall while staying cool indoors. Since 2002, HUB Sports has set the standard in youth athletics across Arizona, creating inclusive, highΓÇæquality programs that inspire a lifelong love for sports. Partnering with Nike Sports Camps, HUB Sports delivers a memorable, professionally run soccer camp experience that families return to year after year. If youΓÇÖre looking for a fun, safe, and exciting way to spend the summer in Scottsdale, this indoor Nike Soccer Camp is the perfect place to play, learn, and fall in love with the game.',5,14,'all','2026-06-29','2026-07-03',399.0,'per_session','$399','https://www.ussportscamps.com/soccer/nike/nike-indoor-soccer-camp-hub-sports-rancho-solano#session-82835-1218211',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','7ec7a52a-1460-4a89-99a0-f2d152662f72','nike-indoor-soccer-camp-with-hub-sports-at-rancho-solano-prep-school-indoor-camp','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
