INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-813332c0-3488-56b8-95f7-927568fdb764','org-a2a74987-8157-5137-aaa9-393368df9032','nike-soccer-camp-at-sofive-elkins-park-day-camp-june-29-july-3-2026','Nike Soccer Camp at Sofive Elkins Park - Day Camp (June 29ΓÇôJuly 3, 2026)','camp','camp_sports','["baseball_softball"]','Experience an actionΓÇæpacked week of worldΓÇæclass soccer training at the Nike Soccer Camp at Sofive Elkins Park in Elkins Park, Pennsylvania ΓÇö led by the internationally respected Gold &amp; Gray Soccer Academy. Founded by professional footballers David Gold and Ross Gray, Gold &amp; Gray has earned a reputation as one of ScotlandΓÇÖs premier development academies, trusted by MLS athletes and European professionals for cultivating top-tier youth talent. Open to boys and girls ages 6ΓÇô16 of all experience levels, this camp delivers an elite training environment inside a modern, state-of-the-art Sofive facility. Players benefit from a low coachΓÇætoΓÇæcamper ratio and receive personalized guidance from UEFAΓÇælicensed coaches who have trained youth athletes from renowned clubs including Celtic, Rangers, Hearts, and Hibs. Throughout the week, campers sharpen their technical skills, improve their speed of play and decision-making, and develop confidence through highΓÇæenergy sessions that blend professionalism with fun. ItΓÇÖs a chance to train like the pros, push your game forward, and experience the intensity and excitement of a true academy-style environment. Whether you''re aiming to elevate your game, build a stronger foundation, or simply enjoy an unforgettable week of soccer, this Nike Soccer Camp is the perfect opportunity to take your skills to the next level.',6,16,'all','2026-06-29','2026-07-03',265.0,'per_session','$265','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-sofive-elkins-park#session-83639-1219304',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','56ac579f-654a-4f58-8fef-47b8f74fd67b','nike-soccer-camp-at-sofive-elkins-park-day-camp-june-29-july-3-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
