INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-36df08b6-d339-514d-bd40-753d64c65908','org-7470a826-0f23-58f0-819e-0483841f8c72','nike-soccer-camp-in-haverhill-june-29-july-3-2026','Nike Soccer Camp in Haverhill -  (June 29ΓÇôJuly 3, 2026)','camp','camp_sports','["soccer"]','Get ready for an exciting week of soccer at the Nike Soccer Camp in Haverhill, MA! Led by Mirko Nufi, MenΓÇÖs Assistant Coach at Merrimack College, and supported by an experienced coaching staff, this camp offers young athletes the perfect blend of highΓÇæquality instruction and upbeat, supportive training. Designed for boys and girls ages 6ΓÇô16, the camp welcomes players of all skill levels, from beginners eager to learn the game to advanced athletes looking to sharpen their technique. Through a fun and challenging mix of drills, competitive games, and smallΓÇæsided play, every participant will build confidence, advance their skills, and deepen their love for soccer. Hosted at Haverhill High School, the camp delivers topΓÇætier coaching in a convenient local setting. Campers will enjoy indoor lunch breaks in the school cafeteria or gymnasium, with water stations available on the field throughout the day. Shaded gazebos provide relief from the sun, and nearby portable restrooms ensure comfort and convenience for all. Join us for a week filled with new friends, inspiring coaches, and unforgettable memories, all while taking your game to the next level!',6,16,'all','2026-06-29','2026-07-03',359.0,'per_session','$359','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-haverhill-ma#session-84107-1219945',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','33a27c34-be43-45bd-8ce2-0d0bb12f4dbe','nike-soccer-camp-in-haverhill-june-29-july-3-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
