INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-9b9177ab-60be-5d4b-aaad-b78263b105db','org-a90cd8aa-dc96-5aa7-a89c-67466d6c61c8','nike-soccer-camp-in-romeoville-june-29-july-3-2026','Nike Soccer Camp in Romeoville -  (June 29ΓÇôJuly 3, 2026)','camp','camp_sports','["soccer"]','Soccer Skill Schools was voted a Top-10 Nike Soccer Camp in 2024 &amp; 2025 by players and parents! Join us for the Nike Soccer Camp in Romeoville, Illinois, led by Kyle Jones, Director of Soccer Skill Schools. This camp is open to players of all abilities ages 6ΓÇô16, this camp focuses on developing and refining technical skills in a fun, competitive training environment. Campers will learn from experienced coaching professionals while building confidence, improving their game, and enjoying one of the top youth soccer training experiences in the Romeoville area. Soccer Skill Schools'' "Numbers Approach Methodology" brings world-class skill development methods from Brazil, Holland, England, and Spain directly to the Midwest. The Soccer Skill School approach focuses on the individual player by guiding each athlete toward complete mastery of the ball, empowering them to make their own creative decisions, and equipping them with 65+ individual skills to win the one-on-one competitions that determine every game''s outcome. Led by experienced college coaches and current college players, the Soccer Skill Schools staff brings elite-level expertise and mentorship to every session. Training alongside coaches who compete at the collegiate level gives players invaluable insight into what it takes to elevate their game and succeed at the next level! Hear from Coach Kyle Jones: ΓÇ£We create an environment where players are challenged, supported, and inspired every day. Through high-quality coaching and a love for the game, our goal is to help each athlete build confidence, develop their skills, and leave camp better both on and off the field.ΓÇ¥',6,16,'all','2026-06-29','2026-07-03',370.0,'per_session','$370','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-romeoville#session-84453-1220408',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','b9fbef3d-83d2-4a50-809a-b26253f4c691','nike-soccer-camp-in-romeoville-june-29-july-3-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-c754fe6f-dc71-5d02-96fa-b1b1b9b48337','org-8c615665-7aca-5a51-94ab-a589c271f6c1','nike-soccer-camp-in-arcadia-los-angeles-june-29-july-3-2026','Nike Soccer Camp in Arcadia - Los Angeles -  (June 29ΓÇôJuly 3, 2026)','camp','camp_sports','["soccer"]','Experience highΓÇælevel training and nonstop fun this summer at the Nike Soccer Camp at Arcadia High School. Designed to help players grow both technically and tactically, this camp offers an exciting, confidenceΓÇæbuilding environment where athletes can sharpen their skills and elevate their overall game. The camp is directed by Chris Ferrer, respected youth development expert, Arcadia High School Boys Head Coach, and leader within Los Angeles Soccer Camps, one of Southern CaliforniaΓÇÖs most trusted youth soccer organizations. Supported by LA Soccer CampsΓÇÖ proven playerΓÇædevelopment model, campers will train in a structured yet fun setting that emphasizes technical excellence, game understanding, and competitive play. Open to boys and girls ages 6ΓÇô14 of all ability levels, the program features a low coachΓÇætoΓÇæcamper ratio, ensuring every player receives personalized instruction, plenty of touches on the ball, and meaningful feedback. Through dynamic drills, smallΓÇæsided games, and match play, campers will develop new skills, refine technique, boost confidence, and leave camp better prepared for the next stage of their soccer journey.',6,14,'all','2026-06-29','2026-07-03',330.0,'per_session','$330','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-arcadia-los-angeles#session-85020-1221209',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','0d58e2d6-aa16-4e2b-b8ba-8be1cdf540c9','nike-soccer-camp-in-arcadia-los-angeles-june-29-july-3-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
