INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-b7089b09-7613-5abf-a0a9-e8493feaa030','org-c2e1a281-f4f4-51d8-aa6c-a8644c35d87c','nike-soccer-camp-at-lake-forest-academy-day-camp-ii-june-29-july-3-2026-713y','Nike Soccer Camp at Lake Forest Academy - Day Camp II (June 29ΓÇôJuly 3, 2026)','camp','camp_sports','["soccer"]','Soccer Skill Schools was voted a Top-10 Nike Soccer Camp in 2024 &amp; 2025 by players and parents! Join us for the Nike Soccer Camp at Lake Forest Academy with Kyle Jones, Director of Soccer Skill Schools. This camp welcomes players of all abilities, ages 6-16, to develop and refine their technical skills in a dynamic, competitive environment. It''s an exceptional opportunity for any player to train under top coaching professionals while having fun and pushing their game to the next level! Soccer Skill Schools'' "Numbers Approach Methodology" brings world-class skill development methods from Brazil, Holland, England, and Spain directly to the Midwest. The Soccer Skill School approach focuses on the individual player by guiding each athlete toward complete mastery of the ball, empowering them to make their own creative decisions, and equipping them with 65+ individual skills to win the one-on-one competitions that determine every game''s outcome. Led by experienced college coaches and current college players, the Soccer Skill Schools staff brings elite-level expertise and mentorship to every session. Training alongside coaches who compete at the collegiate level gives players invaluable insight into what it takes to elevate their game and succeed at the next level! Hear from Coach Kyle Jones: ΓÇ£We create an environment where players are challenged, supported, and inspired every day. Through high-quality coaching and a love for the game, our goal is to help each athlete build confidence, develop their skills, and leave camp better both on and off the field.ΓÇ¥',6,16,'all','2026-06-29','2026-07-03',549.0,'per_session','$549','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-lake-forest',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','be41a877-5031-4bf1-8795-61eda7dfb6d1','nike-soccer-camp-at-lake-forest-academy-day-camp-ii-june-29-july-3-2026-713y','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-ee76174f-273c-5365-84b1-91d0601fd10a','org-ff7f2f42-57ca-5755-abd1-1b8694005223','nike-soccer-camp-in-moorestown-day-camp-june-29-july-3-2026','Nike Soccer Camp in Moorestown - Day Camp (June 29ΓÇôJuly 3, 2026)','camp','camp_sports','["soccer"]','Join Barry Lynch and his coaching staff at the Nike Soccer Camp in Moorestown. Located at Moorestown High School in Moorestown, NJ, this camp offers the perfect blend of training and gameplay. The focus at camp will be on player development, each camper will refine their technique, learn new skills, compete in games and drills, have fun, and make new friends. This youth soccer camp provides the perfect blend of instruction and fun! Make friends and create memories with our team that will last a lifetime! Sure to be a summer highlight, these camps offer a unique opportunity for aspiring soccer players aged 5-16. Throughout the week campers learn new skills, perfect techniques, increase game knowledge, make new friends and have fun playing soccer!',5,16,'all','2026-06-29','2026-07-03',285.0,'per_session','$285-$395','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-moorestown-new-jersey',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','31732125-13d7-4d6c-bd85-ec30f8093c5d','nike-soccer-camp-in-moorestown-day-camp-june-29-july-3-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-eab92974-ac39-5008-97f2-7fd3c01ad98e','org-962b51d7-ac13-51a1-b88a-f14370554d73','nike-soccer-camp-at-occidental-college-june-29-july-3-2026','Nike Soccer Camp at Occidental College -  (June 29ΓÇôJuly 3, 2026)','camp','camp_sports','["soccer"]','Join us for an exciting week at Nike Soccer Camp at Occidental College in Los Angeles, CA, home to one of the most respected collegiate soccer environments in Southern California. Campers will train under Camp Director Rod Lafaurie and the Occidental MenΓÇÖs Soccer staff, recently named SCIAC Coaching Staff of the Year, and recognized nationally with a Top-10 Rated Director Award.Set on the beautiful Occidental College campus, this camp offers a true collegiate training experience, giving players access to high-quality facilities and an inspiring college soccer setting in the heart of Los Angeles.The curriculum blends traditional and modern coaching methodologies to help every player take the next step in their development. Players will build core technical skills, improve tactical understanding, and elevate their overall soccer IQ in a fun, structured, and competitive environment. Summer sessions also include access to the on-campus swimming pool, rounding out the full camp experience.Whether your child is just beginning their soccer journey or looking to sharpen competitive edge, this Nike Soccer Camp delivers a high-level and memorable experience where players grow their game, build confidence, and form lasting friendships.Hear from Rod Lafaurie: "Our goal is simple: we want every player to feel safe, have fun, and love every day they spend with us. By training within a curriculum designed by college soccer coaches and utilizing our elite facilities, from the field to the pool, we create a high-energy environment that challenges players to grow. We pride ourselves on clear communication and a development-focused approach that builds technical skills and character, ensuring your child leaves with a deeper love for the game and the confidence to take their next step in soccer."',6,16,'all','2026-06-29','2026-07-03',345.0,'per_session','$345-$465','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-los-angeles-occidental-college',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','9ec54ccf-9d52-4410-8674-bdd221ed2358','nike-soccer-camp-at-occidental-college-june-29-july-3-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
