ll','2026-06-29','2026-07-03',399.0,'per_session','$399','https://www.ussportscamps.com/soccer/nike/nike-indoor-soccer-camp-hub-sports-rancho-solano',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','82263bd1-1382-4b37-bb5b-11a0da597ad5','nike-indoor-soccer-camp-with-hub-sports-at-rancho-solano-prep-school-indoor-camp-moda','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
