INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-8ce351b0-fdc2-564c-a262-df8de794e726','org-cca4924d-df57-53c8-9f03-2abc1c656abf','nike-soccer-camp-at-regis-university-june-29-july-3-2026','Nike Soccer Camp at Regis University -  (June 29ΓÇôJuly 3, 2026)','camp','camp_sports','["soccer"]','Join us for an incredible week of camp at Nike Soccer Camp at Regis University in Denver, Colorado. Team up with Head Men''s Soccer Coach Taylor Diem for the ultimate soccer training experience in Denver, CO! Our camp offers a dynamic blend of traditional and modern coaching methods, ensuring that every camper has the opportunity to elevate their soccer skills to new heights in a fun environment. Held at Regis University''s top class soccer facilities, this youth soccer camp provides top-notch instruction and a whole lot of fun! Don''t miss out on this opportunity to make lasting memories and friendships with our team!',6,16,'all','2026-06-29','2026-07-03',355.0,'per_session','$355-$485','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-regis-university-denver',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','dce9204e-12ef-420a-8dcb-02a219e2475c','nike-soccer-camp-at-regis-university-june-29-july-3-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-405ca676-bffa-559a-ac72-1683109c980e','org-4e411e07-ded4-536e-8c52-b81389c0a5b1','nike-soccer-camp-with-prospect-soccer-academy-4s-ranch-sports-park-june-29-july--5y1g','Nike Soccer Camp with Prospect Soccer Academy - 4S Ranch Sports Park -  (June 29ΓÇôJuly 3, 2026)','camp','camp_sports','["baseball_softball"]','Join us for another exciting summer at the Nike Soccer Camp with Prospect Soccer Academy in 4S Ranch, San Diego, held at 4S Ranch Sports Park. Led by Coach Harry Forrester and the Prospect Soccer Academy staff, this returning camp welcomes boys and girls ages 6ΓÇô14 of all ability levels for a high-quality training experience focused on technical development, tactical understanding, and overall soccer IQ in a fun and supportive environment.Prospect Soccer Academy is a premier Southern California development program led by former professional players who run a full-time academy dedicated to developing players at every level. With a wealth of playing and coaching experience, the staff delivers a high-energy, player-centered environment built around long-term growth, confidence, and enjoyment of the game.Set at 4S Ranch Sports Park, a top youth soccer facility in San Diego, players train on quality fields in a professional yet welcoming setting. The curriculum blends proven fundamentals with modern, game-based training designed to improve decision-making, technical ability, and performance under pressure.This camp continues to be a trusted favorite for families in the San Diego area, offering young players the chance to learn, compete, and grow under experienced, passionate coaches in a positive and engaging environment. Hear from Co-Owner of Prospect Soccer Academy and Camp Director Harry Forrester: "Our camps are delivered by seasoned professional players and coaches who bring real game experience into every session. Built around a proven, development-first philosophy, we prioritize technical excellence through high-repetition training and game-realistic scenarios such as 1v1 and 2v2, helping players build confidence, decision-making, and creativity under pressure. Just as important is the environment we create, structured, supportive, and professionally led, where players are encouraged to take risks, learn from mistakes, and grow. Our goal is for every player to leave not only as a more complete footballer, but with greater confidence, resilience, and a genuine love for the game.ΓÇ¥ Prospect Soccer Academy will be hosting camps in multiple other locations Click here for more info',6,14,'all','2026-06-29','2026-07-03',365.0,'per_session','$365-$485','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-4s-ranch-sports-park-san-diego',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','18001d52-4fac-42a5-9b62-2f3d57171697','nike-soccer-camp-with-prospect-soccer-academy-4s-ranch-sports-park-june-29-july--5y1g','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-c6f34eee-65b5-52b2-bd4d-3b4dec3c195e','org-14aff2ec-be45-5e10-b7ee-48571d4a8eed','nike-soccer-camp-at-sofive-south-gate-june-29-july-3-2026-mmq3','Nike Soccer Camp at Sofive South Gate -  (June 29ΓÇôJuly 3, 2026)','camp','camp_sports','["soccer"]','Experience elite training this summer at the Nike Soccer Camp at Sofive South Gate, powered by the regionally respected playerΓÇædevelopment expertise of Coach Chris Bonawandt and his renowned Los Angeles Soccer Camp organization. Known across the Los Angeles area for producing confident, technically skilled players and running some of the regionΓÇÖs most trusted youth soccer camps, Coach Chris brings his proven training model to Rancho Cucamonga for an unforgettable week of growth and excitement. Hosted at Sofive South Gate, a state-of-the-art soccer facility built for fast-paced play and top-tier instruction, this camp offers the perfect environment for players to sharpen their skills and take their game to the next level. Open to boys and girls ages 6ΓÇô16 of all experience levels, the program features a low coach-to-camper ratio, ensuring every athlete receives personalized feedback, quality repetitions, and individual attention. Campers will develop new techniques, strengthen fundamentals, improve decision-making, and build confidence through dynamic drills and competitive play. ΓÇ£At LA Soccer Camps, our goal is simple, we want kids from all backgrounds to have fun, play the game, and continue developing their skills. Each week we focus on one core fundamental each day, like dribbling, turning, passing, receiving, and shooting, so players can really lock in and build confidence. More than anything, we want kids to leave camp smiling, proud of what they learned, and excited to come back the next day.ΓÇ¥ - Chris Bonawandt, Camp Director',6,16,'all','2026-06-29','2026-07-03',310.0,'per_session','$310-$420','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-sofive-south-gate',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','196abbff-8da6-43b1-91b8-6ae5c0f3d1ac','nike-soccer-camp-at-sofive-south-gate-june-29-july-3-2026-mmq3','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-17da38b2-af27-5b2c-b508-40b94df49c45','org-a2a74987-8157-5137-aaa9-393368df9032','nike-soccer-camp-at-sofive-elkins-park-day-camp-june-29-july-3-2026-rotw','Nike Soccer Camp at Sofive Elkins Park - Day Camp (June 29ΓÇôJuly 3, 2026)','camp','camp_sports','["baseball_softball"]','Experience an actionΓÇæpacked week of worldΓÇæclass soccer training at the Nike Soccer Camp at Sofive Elkins Park in Elkins Park, Pennsylvania ΓÇö led by the internationally respected Gold &amp; Gray Soccer Academy. Founded by professional footballers David Gold and Ross Gray, Gold &amp; Gray has earned a reputation as one of ScotlandΓÇÖs premier development academies, trusted by MLS athletes and European professionals for cultivating top-tier youth talent. Open to boys and girls ages 6ΓÇô16 of all experience levels, this camp delivers an elite training environment inside a modern, state-of-the-art Sofive facility. Players benefit from a low coachΓÇætoΓÇæcamper ratio and receive personalized guidance from UEFAΓÇælicensed coaches who have trained youth athletes from renowned clubs including Celtic, Rangers, Hearts, and Hibs. Throughout the week, campers sharpen their technical skills, improve their speed of play and decision-making, and develop confidence through highΓÇæenergy sessions that blend professionalism with fun. ItΓÇÖs a chance to train like the pros, push your game forward, and experience the intensity and excitement of a true academy-style environment. Whether you''re aiming to elevate your game, build a stronger foundation, or simply enjoy an unforgettable week of soccer, this Nike Soccer Camp is the perfect opportunity to take your skills to the next level.',6,16,'all','2026-06-29','2026-07-03',265.0,'per_session','$265-$375','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-sofive-elkins-park',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','faff2788-0425-44e6-8711-af8428a4bea4','nike-soccer-camp-at-sofive-elkins-park-day-camp-june-29-july-3-2026-rotw','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-10bd8b45-08bc-5169-a37e-3e142b5a0b2d','org-f3694085-11a7-5ed4-afe7-b0272e774586','nike-soccer-camp-at-pace-university-june-29-july-3-2026','Nike Soccer Camp at Pace University -  (June 29ΓÇôJuly 3, 2026)','camp','camp_sports','["soccer"]','This Nike Soccer Camp offers a fantastic opportunity for players to improve their game this summer, join Head Coach Mike Winn at Pace University in Pleasantville, NY to develop your skills and tactical awareness. The camp will focus on team play, technical development, core fundamentals and position specifics. Campers will have an unforgettable experience while receiving unmatched training from college coaches on the Pace University campus. Camp is open to players of all abilities and will be grouped based on age and skill level.',6,17,'all','2026-06-29','2026-07-03',369.0,'per_session','$369-$519','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-pace-university',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','4ce0af73-fd01-43d3-bd4a-ad4daa7ae56f','nike-soccer-camp-at-pace-university-june-29-july-3-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
