INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-046f9acf-fdae-5000-94db-f9d98725a0f1','org-7f9b2a39-e44a-5978-a722-b08523fe5683','nike-tennis-camp-at-lewis-clark-college-july-6-9-2026','Nike Tennis Camp at Lewis & Clark College -  (July 6ΓÇô9, 2026)','camp','camp_sports','["tennis"]','Join us for an unforgettable tennis experience for junior players ages 8-17 at the Nike Tennis Camp at Lewis &amp; Clark College in Portland, Oregon. We offer winter, spring and summer sessions, providing young athletes the opportunity to work on their game year-round. This camp combines expert instruction, intensive drilling, and exciting competitive play, ensuring a well-rounded development for every player. Participants will have many opportunities to practice their skills, technique, and engage in friendly competition with peers who share their passion for tennis! Whether you''re a beginner or looking to refine your advanced skills, our camp is designed to challenge and inspire players of all levels. Get ready to hit countless balls, learn from experienced coaches, and make lasting friendships.',8,17,'all','2026-07-06','2026-07-09',799.0,'per_session','$799','https://www.ussportscamps.com/tennis/nike/nike-tennis-camp-at-lewis-clark-college#session-80264-1214618',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','62db9d01-ec2b-436f-985c-d81576b311ae','nike-tennis-camp-at-lewis-clark-college-july-6-9-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
