INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-9a476816-9e6c-5c07-b797-9ea70180d574','org-d9adece5-e805-51c2-ad8b-95e9b4c4332d','nike-baseball-camp-at-elmira-college-july-6-9-2026','Nike Baseball Camp at Elmira College -  (July 6ΓÇô9, 2026)','camp','camp_sports','["baseball_softball"]','The Nike Baseball Camp at Elmira College is thrilled to be back for the 2026 camp season! Head Coach of the Eagles, Anthony Goncalves, is excited to welcome familiar and new ballplayers who are looking to improve their skills. This will be a great opportunity to learn from collegiate coaches with a wide range of knowledge and expertise about the game of baseball. Coach Goncalves will be entering his fifth year at the helm of the Eagles, having first joined the program as an assistant in 2021 before becoming its second-ever head coach. Under his guidance, the team has broken several in-season offensive records, such as slugging percentage (.406), on-base percentage (.404), home runs (23), and hit-by-pitches (75). Defensively, Elmira set program bests for fewest hits (287) and walks (182) allowed, along with a single-game strikeout record of 16 against Alfred! Coach Goncalves and his staff are looking forward to sharing their knowledge and encourage everyone to register!',7,13,'all','2026-07-06','2026-07-09',309.0,'per_session','$309','https://www.ussportscamps.com/baseball/nike/nike-baseball-camp-elmira-college',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','dc4eddca-7efa-4a6f-8154-81792cec0a32','nike-baseball-camp-at-elmira-college-july-6-9-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-7f2a48a0-fe84-5ad1-874e-61076f28ecc2','org-7ff51dd2-198e-5e40-a1da-7281b3385131','nike-baseball-camp-at-university-of-la-verne-july-6-9-2026','Nike Baseball Camp at University of La Verne -  (July 6ΓÇô9, 2026)','camp','camp_sports','["baseball_softball"]','Get ready for the Nike Baseball Camps at the University of La Verne in Southern California! All baseball players that attend will learn valuable skills that they can transfer into their game to help them become better baseball players. Instruction will cover all aspects of baseball including fielding, hitting, baserunning, and team play. Summer is the perfect time to continue perfecting your love of the game and Director Scott Winterburn is confident he can help your camper reach their goals. Scott Winterburn, who took over the University of La Verne baseball program in 2001 after coaching at Azusa Pacific University, has built a powerhouse program over his tenure. Under his leadership, the Leopards have captured eight SCIAC titles (2004, 2005, 2008, 2012, 2018, 2023, 2024, and 2025), earned multiple Top 20 national rankings, made several NCAA tournament appearances, two super regional appearances (2023 and 2024), and two SCIAC Postseason Tournament Championships (2015 and 2025). Winterburn has also developed numerous standout players, coaching six SCIAC Players or Pitchers of the YearΓÇöall of whom earned All-America honorsΓÇöand producing 43 All-West Region selections and 9 total All-Americans.',8,13,'all','2026-07-06','2026-07-09',429.0,'per_session','$429','https://www.ussportscamps.com/baseball/nike/nike-baseball-camp-university-of-la-verne-1',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','62e4095b-2448-489d-b101-2d5580320965','nike-baseball-camp-at-university-of-la-verne-july-6-9-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
