INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-eff7a5a0-06c2-53f4-bb48-1f90b8e52e92','org-c6a19cf4-2d29-5bed-b166-354120bb638a','summer-camp-climbing-rock-stars-tacoma','Summer Camp - Climbing Rock Stars - Tacoma','camp','camp_general',NULL,'Five-day Tacoma day camp at the Mountaineers Tacoma Program Center for kids in grades 1-7 focused on advancing climbing skills. In addition to top-roping, belaying, and rappelling, campers practice clipping draws, mock-leading, anchor building, and some may lead sport routes. Each group gets one outdoor climbing field trip to Exit 38 near North Bend. Friday meets at Point Defiance Park. Camp runs 8:30am to 4:30pm Monday through Thursday. Led by Sarah Holt.',6,13,'intermediate','2026-07-06','2026-07-10',385.0,'per_session','$385 members / $410 guests','https://www.mountaineers.org/locations-lodges/tacoma-branch/committees/tacoma-youth-outreach-committee/course-templates/copy2_of_summer-camp-rock-ropes-1-tacoma/summer-camp-climbing-rock-stars-tacoma-2026',NULL,'waitlist','day',0,0,NULL,NULL,'scraped','active',90,'mountaineers.org','live','e548493f-78eb-420b-a307-4743e19ed42b','summer-camp-climbing-rock-stars-tacoma','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
