INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-02fbd15a-bca5-59a7-9d86-8a7996f6aa98','org-5da2c189-050f-5711-a8ad-950ab1f9bdcd','cwa-summer-camp-sports-camp-tennis-grades-3-5','CWA Summer Camp - Sports Camp: Tennis (Grades 3-5)','camp','camp_sports','["tennis"]','Half-day weeklong tennis camp at Charles Wright Academy for students entering grades 3-5 in fall. Monday-Friday 8:30 AM to 11:30 AM on the CWA campus. Combines focused tennis instruction with general camp activities such as field games, forest hikes, arts and crafts, and outdoor classroom time. Coaches are CWA athletics staff who also coach during the school year. Aftercare available until 5:30 PM at extra cost.',8,11,'all','2026-07-06','2026-07-10',250.0,'per_session','$250','https://www.homeroom.com/sites/charles-wright-academy-university-place/camp/sports-camps',NULL,'open','day',0,0,NULL,NULL,'scraped','active',90,'homeroom.com','live','a31ab1e9-d941-4e93-a650-60887b9bab6a','cwa-summer-camp-sports-camp-tennis-grades-3-5','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-9eb400bb-3f7a-5542-8421-0d62f87548d1','org-0d387ea0-de33-5114-8c62-125a0bb18473','nike-soccer-camp-in-winnetka-july-6-10-2026','Nike Soccer Camp in Winnetka -  (July 6ΓÇô10, 2026)','camp','camp_sports','["soccer"]','Soccer Skill Schools was voted a Top-10 Nike Soccer Camp in 2024 &amp; 2025 by players and parents! Join us for the Nike Soccer Camp in Winnetka with Kyle Jones, Director of Soccer Skill Schools. This camp welcomes players of all abilities, ages 6-16, to develop and refine their technical skills in a dynamic, competitive environment. It''s an exceptional opportunity for any player to train under top coaching professionals while having fun and pushing their game to the next level! Soccer Skill Schools'' "Numbers Approach Methodology" brings world-class skill development methods from Brazil, Holland, England, and Spain directly to the Midwest. The Soccer Skill School approach focuses on the individual player by guiding each athlete toward complete mastery of the ball, empowering them to make their own creative decisions, and equipping them with 65+ individual skills to win the one-on-one competitions that determine every game''s outcome. Led by experienced college coaches and current college players, the Soccer Skill Schools staff brings elite-level expertise and mentorship to every session. Training alongside coaches who compete at the collegiate level gives players invaluable insight into what it takes to elevate their game and succeed at the next level! Hear from Coach Kyle Jones: ΓÇ£We create an environment where players are challenged, supported, and inspired every day. Through high-quality coaching and a love for the game, our goal is to help each athlete build confidence, develop their skills, and leave camp better both on and off the field.ΓÇ¥',6,16,'all','2026-07-06','2026-07-10',529.0,'per_session','$529','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-winnetka-il#session-80861-1215443',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','0c8c87f5-26e0-4a5e-bbc4-941e9fa3d629','nike-soccer-camp-in-winnetka-july-6-10-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
