INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-3ac4689f-ef81-5f5a-831d-23cb70ef958b','org-30a3eb7f-4568-575d-80d0-f5594eae974a','nike-soccer-camp-with-jm-soccer-academy-in-reno-july-7-10-2026','Nike Soccer Camp with JM Soccer Academy in Reno -  (July 7ΓÇô10, 2026)','camp','camp_sports','["soccer"]','Experience an unforgettable week of soccer training at the Nike Soccer Camp at the Golden Eagle Sports Complex in Sparks, NV, one of the nationΓÇÖs premier multiΓÇæsport facilities and just minutes from Reno. This camp is designed for boys and girls ages 4ΓÇô14, offering the perfect blend of highΓÇælevel soccer instruction, structured gameplay, and plenty of shaded rest periods to keep athletes comfortable and refreshed throughout the day. Directed eby JM Soccer Academy and led by former professional player Jordan Murrell, this camp delivers elite coaching from one of the regionΓÇÖs top playerΓÇædevelopment programs. Jordan brings a modern, technical, and playerΓÇæcentered approach that helps young athletes build confidence, improve their skills, and play with greater intelligence and creativity. His ability to connect with players of all ages creates an energizing and supportive environment from the first whistle to the last. For our youngest athletes, the camp offers a Mini Camp from 8:00ΓÇô9:30am for ages 4ΓÇô5, introducing children to the joy of soccer through movementΓÇæbased activities, foundational skill work, and funΓÇæfocused learning. Older players ages 6ΓÇô14 will enjoy training that blends fastΓÇæpaced technical drills, ballΓÇæmastery work, smallΓÇæsided games, and competitive match play, all designed to elevate skills and soccer IQ in a fun and engaging setting. Each day is thoughtfully structured to balance highΓÇætempo development with recovery time, ensuring players stay active, engaged, and motivated while enjoying access to shaded areas throughout the complex. With worldΓÇæclass fields, exceptional coaching from JM Soccer Academy, and the proven structure of Nike Soccer Camps, this program delivers one of the most exciting and complete soccer experiences in the RenoΓÇôSparks region. Join us this summer at Golden Eagle Sports Complex and take your game to the next level with elite coaching, topΓÇætier facilities, and nonstop soccer fun!',4,14,'all','2026-07-07','2026-07-10',125.0,'per_session','$125','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-jm-soccer-academy-reno-nv#session-82752-1218106',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','cbc883e7-ebfa-4dda-ac23-477e73a32ea8','nike-soccer-camp-with-jm-soccer-academy-in-reno-july-7-10-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
