INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-3bed3dce-3b63-55c6-8430-90bb34e794f7','org-7f9a3b41-7b3d-574a-89ec-cb4016af821b','nike-baseball-camp-at-on-deck-in-prince-george-s-county-july-6-10-2026','Nike Baseball Camp at On-Deck in Prince GeorgeΓÇÖs County -  (July 6ΓÇô10, 2026)','camp','camp_sports','["baseball_softball"]','The Nike Baseball Camp at On-Deck in Prince GeorgeΓÇÖs County offers a high-level training experience in an intimate, athlete-focused environment. Directed by Andre Hockaday and the professional coaching staff at On-Deck, this camp is designed for players who want focused instruction, personalized feedback, and serious skill developmentΓÇöwithout losing the fun of the game. This summer, the camp will run four weekly sessions throughout the month of July, with camp held Monday through Friday from 9:00amΓÇô3:00pm. Each week features four days of skill development inside the state-of-the-art On-Deck indoor facility, followed by a final day of live scrimmages and gameplay on the turf baseball field at Prince GeorgeΓÇÖs Community College. The On-Deck facility is a 7,000-square-foot, air-conditioned training space equipped with a large indoor turf field, five batting cages, and modern baseball training technology. With just 50 campers per week, athletes receive extensive one-on-one instruction and small-group coaching from experienced professional baseball coaches and trainers. Campers can expect a well-rounded experience that blends advanced skill development, competitive gameplay, and a positive, high-energy atmosphereΓÇöall built to help players grow their confidence, sharpen their skills, and enjoy every day at camp.',6,12,'all','2026-07-06','2026-07-10',399.0,'per_session','$399','https://www.ussportscamps.com/baseball/nike/nike-baseball-camp-on-deck-prince-georges-county',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','1051f2ae-f690-4a8a-8d75-6ce84ce2b842','nike-baseball-camp-at-on-deck-in-prince-george-s-county-july-6-10-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
