INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-e3e5e548-3260-5d52-8449-986369f4a042','org-8cb76182-10f0-5927-9e5f-227f07dd2f28','nike-soccer-camp-at-oregon-state-university-july-12-16-2026','Nike Soccer Camp at Oregon State University -  (July 12ΓÇô16, 2026)','camp','camp_sports','["soccer"]','Join us for the Nike Soccer Camp at Oregon State University in Corvallis, Oregon, an immersive overnight soccer camp that has sold out three consecutive years. Set on the beautiful Oregon State campus, this premier residential camp offers the complete college-style experience, combining elite soccer training with engaging off-the-field and social activities. Designed for boys and girls ages 6ΓÇô17, this co-ed Nike Soccer Camp is led by passionate, experienced coaches committed to helping players accelerate their development. Campers train daily using a blend of modern and traditional coaching methods, focusing on technical skill development, tactical understanding, and confident decision-making in game-like situations. The overnight format allows athletes to fully experience campus life, build friendships, and participate in structured evening activities that complement their soccer training. This balance of high-level coaching and a truly immersive residential experience creates an environment where players grow both as athletes and as individuals. Whether your goal is to improve technical ability, boost soccer IQ, or experience what itΓÇÖs like to train in a top-tier college soccer environment, the Nike Soccer Camp at Oregon State University delivers a fun, competitive, and unforgettable summer camp experience.',6,17,'all','2026-07-12','2026-07-16',449.0,'per_session','$449','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-oregon-state-university#session-80991-1215660',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','2d6b54fe-a879-4a8f-bca4-78ee4e41792c','nike-soccer-camp-at-oregon-state-university-july-12-16-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
