INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-82fff649-1e70-5777-aaf3-e49f7cdd18a2','org-6a9f744e-acdf-54b3-bf34-b6e0be79dc51','nike-baseball-camp-at-california-state-university-san-marcos-july-13-16-2026','Nike Baseball Camp at California State University, San Marcos -  (July 13ΓÇô16, 2026)','camp','camp_sports','["baseball_softball"]','Nike Baseball Camps is excited to return to Cal State San Marcos in 2026! Register today and enjoy elite-level training while making memories to last a lifetime. The camp offers a unique opportunity to train under the direction of dedicated coaches and current and former collegiate athletes who serve as counselors. The camp is open to athletes ages 8-17. Day Camp (9:00am ΓÇô 4:00pm) This Day Camp program runs 9:00am-4:00pm each day and includes daytime training, fun activities, scrimmaging opportunities, and more. Campers can bring their own lunch or purchase on campus. Athletic Facilities Campers train at the Cal State San MarcosΓÇÖ Baseball Stadium for the duration of the camp. The facility offers a beautiful field with batting cages and bullpens and offers free parking next to the field for drop-off and pick-up. The Nike Baseball Camp at Cal State San Marcos is open to any and all entrants and limited only by number, age and gender. Athletic facilities and coaches are subject to change. The camp is not owned, sponsored, controlled or endorsed by Cal State San Marcos.',8,17,'all','2026-07-13','2026-07-16',529.0,'per_session','$529','https://www.ussportscamps.com/baseball/nike/nike-baseball-camp-california-state-university-san-marcos#session-83247-1218788',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','eef80cf9-ba8b-4c78-b5a8-be05dbdac829','nike-baseball-camp-at-california-state-university-san-marcos-july-13-16-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
