INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-8e35132e-0b07-5437-ba52-977215e9d165','org-c6a19cf4-2d29-5bed-b166-354120bb638a','summer-camp-nature-arts-crafts-week-1-tacoma','Summer Camp - Nature Arts & Crafts Week 1 - Tacoma','camp','camp_general',NULL,'Five-day Tacoma day camp at the Mountaineers Tacoma Program Center for kids in grades 1-7 connecting outdoor skills with arts and crafts. Wednesday and Thursday are field trip days with an easy hike in the Mt. Rainier area focused on nature photography and watercolor painting. Activities may include climbing, rope skills, navigation, wilderness first aid, drawing, mural creation, 3D topographic maps, ropes-based crafts, paper mache, tie-dye, and pyrography. Friday meets at Point Defiance Park. Camp runs 8:30am to 4:30pm. Led by Sarah Holt.',6,13,'beginner','2026-07-13','2026-07-17',385.0,'per_session','$385 members / $410 guests','https://www.mountaineers.org/locations-lodges/tacoma-branch/committees/tacoma-youth-outreach-committee/course-templates/copy_of_wilderness-week-tacoma/summer-camp-nature-arts-crafts-week-1-tacoma-2026',NULL,'waitlist','day',0,0,NULL,NULL,'scraped','active',90,'mountaineers.org','live','19177202-8ad3-4738-98ad-b94ef6f85250','summer-camp-nature-arts-crafts-week-1-tacoma','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-131e4c20-996b-5629-a952-4c29c70b3bac','org-b81ef3c2-3888-5339-bd89-a7f6feec0012','sound-life-day-camp-week-4-sweets','Sound Life Day Camp - Week 4: Sweets','camp','camp_general',NULL,'Tacoma Christian day camp with daily off-site field trips. Week 4 themed Sweets with an ice cream taste challenge, Seattle Chocolate Factory, donuts in the South Sound, Boehm Chocolate Factory, and Friday swimming. Camp hours 8:15am to 4:30pm with free before-care 7:30 to 8:15am and aftercare 4:30 to 5:30pm. One-time $30 registration fee per camper.',6,13,'all','2026-07-13','2026-07-17',220.0,'per_session','$220/week plus $30 registration','https://www.soundlifedaycamp.com/tacoma',NULL,'open','day',0,0,NULL,NULL,'scraped','active',90,'soundlifedaycamp.com','live','90857c2c-a9b8-4beb-8431-7ee7c19f58b1','sound-life-day-camp-week-4-sweets','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
