INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-ce3a823e-76eb-50ed-938d-75e4c1eeb898','org-7e0aad84-71ba-53f0-b359-ab0fa336e751','challenger-sports-foundational-skills-camp-norpoint-at-meeker-middle-school','Challenger Sports Foundational Skills Camp - NorPoint at Meeker Middle School','camp','camp_sports','["soccer"]','Challenger Sports Foundational Skills Camp partnered with NorPoint SC and held at Meeker Middle School in northeast Tacoma. Five-day soccer day camp for ages 3-14 led by international coaches. Curriculum focuses on technical foundational skills, small-sided games, and a tactical introduction grouped by age and ability. Multiple session lengths are available with early-bird pricing applied at checkout.',3,14,'all','2026-07-13','2026-07-17',119.0,'per_session','$119-$299','https://challengersports.com/camps/norpoint-sc-week-1-tacoma-wa/',NULL,'open','day',0,0,NULL,NULL,'scraped','active',90,'challengersports.com','live','05261ec2-a85e-4c5d-b854-fa72510c5cc7','challenger-sports-foundational-skills-camp-norpoint-at-meeker-middle-school','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-bd522796-5a77-5b77-b20d-82f0ae9419c7','org-5da2c189-050f-5711-a8ad-950ab1f9bdcd','cwa-summer-camp-sports-camp-soccer-grades-3-5','CWA Summer Camp - Sports Camp: Soccer (Grades 3-5)','camp','camp_sports','["soccer"]','Half-day weeklong soccer camp at Charles Wright Academy for students entering grades 3-5 in fall. Monday-Friday 8:30 AM to 11:30 AM. Held on the CWA campus athletics fields, combined with general camp activities such as field games, forest hikes, arts and crafts, and outdoor classroom time. Coaches are CWA athletics staff. Lunch is camper-provided; aftercare available until 5:30 PM at extra cost.',8,11,'all','2026-07-13','2026-07-17',250.0,'per_session','$250','https://www.homeroom.com/sites/charles-wright-academy-university-place/camp/sports-camps',NULL,'open','day',0,0,NULL,NULL,'scraped','active',90,'homeroom.com','live','2d073331-efb3-418b-8d8f-b05c29b19af3','cwa-summer-camp-sports-camp-soccer-grades-3-5','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-388d44f0-ee7b-545c-b0e1-a7c8a45d7c44','org-594c63d9-a90e-53ad-b7c8-28a7b91ae76a','nike-soccer-camp-at-lake-forest-academy-day-camp-iii-july-13-17-2026','Nike Soccer Camp at Lake Forest Academy - Day Camp III (July 13ΓÇô17, 2026)','camp','camp_sports','["soccer"]','Soccer Skill Schools was voted a Top-10 Nike Soccer Camp in 2024 &amp; 2025 by players and parents! Join us for the Nike Soccer Camp at Lake Forest Academy with Kyle Jones, Director of Soccer Skill Schools. This camp welcomes players of all abilities, ages 6-16, to develop and refine their technical skills in a dynamic, competitive environment. It''s an exceptional opportunity for any player to train under top coaching professionals while having fun and pushing their game to the next level! Soccer Skill Schools'' "Numbers Approach Methodology" brings world-class skill development methods from Brazil, Holland, England, and Spain directly to the Midwest. The Soccer Skill School approach focuses on the individual player by guiding each athlete toward complete mastery of the ball, empowering them to make their own creative decisions, and equipping them with 65+ individual skills to win the one-on-one competitions that determine every game''s outcome. Led by experienced college coaches and current college players, the Soccer Skill Schools staff brings elite-level expertise and mentorship to every session. Training alongside coaches who compete at the collegiate level gives players invaluable insight into what it takes to elevate their game and succeed at the next level! Hear from Coach Kyle Jones: ΓÇ£We create an environment where players are challenged, supported, and inspired every day. Through high-quality coaching and a love for the game, our goal is to help each athlete build confidence, develop their skills, and leave camp better both on and off the field.ΓÇ¥',6,16,'all','2026-07-13','2026-07-17',549.0,'per_session','$549','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-lake-forest#session-79579-1213265',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','192d1a72-8471-4c8b-9d1c-930c242ce08f','nike-soccer-camp-at-lake-forest-academy-day-camp-iii-july-13-17-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
