'2026-07-13','2026-07-17',399.0,'per_session','$399','https://www.ussportscamps.com/soccer/nike/nike-indoor-soccer-camp-hub-sports-rancho-solano#session-82836-1218212',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','499b90bb-9f0a-40cd-b61e-e63d88b2b675','nike-indoor-soccer-camp-with-hub-sports-at-rancho-solano-prep-school-indoor-camp-i38x','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
