INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-20aa2155-9af0-57c1-9b20-b921d846aa92','org-5d520186-e863-5005-95c1-5561a866632c','nike-soccer-camp-at-sofive-rancho-cucamonga-july-13-17-2026','Nike Soccer Camp at Sofive Rancho Cucamonga -  (July 13ΓÇô17, 2026)','camp','camp_sports','["soccer"]','Experience elite training this summer at the Nike Soccer Camp at Sofive Rancho Cucamonga, powered by the regionally respected playerΓÇædevelopment expertise of Coach Chris Bonawandt and his renowned Los Angeles Soccer Camp organization. Known across the Los Angeles area for producing confident, technically skilled players and running some of the regionΓÇÖs most trusted youth soccer camps, Coach Chris brings his proven training model to Rancho Cucamonga for an unforgettable week of growth and excitement. Hosted at Sofive Rancho Cucamonga, a state-of-the-art soccer facility built for fast-paced play and top-tier instruction, this camp offers the perfect environment for players to sharpen their skills and take their game to the next level. Open to boys and girls ages 6ΓÇô16 of all experience levels, the program features a low coach-to-camper ratio, ensuring every athlete receives personalized feedback, quality repetitions, and individual attention. Campers will develop new techniques, strengthen fundamentals, improve decision-making, and build confidence through dynamic drills and competitive play. ΓÇ£At LA Soccer Camps, our goal is simple, we want kids from all backgrounds to have fun, play the game, and continue developing their skills. Each week we focus on one core fundamental each day, like dribbling, turning, passing, receiving, and shooting, so players can really lock in and build confidence. More than anything, we want kids to leave camp smiling, proud of what they learned, and excited to come back the next day.ΓÇ¥ - Chris Bonawandt, Camp Director',6,16,'all','2026-07-13','2026-07-17',315.0,'per_session','$315','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-sofive-rancho-cucamonga#session-82120-1217228',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','3eeffc0b-c4a7-4120-aaf8-2811597d486f','nike-soccer-camp-at-sofive-rancho-cucamonga-july-13-17-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
