INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-b1126b08-7767-5526-b0ca-d5c605d631df','org-5a9b68a2-1e78-5c1a-a13f-1d95da126f82','nike-baseball-camp-at-adventhealth-stadium-directed-by-rome-emperors-july-21-23-','Nike Baseball Camp at AdventHealth Stadium, directed by Rome Emperors -  (July 21ΓÇô23, 2026)','camp','camp_sports','["baseball_softball"]','Nike Baseball Camps is thrilled to return to host camp with the Rome Emperors the High-A Affiliate of the Atlanta Braves! The Emperors staff and players are ready to provide a great learning environment and give each camper the proper tools to excel at the next level. Campers age 7-13 will have have the opportunity to learn how to approach the sport the right way as they fine-tune their fielding, hitting, base-running skills, and enhance their knowledge of the game, all while having an awesome time and making new friends. Campers will also have the opportunity to attend a Rome Emperors each day after camp!',7,13,'all','2026-07-21','2026-07-23',299.0,'per_session','$299','https://www.ussportscamps.com/baseball/nike/nike-baseball-camp-rome-emperors',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','443ffa78-d7d2-4b62-90fb-c022559993b5','nike-baseball-camp-at-adventhealth-stadium-directed-by-rome-emperors-july-21-23-','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
