INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-065e0d46-0033-5d69-ae55-f111c1b39a01','org-f99d3067-e1bd-5aff-970e-3e22c74eeec4','nike-baseball-camp-at-biola-university-july-20-23-2026-3lkh','Nike Baseball Camp at Biola University -  (July 20ΓÇô23, 2026)','camp','camp_sports','["baseball_softball"]','The Nike Baseball Camp at Biola University is back for another awesome summer in 2026! Hosted in La Mirada, CA, this informative camp experience is run by BiolaΓÇÖs Head Coach Jesse Rodgers and a great team of coaches who know how to teach the game and keep it exciting. Campers will level up their fielding, hitting, and base-running skills, learn more about the game they love, and have a blast making new friends. ItΓÇÖs the perfect mix of high-energy baseball and unforgettable summer memories!',5,8,'all','2026-07-20','2026-07-23',329.0,'per_session','$329-$429','https://www.ussportscamps.com/baseball/nike/baseball-camp-biola-university',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','f10bc375-93cb-4a42-8377-e28fcfb90c03','nike-baseball-camp-at-biola-university-july-20-23-2026-3lkh','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-264f4f4b-e793-5d8e-9ba0-95c57ecc1cf3','org-ee6ff521-bb7c-588a-9cb9-a65746c686fc','nike-baseball-camp-at-seattle-university-july-20-23-2026-kj97','Nike Baseball Camp at Seattle University -  (July 20ΓÇô23, 2026)','camp','camp_sports','["baseball_softball"]','Get ready for an awesome summer of baseball training at the Nike Baseball Camp at Seattle University! Take your game to the next level, sharpen your skills, and compete alongside other serious players. Led by Coach Leo Rivera, Assistant Baseball Coach at Seattle University, this camp offers high-level instruction in a fun, challenging, and competitive environment. Coach Rivera and his staff are committed to helping every player improve, reach their goals, and build confidence on and off the field. All skill levels are welcomeΓÇöcome ready to work hard, make new friends, and create memories that will last long after the final out of summer.',7,13,'all','2026-07-20','2026-07-23',429.0,'per_session','$429','https://www.ussportscamps.com/baseball/nike/nike-baseball-camp-seattle-university',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','5f1f6303-1b86-4585-ac14-d1ddf31cc966','nike-baseball-camp-at-seattle-university-july-20-23-2026-kj97','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-1d61b73f-895e-5da3-9f2e-769a49824f3f','org-95ef4eed-99f4-53d1-ac4e-57f87618412e','nike-baseball-camp-in-bend-day-camp-july-20-23-2026-n3hj','Nike Baseball Camp in Bend - Day Camp (July 20ΓÇô23, 2026)','camp','camp_sports','["baseball_softball"]','Nike Baseball Camps is thrilled to return to Bend, OR in 2026! Register today and enjoy elite-level training while making memories to last a lifetime. The camp offers a unique opportunity to train under the direction of dedicated coaches and current and former collegiate athletes who serve as counselors. The camp is open to athletes ages 8-17 (varies by program type). Overnight Camp Our overnight camp in Bend offers an immersive, on-campus experience where campers reside in the campus dormitories in adjacent rooms to the coaching staff while training during the daytime hours. The tuition includes all training, lodging, meals, fun evening activities, and more. This program is offered to boys ages 10-17. New in 2026! Overnight campers will now stay in the dormitories at Wickiup Hall at Central Oregon Community College. COCC is a beautiful campus located on Awbrey Butte in Westside Bend and has sweeping views of the Cascade Mountains. The campus has large, nice dorms built in 2015 and more expansive athletic facilities for training and evening activities. Day Camp (9:00am ΓÇô 4:00pm) Nike Baseball Camps also offers a day camp program for athletes who do not wish to stay overnight. The day camp program runs 9:00am-4:00pm each day and includes daytime training only. Campers can bring their own lunch or purchase on campus. The day camp program is open to boys ages 8-17. Nike Sports Camp Experience Nike Sports Camps offers a unique experience in Bend with many sports - Baseball, Cross Country, Golf (Coming Soon!), Soccer, Softball, Tennis, and Track &amp; Field - operating simultaneously. During the day, the athletes receive sport-specific coaching within their sport focus. In the evening, overnight campers across all sports come together for a special camp-wide experience which includes fun field games, educational seminars, and more. Baseball Complex/Transportation Information The camp will likely utilize the Big Sky Park Baseball Fields or Summit High School (as it has in the past) for daily training. Campers and staff are transported by bus to and from the off-campus facilities for training each day. The 2026 athletic facilities will be confirmed in the spring. The Nike Baseball Camp in Bend is open to any and all entrants and limited only by number, age and gender. Athletic facilities and coaches are subject to change. The camp is not owned, sponsored, controlled or endorsed by Central Oregon Community College.',8,17,'all','2026-07-20','2026-07-23',569.0,'per_session','$569','https://www.ussportscamps.com/baseball/nike/nike-baseball-camp-bend',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','c9650617-6744-4650-b83b-f4dee608714a','nike-baseball-camp-in-bend-day-camp-july-20-23-2026-n3hj','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
