INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-53529fe4-eb80-5661-b055-f269fa8fb450','org-e2c5755d-9037-5214-82ef-6d0ccbb94eef','point-defiance-zoo-wild-explorers-camp-july','Point Defiance Zoo Wild Explorers Camp - July','camp','camp_general',NULL,'Five-day Zoo camp at Point Defiance for 3rd and 4th grade graduates. Campers tour the Zoo, Aquariums, and surrounding natural areas to study how animals adapt to terrestrial and marine environments and meet animals up close. Monday through Friday 8:45 am to 3:30 pm.',9,11,'intermediate','2026-07-20','2026-07-24',485.0,'per_session','$485 members, $530 non-members','https://www.pdza.org/summer-camps/',NULL,'full','day',0,0,NULL,NULL,'scraped','active',60,NULL,'live','eb6c23a3-9081-4fe1-aef4-2f42448916d3','point-defiance-zoo-wild-explorers-camp-july','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-e5265adb-3afe-591f-b84e-cd2337d04506','org-e2c5755d-9037-5214-82ef-6d0ccbb94eef','point-defiance-zoo-science-explorers-camp-july','Point Defiance Zoo Science Explorers Camp - July','camp','camp_general',NULL,'Four-day Zoo camp at Point Defiance for 5th to 7th grade graduates. Campers explore animal adaptations, tour Zoo and aquarium habitats, and learn how care teams and veterinarians work, with some classroom learning. Tuesday through Friday 8:45 am to 3:45 pm.',11,13,'intermediate','2026-07-21','2026-07-24',415.0,'per_session','$415 members, $455 non-members','https://www.pdza.org/summer-camps/',NULL,'full','day',0,0,NULL,NULL,'scraped','active',60,NULL,'live','db323531-e7d9-4226-b542-672fe013820e','point-defiance-zoo-science-explorers-camp-july','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-88471b4c-d5a8-5a55-92a7-f86405aa3e83','org-71e5e6b6-d4d6-518c-8b88-c02fa868b491','camp-invention-at-marvista-elementary','Camp Invention at Marvista Elementary','camp','coding_stem',NULL,'Camp Invention is a week-long STEM day camp run by the National Inventors Hall of Fame at Marvista Elementary. Campers work in small teams on hands-on challenges that mix engineering, problem solving, and creativity. Activities change each year and include taking apart real devices, building prototypes, and pitching inventions. The program is led by trained local educators.',5,11,'all','2026-07-20','2026-07-24',295.0,'per_session','$295','https://www.invent.org/programs/camp-invention',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,NULL,'live','dbefb11c-b9d6-4cb8-be08-0c92e79276f2','camp-invention-at-marvista-elementary','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-12bd2363-1eb9-539c-af87-d8465e820231','org-fd0d014f-8563-513d-8c8c-414acd38b6a2','hit-the-road-adventure-camp','Hit the Road Adventure Camp','camp','camp_general',NULL,'Hit the Road is one of three teen Adventure Camps run by City of Auburn Parks Arts and Recreation at the Les Gove Park / Teen Center complex. The camp meets Monday through Friday for ages 11 through 15. Adventure Camp programming centers on group outings, off-site transports, and team-building activities led by Auburn Parks staff. Registration is through Auburn''s ActiveNet portal.',11,15,'all','2026-07-20','2026-07-24',335.0,'per_session','$335 resident / $422 non-resident','https://apm.activecommunities.com/auburnwa/Activity_Search',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'apm.activecommunities.com','live','95aa78d1-6822-429f-8346-75fd1a258e8a','hit-the-road-adventure-camp','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
