INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-693a4bca-a296-5a34-b583-753ee5449901','org-e23f58bf-b368-5e9e-a6f6-ec5ced84ff97','auburn-theatre-camp','Auburn Theatre Camp','camp','theater',NULL,'Auburn Parks and Recreation theatre day camp for older kids at Les Gove Park. Acting, scene work, stage movement, and a final performance led by Parks instructors.',10,14,'beginner','2026-07-20','2026-07-24',NULL,NULL,'Contact for pricing','https://apm.activecommunities.com/auburnwa/Activity_Search',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'apm.activecommunities.com','live','6e73c751-2554-4d49-b89b-16f9de5c4674','auburn-theatre-camp','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-597ca8d4-6ecd-5a07-a2db-03aeaf907a08','org-c6a19cf4-2d29-5bed-b166-354120bb638a','summer-camp-rock-ropes-2-tacoma','Summer Camp - Rock & Ropes 2 - Tacoma','camp','camp_general',NULL,'Five-day Tacoma day camp at the Mountaineers Tacoma Program Center for kids in grades 1-7 focused on introduction to rock climbing. Identical curriculum to Rock & Ropes 1, simply the second instance of the theme. Campers learn to belay, tie knots, rappel, prusik, and try basic anchor work. Each group gets one outdoor climbing field trip to Exit 38 near North Bend. Friday meets at Point Defiance Park. Camp runs 8:30am to 4:30pm Monday through Thursday. Led by Sarah Holt.',6,13,'beginner','2026-07-20','2026-07-24',385.0,'per_session','$385 members / $410 guests','https://www.mountaineers.org/locations-lodges/tacoma-branch/committees/tacoma-youth-outreach-committee/course-templates/copy_of_summer-camp-rock-ropes-1-tacoma/summer-camp-rock-ropes-2-tacoma-2026',NULL,'waitlist','day',0,0,NULL,NULL,'scraped','active',90,'mountaineers.org','live','78da01c4-afd2-479e-b8c1-700723e08a41','summer-camp-rock-ropes-2-tacoma','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-4adb282b-9afb-5b89-89bd-9dfe8fb0ba89','org-b81ef3c2-3888-5339-bd89-a7f6feec0012','sound-life-day-camp-week-5-mariners','Sound Life Day Camp - Week 5: Mariners','camp','camp_general',NULL,'Tacoma Christian day camp with daily off-site field trips. Week 5 themed Mariners with ice blocking, boating and tubing days, a Mariners baseball game, and Friday swimming. Camp hours 8:15am to 4:30pm with free before-care 7:30 to 8:15am and aftercare 4:30 to 5:30pm. One-time $30 registration fee per camper.',6,13,'all','2026-07-20','2026-07-24',220.0,'per_session','$220/week plus $30 registration','https://www.soundlifedaycamp.com/tacoma',NULL,'open','day',0,0,NULL,NULL,'scraped','active',90,'soundlifedaycamp.com','live','6017c4eb-02a6-4746-9e4e-d91693432ce8','sound-life-day-camp-week-5-mariners','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-7ebc092d-6a02-5b06-b98c-d8b446b92f99','org-0b699443-57e1-5de3-a259-580a4a913699','wolf-camp-puyallup-wildlife-search-rescue','Wolf Camp Puyallup - Wildlife Search & Rescue','camp','camp_general',NULL,'Wildlife tracking and search and rescue day camp at Clark''s Creek Park South Shelter and Blue Skye Farm. Campers hike with day packs, learn to read animal tracks and bird signs, and follow lessons that adapt to where the wildlife leads. No prerequisites required. 6:1 student-teacher ratio. Daily schedule 9:00am to 3:45pm with morning lessons, lunch with games and archery, and afternoon activities.',7,14,'beginner','2026-07-20','2026-07-24',495.0,'per_session','$495 full tuition (sliding scale available)','https://wolfcamp.org/youth/summer-day-camps-for-kids/puyallup-tacoma/',NULL,'waitlist','day',0,0,NULL,NULL,'scraped','active',90,'wolfcamp.org','live','32305745-ba80-4edb-9e3b-29d85d81522f','wolf-camp-puyallup-wildlife-search-rescue','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
