INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-4267a5d6-9184-551b-ad8e-a799cd98f60b','org-904323b8-de9e-516a-8009-2f0dd81d3b9d','nike-soccer-camp-in-winnetka-july-20-24-2026','Nike Soccer Camp in Winnetka -  (July 20ΓÇô24, 2026)','camp','camp_sports','["soccer"]','Soccer Skill Schools was voted a Top-10 Nike Soccer Camp in 2024 &amp; 2025 by players and parents! Join us for the Nike Soccer Camp in Winnetka with Kyle Jones, Director of Soccer Skill Schools. This camp welcomes players of all abilities, ages 6-16, to develop and refine their technical skills in a dynamic, competitive environment. It''s an exceptional opportunity for any player to train under top coaching professionals while having fun and pushing their game to the next level! Soccer Skill Schools'' "Numbers Approach Methodology" brings world-class skill development methods from Brazil, Holland, England, and Spain directly to the Midwest. The Soccer Skill School approach focuses on the individual player by guiding each athlete toward complete mastery of the ball, empowering them to make their own creative decisions, and equipping them with 65+ individual skills to win the one-on-one competitions that determine every game''s outcome. Led by experienced college coaches and current college players, the Soccer Skill Schools staff brings elite-level expertise and mentorship to every session. Training alongside coaches who compete at the collegiate level gives players invaluable insight into what it takes to elevate their game and succeed at the next level! Hear from Coach Kyle Jones: ΓÇ£We create an environment where players are challenged, supported, and inspired every day. Through high-quality coaching and a love for the game, our goal is to help each athlete build confidence, develop their skills, and leave camp better both on and off the field.ΓÇ¥',6,16,'all','2026-07-20','2026-07-24',529.0,'per_session','$529','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-winnetka-il#session-80862-1215444',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','8d874887-8423-4028-8f07-1aed86f5d650','nike-soccer-camp-in-winnetka-july-20-24-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-c2cb49bd-5997-52ca-a8cc-f39180fa834b','org-aa2c10de-b835-5a38-b5ba-1db8f5cfe847','nike-soccer-camp-in-st-charles-july-20-24-2026','Nike Soccer Camp in St. Charles -  (July 20ΓÇô24, 2026)','camp','camp_sports','["soccer"]','Michael OΓÇÖNeill was voted a Top 10 Nike Soccer Camp Director in 2025 by players and parents. His camps are built around positive coaching, strong fundamentals, and a welcoming environment where players of all levels can develop and enjoy the game. Join us for an exciting camp experience at Sportsplex in St. Charles, IL. Campers will receive instruction from Northern Illinois University WomenΓÇÖs Soccer Head Coach Michael OΓÇÖNeill in a structured, high-energy environment focused on skill development and confidence building. Sessions combine traditional and modern coaching methods with an emphasis on dribbling, passing, shooting, ball control, and small-sided games that reinforce teamwork, communication, and decision-making. Designed for players ages 6ΓÇô14, this camp provides age-appropriate training and individual attention to support steady improvement throughout the week. ItΓÇÖs a fun, competitive environment where players can grow their skills, build confidence, and make new friends. Hear from NIU Head Coach and Camp Director Michael O''Neil: "Our camp is built around the belief that young players learn best when they feel supported, challenged, and excited to be on the field. Through positive coaching, fun and engaging activities, and age-appropriate skill development, players will build confidence, improve their soccer fundamentals, learn teamwork and sportsmanship, and develop a lasting love for the game in a safe and encouraging environment."',6,14,'all','2026-07-20','2026-07-24',335.0,'per_session','$335','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-st-charles-il#session-82309-1217506',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','6a5d42f3-af7f-4df6-8acb-f46eb1a39892','nike-soccer-camp-in-st-charles-july-20-24-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
