INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-37359130-2820-52cc-9239-4818dba7cb96','org-899373aa-0595-56b1-8cd5-1cb2161f749e','nike-soccer-camp-at-northern-arizona-university-flagstaff-july-20-24-2026','Nike Soccer Camp at Northern Arizona University - Flagstaff -  (July 20ΓÇô24, 2026)','camp','camp_sports','["soccer"]','Experience the excitement of Nike Soccer Camps this summer at Northern Arizona University, where young athletes train like true Lumberjacks under the leadership of NAU WomenΓÇÖs Soccer Head Coach Alan Berrios and his elite collegiate coaching staff. Set against the breathtaking backdrop of Flagstaff, Arizona, this camp invites boys and girls ages 6ΓÇô16 to elevate their game on Lumberjack Field, one of the top Division I soccer facilities in the region. Players will sharpen their technical skills, gain confidence through fastΓÇæpaced smallΓÇæsided games, and enjoy personalized instruction designed for every level, from beginners to aspiring competitive athletes. With its cool mountain climate and beautiful highΓÇæaltitude setting, Flagstaff is the ultimate summer training destination, providing the perfect environment for players to stay active, focused, and inspired. Every day at camp blends highΓÇæenergy coaching with the supportive atmosphere Nike Soccer Camps are known for, creating an unforgettable experience that pushes athletes to grow on and off the field. Leave Camp More Confident ΓÇô Our goal is for every camper to leave with stronger skills, new friendships, and a greater love for the game. Hear From Coach Alan Berrios: ΓÇ£Our youth camps are built around creating a positive and inspiring environment where young players can grow their love for the game while developing strong fundamentals. Every session is run by our coaching staff and supported by current and former NAU players, allowing campers to learn directly from athletes who train and compete at the Division I level. We focus on teaching the game the right way, building technical skills, confidence, teamwork, and character. While making sure players are having fun and feeling supported every step of the way. Our goal is for every camper to leave with improved skills, new friendships, and an even greater passion for soccer.ΓÇ¥',6,16,'all','2026-07-20','2026-07-24',255.0,'per_session','$255','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-northern-arizona-university-flagstaff#session-84631-1220671',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','674583b5-3311-41c6-9f64-3594725e57c5','nike-soccer-camp-at-northern-arizona-university-flagstaff-july-20-24-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
