INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-c802deac-1efd-5973-a8fe-afe785e44551','org-e16b175a-1ef7-578f-816e-96166c0b6436','nike-soccer-camp-in-river-hills-july-20-24-2026','Nike Soccer Camp in River Hills -  (July 20ΓÇô24, 2026)','camp','camp_sports','["soccer"]','Soccer Skill Schools was voted a Top-10 Nike Soccer Camp in 2024 &amp; 2025 by players and parents! Join us for the Nike Soccer Camp in River Hills with Kyle Jones, Director of Soccer Skill Schools. This camp welcomes players of all abilities, ages 6-16, to develop and refine their technical skills in a dynamic, competitive environment. It''s an exceptional opportunity for any player to train under top coaching professionals while having fun and pushing their game to the next level! Soccer Skill Schools'' "Numbers Approach Methodology" brings world-class skill development methods from Brazil, Holland, England, and Spain directly to the Midwest. The Soccer Skill School approach focuses on the individual player by guiding each athlete toward complete mastery of the ball, empowering them to make their own creative decisions, and equipping them with 65+ individual skills to win the one-on-one competitions that determine every game''s outcome. Led by experienced college coaches and current college players, the Soccer Skill Schools staff brings elite-level expertise and mentorship to every session. Training alongside coaches who compete at the collegiate level gives players invaluable insight into what it takes to elevate their game and succeed at the next level! Hear from Coach Kyle Jones: ΓÇ£We create an environment where players are challenged, supported, and inspired every day. Through high-quality coaching and a love for the game, our goal is to help each athlete build confidence, develop their skills, and leave camp better both on and off the field.ΓÇ¥',6,16,'all','2026-07-20','2026-07-24',460.0,'per_session','$460','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-river-hills#session-82860-1218245',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','dcd0e77c-2fef-4946-a11c-4b54c99344a5','nike-soccer-camp-in-river-hills-july-20-24-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
