INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-ae0112d5-83ea-5802-91ae-a2ca6b1df1c4','org-7905c2c6-324f-56f8-a907-8fe5168ea32c','robert-morris-university-girls-soccer-camp-july-20-24-2026','Robert Morris University Girls Soccer Camp -  (July 20ΓÇô24, 2026)','camp','camp_sports','["soccer"]','The Robert Morris University Girls Soccer Camp offers a high-quality day camp soccer experience for girls ages 6ΓÇô14 at Robert Morris Soccer Stadium in Moon Township, Pennsylvania. Conveniently located just outside Pittsburgh, this camp serves families throughout Allegheny County and the greater Western PA region. Led by Head Women''s Soccer Coach Michelle Rick, the camp provides expert instruction rooted in collegiate training principles while remaining fun, supportive, and age-appropriate. Open to players of all skill levels, campers will work on developing their technical abilities, game understanding, and confidence through structured training sessions and small-sided play. Camp sessions focus on foundational skills such as ball control, passing, dribbling, and finishing, paired with competitive games that encourage creativity, teamwork, and decision-making. Training takes place at Robert Morris Soccer Stadium, giving campers the opportunity to learn and compete in an authentic collegiate soccer environment. Hear from Head Women''s Soccer Coach &amp; Camp Director Michelle Rick: "Our goal is simple... create a fun, positive environment where kids can learn the game, play, and enjoy being on the field with their friends. This camp is perfect for young players of all levels who want to stay active, have fun, and improve their soccer skills over the summer. Whether new to the game or already playing, campers will enjoy a supportive environment focused on learning, playing, and enjoying the game with others."',6,14,'all','2026-07-20','2026-07-24',255.0,'per_session','$255','https://www.ussportscamps.com/soccer/nike/girls-soccer-camp-robert-morris-university#session-83092-1218557',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','bd550859-c07a-40f6-8a84-f0c50777925e','robert-morris-university-girls-soccer-camp-july-20-24-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
