INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-e264e151-a3ae-5c04-9080-aa2abcdb0a7c','org-c5f56e1f-e332-5ef2-917d-f8b6325bf270','nike-tennis-camp-amherst-at-mount-holyoke-college-all-skills-program-all-skills--a3d3','Nike Tennis Camp (Amherst) at Mount Holyoke College - All Skills Program - All Skills (High School Only) (July 19ΓÇô24, 2026)','camp','camp_sports','["tennis"]','Nike Tennis Camp continues its tradition of excellence at the prestigious Mount Holyoke College, a location that has hosted thousands of campers over the years. Directed by Mike Gardner and Ryan Holmes, renowned coaches in the Northeast, this camp offers top-tier training in a world-class environment. We offer Full Day, Extended Day, and Overnight program options for players ages 8-18. With top-tier instruction, world-class facilities, and an unforgettable experience, our camp is the perfect place to elevate your game! This coed camp is open to beginner and intermediate players. If your camper is an advanced or tournament level player, please visit: Nike Tennis Camp at Mount Holyoke College - Tournament Programs This Camp must comply with regulations of the Massachusetts Department of Public Health and be licensed by local Board of Health. Parents/Guardians will have the right to review background check, healthcare and discipline policies and grievance procedures upon request.',13,18,'all','2026-07-19','2026-07-24',909.0,'per_session','$909','https://www.ussportscamps.com/tennis/nike/nike-tennis-camp-mount-holyoke-college#session-80343-1214758',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','513d2de7-49ed-4e30-9004-68604bb48722','nike-tennis-camp-amherst-at-mount-holyoke-college-all-skills-program-all-skills--a3d3','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
