INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-1caf4d18-4fbc-5b97-afa1-651f1edd37e1','org-80f9aaaf-de61-5490-9ef6-020947fa797e','nike-tennis-camp-at-university-of-puget-sound-day-camp-july-27-30-2026','Nike Tennis Camp at University of Puget Sound - Day Camp (July 27ΓÇô30, 2026)','camp','camp_sports','["baseball_softball"]','Overnight Camp Our overnight camp at Puget Sound offers an immersive, on-campus experience where campers reside in the dormitories in adjacent rooms to the camp staff while training during the daytime hours. The tuition includes housing, meals, fun evening activities, as well as college recruiting seminars on Tuesday evening (parents are encouraged to attend the seminars!). Day Camp (9:00am-4:00pm) Nike Tennis Camps also offers a summer day camp program for athletes who do not wish to stay overnight. This program runs 9:00am-4:00pm each day and includes daytime training only. Campers can bring their own lunch or purchase on campus. Nike Sports Camp Experience At University of Puget Sound, Nike Sports Camps offers a unique experience with many sports (Baseball, Cross Country, Soccer, Softball, Swim, Tennis, and Track &amp; Field) operating simultaneously. During the day, the athletes receive sport-specific coaching within their sport focus. In the evening, overnight campers across all sports come together for a special camp-wide experience which includes fun field games, educational seminars, and more. Tennis Facilities/ Transportation The camp utilizes a combination of the University of Puget Sound and Bellarmine Preparatory School tennis complexes. For any off-campus training at Bellarmine Prep (less than two miles from Puget Sound), campers and staff are transported to and from by bus. The 2026 athletic facilities will be confirmed in the spring. The Nike Tennis Camp at University of Puget Sound is open to any and all entrants and limited only by number, age and gender. Athletic facilities and coaches are subject to change. The camp is not owned, sponsored, controlled or endorsed by University of Puget Sound.',10,17,'all','2026-07-27','2026-07-30',759.0,'per_session','$759','https://www.ussportscamps.com/tennis/nike/nike-tennis-camp-university-of-puget-sound#session-82014-1217103',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','a5d788fe-6a88-4e77-ab4b-dc88c25d418a','nike-tennis-camp-at-university-of-puget-sound-day-camp-july-27-30-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
