INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-51293734-26f3-5c14-9f1a-686ae8d3717c','org-718ab1c1-aadd-5832-979e-1babf47ff626','nike-baseball-camp-at-seattle-university-july-27-30-2026','Nike Baseball Camp at Seattle University -  (July 27ΓÇô30, 2026)','camp','camp_sports','["baseball_softball"]','Get ready for an awesome summer of baseball training at the Nike Baseball Camp at Seattle University! Take your game to the next level, sharpen your skills, and compete alongside other serious players. Led by Coach Leo Rivera, Assistant Baseball Coach at Seattle University, this camp offers high-level instruction in a fun, challenging, and competitive environment. Coach Rivera and his staff are committed to helping every player improve, reach their goals, and build confidence on and off the field. All skill levels are welcomeΓÇöcome ready to work hard, make new friends, and create memories that will last long after the final out of summer.',7,13,'all','2026-07-27','2026-07-30',429.0,'per_session','$429','https://www.ussportscamps.com/baseball/nike/nike-baseball-camp-seattle-university',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','18828958-62a5-4a0b-9601-140207473c70','nike-baseball-camp-at-seattle-university-july-27-30-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
