INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-babe76d7-465b-509d-a2d4-7dc1552bfdc4','org-41fec641-d5cb-5b97-bfd5-72075cd7ac49','nike-baseball-camp-at-home-plate-july-27-30-2026','Nike Baseball Camp at Home Plate -  (July 27ΓÇô30, 2026)','camp','camp_sports','["baseball_softball"]','Nike Baseball Camp at Home Plate in Peachtree City, GA is coming back in 2026, and we couldnΓÇÖt be more excited! ItΓÇÖs a great opportunity for young players to build their skills and grow their love for the game. Campers will get hands-on instruction from Director Walker Searcy and his awesome coaching staff, all in a fun, positive environment. Each day is packed with baseballΓÇöhitting, fielding, base running, and learning how to be a great teammate. Whether your child is just starting out or looking to take their game to the next level, this camp is designed to help them improve and have a blast doing it.',10,14,'all','2026-07-27','2026-07-30',379.0,'per_session','$379','https://www.ussportscamps.com/baseball/nike/nike-baseball-camp-home-plate',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','7f64cb08-be7f-4559-805c-8af20f33fe73','nike-baseball-camp-at-home-plate-july-27-30-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-75db8fa9-0701-5f73-a464-90fd5b8e9797','org-92dcbd8b-464e-562c-8172-9543817e22cc','nike-baseball-camp-at-university-of-puget-sound-day-camp-july-27-30-2026-ie9v','Nike Baseball Camp at University of Puget Sound - Day Camp (July 27ΓÇô30, 2026)','camp','camp_sports','["baseball_softball"]','Nike Baseball Camps is excited to return to University of Puget Sound in 2026! Register today and enjoy elite-level training while making memories to last a lifetime. The camp offers a unique opportunity to train under the direction of passionate coaches and current and former collegiate athletes who serve as counselors. The camp is open to athletes ages 10-17. Overnight Camp Our overnight camp at Puget Sound offers an immersive, on-campus experience where campers reside in the dormitories in adjacent rooms to the camp staff while training during the daytime hours. The tuition includes housing, meals, fun evening activities, as well as college recruiting seminars on Tuesday evening (parents are encouraged to attend the seminars!). Day Camp (9:00am ΓÇô 4:00pm) Nike Baseball Camps also offers a summer day camp program for athletes who do not wish to stay overnight. This program runs 9:00am-4:00pm each day and includes daytime training only. Campers can bring their own lunch or purchase on campus. Nike Sports Camp Experience At University of Puget Sound, Nike Sports Camps offers a unique experience with many sports (Baseball, Cross Country, Soccer, Softball, Swim, Tennis, and Track &amp; Field) operating simultaneously. During the day, the athletes receive sport-specific coaching within their sport focus. In the evening, overnight campers across all sports come together for a special camp-wide experience which includes fun field games, educational seminars, and more. Baseball Facilities/Transportation The camp utilizes a combination of the University of Puget Sound (Session #1) and Bellarmine Preparatory SchoolΓÇÖs (Session #2) baseball complexes. For any off-campus training, campers and staff are transported by bus to and from the baseball complex. The 2026 athletic facilities will be confirmed in the spring. The Nike Baseball Camp at University of Puget Sound is open to any and all entrants and limited only by number, age and gender. Athletic facilities and coaches are subject to change. The camp is not owned, sponsored, controlled or endorsed by University of Puget Sound.',8,17,'all','2026-07-27','2026-07-30',499.0,'per_session','$499','https://www.ussportscamps.com/baseball/nike/nike-baseball-camp-university-of-puget-sound',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','87b50bcc-88ee-448a-8667-490483258481','nike-baseball-camp-at-university-of-puget-sound-day-camp-july-27-30-2026-ie9v','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
