INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-e6350fca-c8f8-554e-aa8b-ac8e0bb409c1','org-c6a19cf4-2d29-5bed-b166-354120bb638a','summer-camp-water-week-2-tacoma','Summer Camp - Water Week 2 - Tacoma','camp','camp_general',NULL,'Five-day Tacoma day camp at the Mountaineers Tacoma Program Center for kids in grades 1-7 with a focus on water skills and safety. This week each camper gets a kayaking field trip on either Wednesday or Thursday. Campers also try river paddling, tide pooling, climbing, hiking, navigation, first aid, and knots. Friday meets at Point Defiance Park. Camp runs 8:30am to 4:30pm Monday through Thursday. Led by Sarah Holt.',6,13,'beginner','2026-07-27','2026-07-31',410.0,'per_session','$410 members / $435 guests','https://www.mountaineers.org/locations-lodges/tacoma-branch/committees/tacoma-youth-outreach-committee/course-templates/copy_of_water-week-tacoma/summer-camp-water-week-2-tacoma-2026',NULL,'waitlist','day',0,0,NULL,NULL,'scraped','active',90,'mountaineers.org','live','08f3878a-4a3f-4aaf-9790-3ca8dea5adab','summer-camp-water-week-2-tacoma','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-348f1b3a-0aed-56f4-8821-5be384f141c0','org-c6a19cf4-2d29-5bed-b166-354120bb638a','summer-camp-teen-adventures-rock-climbing-tacoma','Summer Camp - Teen Adventures: Rock Climbing - Tacoma','camp','camp_general',NULL,'Four-day teen rock climbing adventure for ages 13-17, all experience levels welcome. Tuesday is at the Tacoma Program Center for climbing basics including top-roping, belaying, rappelling, knots, and anchors. Wednesday through Friday is outdoor climbing at Exit 38 and Exit 32 with two nights of camping nearby. Skills covered may include lead belaying, mock-leading, leading on bolts, anchor building, and rescue skills. Participants may hike up to 1 mile with 30-pound packs. Led by Sarah Holt.',13,17,'all','2026-07-28','2026-07-31',495.0,'per_session','$495 members / $520 guests','https://www.mountaineers.org/locations-lodges/tacoma-branch/committees/tacoma-youth-outreach-committee/course-templates/copy2_of_summer-camp-teen-adventures-intro-backpacking-tacoma/summer-camp-teen-adventures-rock-climbing-tacoma-2026',NULL,'waitlist','overnight',0,0,NULL,NULL,'scraped','active',90,'mountaineers.org','live','f3baa3b8-6468-4e3c-9869-868b2e4f6d7b','summer-camp-teen-adventures-rock-climbing-tacoma','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-eb0e2db7-7250-5692-9352-35cbd59e691a','org-b81ef3c2-3888-5339-bd89-a7f6feec0012','sound-life-day-camp-week-6-adventure','Sound Life Day Camp - Week 6: Adventure','camp','camp_general',NULL,'Tacoma Christian day camp with daily off-site field trips. Week 6 themed Adventure with ice skating, canoeing at Sunset Lake, blueberry picking, the Olympia Farmers Market, and Friday swimming. Camp hours 8:15am to 4:30pm with free before-care 7:30 to 8:15am and aftercare 4:30 to 5:30pm. One-time $30 registration fee per camper.',6,13,'all','2026-07-27','2026-07-31',220.0,'per_session','$220/week plus $30 registration','https://www.soundlifedaycamp.com/tacoma',NULL,'open','day',0,0,NULL,NULL,'scraped','active',90,'soundlifedaycamp.com','live','8057c2db-b00f-42d0-8000-6a22e4e372ce','sound-life-day-camp-week-6-adventure','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-563bf66b-da4b-550c-83ff-d7a0077a1398','org-0b699443-57e1-5de3-a259-580a4a913699','wolf-camp-puyallup-wild-cooking-herbology','Wolf Camp Puyallup - Wild Cooking & Herbology','camp','camp_general',NULL,'Wild edible plants and outdoor cooking day camp at Clark''s Creek Park South Shelter and Blue Skye Farm in Puyallup. Campers identify edible and medicinal plants, prepare wild foods over campfires, and learn herbology basics. Best for campers focused in group learning environments or returning students. Daily schedule 9:00am to 3:45pm. 6:1 student-teacher ratio.',7,14,'beginner','2026-07-27','2026-07-31',495.0,'per_session','$495 full tuition (sliding scale available)','https://wolfcamp.org/youth/summer-day-camps-for-kids/puyallup-tacoma/',NULL,'open','day',0,0,NULL,NULL,'scraped','active',90,'wolfcamp.org','live','ab13b85e-fefe-448a-96aa-b7e58ef863ad','wolf-camp-puyallup-wild-cooking-herbology','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
