INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-5c2c5c10-72e8-545c-873f-5097c5899b8b','org-0257781c-9ced-5113-badf-d9a69c6ae80f','nike-soccer-camp-at-dallas-college-brookhaven-july-27-31-2026','Nike Soccer Camp at Dallas College - Brookhaven -  (July 27ΓÇô31, 2026)','camp','camp_sports','["soccer"]','Get ready for an unforgettable soccer experience at the Nike Soccer Camp at Dallas College Brookhaven in Dallas, TX! This actionΓÇæpacked camp is powered by Pro Level Training and led by renowned local player development experts Keondra Mallard and Eder Falcon, two highly respected coaches with proven experience training youth, high school, collegiate, and even professional athletes. Their coaching approach blends elite instruction with a strong focus on developing confident, intelligent, and technically skilled players. Campers will train on the conveniently located, premier athletic facilities at Dallas College Brookhaven, creating the perfect environment for learning, competing, and having fun. Designed for boys and girls ages 6ΓÇô16, this week-long program features a dynamic and progressive curriculum that emphasizes skill development, highΓÇæenergy drills, gameΓÇæbased learning, and nonstop excitement. Players will sharpen their technique, improve their soccer IQ, and enjoy fastΓÇæpaced activities that keep them engaged from start to finish. Join us this summer and take your game to the next level with one of the top training experiences in Texas!',6,16,'all','2026-07-27','2026-07-31',399.0,'per_session','$399','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-dallas-college-brookhaven#session-82736-1218079',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','f5684403-4bcf-453b-b765-ca0a49fb39f4','nike-soccer-camp-at-dallas-college-brookhaven-july-27-31-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-93bfa77d-8960-5c6e-9902-8b5da7f0810a','org-8b1b7970-dd7a-56bd-873f-09d08060afba','nike-soccer-camp-at-sofive-elkins-park-day-camp-july-27-31-2026','Nike Soccer Camp at Sofive Elkins Park - Day Camp (July 27ΓÇô31, 2026)','camp','camp_sports','["baseball_softball"]','Experience an actionΓÇæpacked week of worldΓÇæclass soccer training at the Nike Soccer Camp at Sofive Elkins Park in Elkins Park, Pennsylvania ΓÇö led by the internationally respected Gold &amp; Gray Soccer Academy. Founded by professional footballers David Gold and Ross Gray, Gold &amp; Gray has earned a reputation as one of ScotlandΓÇÖs premier development academies, trusted by MLS athletes and European professionals for cultivating top-tier youth talent. Open to boys and girls ages 6ΓÇô16 of all experience levels, this camp delivers an elite training environment inside a modern, state-of-the-art Sofive facility. Players benefit from a low coachΓÇætoΓÇæcamper ratio and receive personalized guidance from UEFAΓÇælicensed coaches who have trained youth athletes from renowned clubs including Celtic, Rangers, Hearts, and Hibs. Throughout the week, campers sharpen their technical skills, improve their speed of play and decision-making, and develop confidence through highΓÇæenergy sessions that blend professionalism with fun. ItΓÇÖs a chance to train like the pros, push your game forward, and experience the intensity and excitement of a true academy-style environment. Whether you''re aiming to elevate your game, build a stronger foundation, or simply enjoy an unforgettable week of soccer, this Nike Soccer Camp is the perfect opportunity to take your skills to the next level.',6,16,'all','2026-07-27','2026-07-31',265.0,'per_session','$265','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-sofive-elkins-park#session-83640-1219306',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','d28918f9-cf16-4533-b35a-8dca48cb7541','nike-soccer-camp-at-sofive-elkins-park-day-camp-july-27-31-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
