INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-e29693e8-306d-5320-b5b3-ff95a76c345f','org-9fa50d19-6da4-5af8-aa6e-307df90b858e','nike-soccer-camp-at-windward-school-july-27-31-2026','Nike Soccer Camp at Windward School -  (July 27ΓÇô31, 2026)','camp','camp_sports','["soccer"]','Get ready for one of LAΓÇÖs most popular youth soccer experiences! The Nike Soccer Camp at Windward School in Los Angeles, CA is back, and after selling out in 2025, itΓÇÖs expected to fill even faster this summer. Designed for players of all levels ages 6ΓÇô14, this highΓÇæenergy camp delivers a perfect blend of fun, development, and elite instruction in a supportive, confidenceΓÇæbuilding environment. Whether your athlete is just discovering the game or eager to sharpen their skills, this camp offers specialized technical training, individual player development, and engaging teamΓÇæbased sessions that help young players grow on and off the field. Set in the heart of sunny California, campers enjoy topΓÇætier coaching, exciting drills, smallΓÇæsided games, and a summer soccer atmosphere that keeps them active, motivated, and loving every minute. Join the action this year and see why this camp continues to be one of Los AngelesΓÇÖ fastestΓÇæfilling summer soccer programs, secure your spot before it sells out again!',6,14,'all','2026-07-27','2026-07-31',525.0,'per_session','$525','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-windward-school#session-81723-1216711',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','8f39f139-33ce-4758-b04f-fffcca4bf8b6','nike-soccer-camp-at-windward-school-july-27-31-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-26bd837e-040c-5c08-965b-d3b60bf2a82c','org-d52c4163-7c1b-5658-95a9-045b4922aca8','nike-soccer-camp-in-naples-july-27-31-2026','Nike Soccer Camp in Naples -  (July 27ΓÇô31, 2026)','camp','camp_sports','["soccer"]','In partnership with DP Soccer Coaching and led by David Popovski, widely recognized as a leader in individual player development, this camp delivers an unmatched training experience for boys and girls ages 6ΓÇô16. David is joined by former professional player Enoch Showunmi, renowned for his expertise in technical development. Together, they form an elite coaching duo committed to helping young athletes grow on and off the field. Across the actionΓÇæpacked week, players will sharpen technique, boost creativity, and develop a deeper understanding of the game through modern, playerΓÇæfocused coaching methods. All sessions take place on the beautifully manicured grass fields at Seacrest Country Day School, with access to indoor, airΓÇæconditioned spaces to stay cool and house fastΓÇæpaced Futsal play. If your player loves soccer and wants a fun, challenging week built around real development, this Nike Soccer Camp brings it all: elite coaching, topΓÇætier facilities, and a memorable summer experience designed to inspire confidence, growth, and passion for the game.',6,16,'all','2026-07-27','2026-07-31',270.0,'per_session','$270','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-naples-florida#session-84248-1220144',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','8959dbf9-eb92-46a8-86d0-5c1352281351','nike-soccer-camp-in-naples-july-27-31-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
