INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-87e34714-31c0-5d77-b57a-d527b8b48a5c','org-dd7b5fb6-8eed-5ea2-b27a-2d23bfc46d59','nike-soccer-camp-at-shippensburg-university-july-27-31-2026','Nike Soccer Camp at Shippensburg University -  (July 27ΓÇô31, 2026)','camp','camp_sports','["soccer"]','Experience an unforgettable week of soccer development at the Nike Soccer Camp at Shippensburg University, where boys and girls ages 6ΓÇô14 train on the beautiful, stateΓÇæofΓÇætheΓÇæart facilities of one of PennsylvaniaΓÇÖs most dynamic NCAA Division II campuses. This immersive camp is directed by Shippensburg University MenΓÇÖs Head Coach Jeremy Spering and Assistant Coach Matthew Garrett, an elite coaching team with decades of collegiate experience and a powerful reputation for developing youth players across Central Pennsylvania. Coach Spering and Coach Garrett bring a highΓÇælevel blend of tactical expertise, technical development, and playerΓÇæcentered instruction. Their coaching methodology ensures that every young athlete receives ageΓÇæappropriate, highΓÇæquality training, whether they are mastering the fundamentals, refining advanced skills, or learning how to read the game at a deeper level. Campers will thrive in a supportive, competitive, and energetic environment designed to boost confidence, sharpen soccer IQ, and inspire growth both on and off the field. Throughout the week, players will take part in fastΓÇæpaced drills, positionΓÇæspecific instruction, skillΓÇæenhancement sessions, smallΓÇæsided games, and fullΓÇæfield activities that encourage creativity, quick decisionΓÇæmaking, and teamwork. Training on Shippensburg UniversityΓÇÖs premier facilities gives athletes an inspiring collegiate setting where they can challenge themselves, make new friends, and experience what it feels like to train like a college Roadrunner. With elite coaching, exceptional fields, and a curriculum built to elevate young players of all abilities, this camp delivers one of the most exciting youth soccer experiences in Shippensburg, Franklin County, and the wider Central Pennsylvania region.',6,14,'all','2026-07-27','2026-07-31',230.0,'per_session','$230','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-shippensburg-university#session-81108-1215854',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','556b6185-6f7a-422c-8d8c-3b1d4085f9f8','nike-soccer-camp-at-shippensburg-university-july-27-31-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
