INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-7c4e16a5-6fc6-59da-912e-f502073db306','org-2af49157-4e0a-565a-8bad-522ebadeb9e9','nike-basketball-camp-at-west-monroe-sports-and-events-jr-basketball-camp-july-27','Nike Basketball Camp at West Monroe Sports and Events - Jr. Basketball Camp (July 27ΓÇô31, 2026)','camp','camp_sports','["baseball_softball"]','The Basketball Academy Camp is designed for athletes that are serious about raising their game to the next level. The RYG Athletics Basketball Academy combines classroom and court time to teach athletes (ages 10-14) the leadership, mindset, and basketball skills they need to thrive. The camp features two classroom sessions a day that dive into leadership, mindset, basketball principles of play and film. The twice daily court sessions give athletes the opportunity to immediately put into practice the things they''re learning in the classroom in a fun, challenging, and competitive environment. The Jr. Basketball Camp is designed for younger campers that are new to the sport. Campers receive an introduction to basketball and will learn basic concepts, terminology, and gross motor movements to help improve their skills and confidence.',10,14,'all','2026-07-27','2026-07-31',199.0,'per_session','$199','https://www.ussportscamps.com/basketball/nike/nike-basketball-camp-west-monroe#session-79169-1212609',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','8ca1ade7-6aff-4782-bd98-cd2c45828bc0','nike-basketball-camp-at-west-monroe-sports-and-events-jr-basketball-camp-july-27','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
