','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','addd3244-0598-443c-9ea3-bdbc84902db2','nike-tennis-camp-amherst-at-mount-holyoke-college-all-skills-program-all-skills--8s7q','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
