INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-57e34159-48f5-5253-9fbb-a376cd371dec','org-6529a48e-db40-5277-abd0-8d11fef74d48','nike-baseball-camp-in-bothell-all-skills-camp-july-28-31-2026','Nike Baseball Camp in Bothell - All Skills Camp (July 28ΓÇô31, 2026)','camp','camp_sports','["baseball_softball"]','Our staff is dedicated to making your stay the single most important days in your baseball career. The purpose of our camps is to teach the fundamentals as well as the advanced skills of baseball to various age levels, helping each participant to better understand the game both mentally and physically. Joining us will allow players to further develop individual skills through instruction, individual and multi-player drills, and game experience, as well as interaction with players off the field in a comfortable camp setting. Players will work hard while having fun at the same time.',7,18,'all','2026-07-28','2026-07-31',429.0,'per_session','$429','https://www.ussportscamps.com/baseball/nike/baseball-camp-bothell',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','1d001054-f0d2-4683-a52d-c3f5508c2685','nike-baseball-camp-in-bothell-all-skills-camp-july-28-31-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-dd09a7b7-84bf-5141-938a-0d213ffa9343','org-587ead20-4e7f-5fa9-82a9-06a1c15fdef4','nike-baseball-camp-at-on-deck-in-prince-george-s-county-july-27-31-2026','Nike Baseball Camp at On-Deck in Prince GeorgeΓÇÖs County -  (July 27ΓÇô31, 2026)','camp','camp_sports','["baseball_softball"]','The Nike Baseball Camp at On-Deck in Prince GeorgeΓÇÖs County offers a high-level training experience in an intimate, athlete-focused environment. Directed by Andre Hockaday and the professional coaching staff at On-Deck, this camp is designed for players who want focused instruction, personalized feedback, and serious skill developmentΓÇöwithout losing the fun of the game. This summer, the camp will run four weekly sessions throughout the month of July, with camp held Monday through Friday from 9:00amΓÇô3:00pm. Each week features four days of skill development inside the state-of-the-art On-Deck indoor facility, followed by a final day of live scrimmages and gameplay on the turf baseball field at Prince GeorgeΓÇÖs Community College. The On-Deck facility is a 7,000-square-foot, air-conditioned training space equipped with a large indoor turf field, five batting cages, and modern baseball training technology. With just 50 campers per week, athletes receive extensive one-on-one instruction and small-group coaching from experienced professional baseball coaches and trainers. Campers can expect a well-rounded experience that blends advanced skill development, competitive gameplay, and a positive, high-energy atmosphereΓÇöall built to help players grow their confidence, sharpen their skills, and enjoy every day at camp.',6,12,'all','2026-07-27','2026-07-31',399.0,'per_session','$399','https://www.ussportscamps.com/baseball/nike/nike-baseball-camp-on-deck-prince-georges-county',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','10ad23c1-0b31-4554-a9c8-76e1fcbf66ab','nike-baseball-camp-at-on-deck-in-prince-george-s-county-july-27-31-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
