INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-a2181e67-7410-5228-a0bd-6b9bb9ad7eaf','org-d25c8fa4-8ae6-5f91-987c-75217c431ef3','nike-baseball-camp-at-uwm-field-directed-by-united-states-professional-baseball-','Nike Baseball Camp at UWM Field, directed by United States Professional Baseball League -  (Aug. 3ΓÇô5, 2026)','camp','camp_sports','["baseball_softball"]','Join us in the summer of 2026 for an exciting Nike Baseball Camp at UWM Field in Utica, MI, the home field of the United States Professional Baseball League (USPBL)! The camp will be led by Justin Karn,Manager of the Westside Woolly Mammoths and member of the USPBL coaching staff for the past four years. Karn brings extensive collegiate coaching experience from programs such as Madonna University, Oakland University, and St. Thomas Aquinas, where he helped guide teams to championships and national tournament appearances. His proven track record of developing talent at both the collegiate and professional levels makes this a can''t-miss opportunity for aspiring ballplayers. Campers 7-12 years old will have an awesome time making new friends, memories, and gaining baseball skills that will help them become better players on the field. Don''t miss this opportunity to be instructed by players and coaches from the Birmingham Bloomfield Beavers, Eastside Diamond Hoppers, Utica Unicorns, and the Westside Woolly Mammoths. Sign up today!',7,12,'all','2026-08-03','2026-08-05',325.0,'per_session','$325','https://www.ussportscamps.com/baseball/nike/nike-baseball-camp-united-states-professional-baseball-league',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','89e73faf-8d54-4f62-b681-195370e85d3f','nike-baseball-camp-at-uwm-field-directed-by-united-states-professional-baseball-','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
