INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-c769f0a1-ef79-55cc-ae54-8d16375f9b7e','org-8cdc645c-d7cf-5841-8485-7ff911d0404a','free-capoeira-camp','Free Capoeira Camp','camp','camp_general',NULL,'This free week-long camp at Tacoma Capoeira Center introduces kids to capoeira, the Afro-Brazilian martial art that blends movement, music, and acrobatics. Campers learn basic kicks, dodges, and floor work, plus the songs and instruments that accompany the roda. The camp is taught by trained capoeira instructors and is open to beginners. Comfortable clothes and water are all that is needed.',7,14,'beginner','2026-08-03','2026-08-07',0.0,'free','Free','https://tacomacapoeiracenter.com/',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,NULL,'live','6149a9c9-7803-4341-9e38-4a58d222ed3f','free-capoeira-camp','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-f66a4970-75c2-5f64-9ac2-bebb04cc6054','org-7e1cf729-d308-5a17-9f1d-3f519bd86b64','camp-create-week-7','Camp Create Week 7','camp','camp_general',NULL,'Camp Create is the City of Lakewood Parks and Recreation summer day camp held at Park Lodge Elementary School. Week 7 runs Monday through Friday with drop-off at 8:00 AM and pickup at 5:00 PM. Campers ages 6 through 9 take part in activities, games, and field trip visits. Run by Lakewood Parks and Recreation staff. Registration is through the city''s ActiveNet portal.',6,9,'all','2026-08-03','2026-08-07',140.0,'per_session','$140','https://anc.apm.activecommunities.com/lakewoodparksandrec/activity/search?onlineSiteId=0&from_original_cui=true&activity_id=5272',NULL,'open','day',0,0,NULL,NULL,'scraped','active',90,'anc.apm.activecommunities.com','live','5fbb8ef4-c9c0-421d-b71b-18a97f63ac6d','camp-create-week-7','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
