INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-b0a84ed5-4ce9-5323-8aa4-b786640239d0','org-9e8101d7-6558-58e4-b710-b7c6ce828a2e','camp-yougottawanna-week-7','Camp Yougottawanna Week 7','camp','camp_general',NULL,'Puyallup Parks and Recreation summer day camp at the Puyallup Activity Center. Sports, games, swim, art, and field trips with Parks and Recreation staff.',6,12,'all','2026-08-03','2026-08-07',225.0,'per_session','$225','https://secure.rec1.com/WA/puyallup-parks-recreation/catalog',NULL,'open','day',0,0,NULL,NULL,'scraped','active',90,'secure.rec1.com','live','c8bbf09e-b076-4d53-ab57-8254668817dc','camp-yougottawanna-week-7','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-d990b4b4-bdbf-5dba-ac7e-aaf505f46b5c','org-c6a19cf4-2d29-5bed-b166-354120bb638a','summer-camp-nature-arts-crafts-week-2-tacoma','Summer Camp - Nature Arts & Crafts Week 2 - Tacoma','camp','camp_general',NULL,'Five-day Tacoma day camp at the Mountaineers Tacoma Program Center for kids in grades 1-7 connecting outdoor skills with arts and crafts. Wednesday and Thursday are field trip days with an easy hike in the Mt. Rainier area focused on nature photography and watercolor painting. Activities may include climbing, rope skills, navigation, wilderness first aid, drawing, mural creation, 3D topographic maps, ropes-based crafts, paper mache, tie-dye, and pyrography. Friday meets at Point Defiance Park. Camp runs 8:30am to 4:30pm. Led by Sarah Holt.',6,13,'beginner','2026-08-03','2026-08-07',385.0,'per_session','$385 members / $410 guests','https://www.mountaineers.org/locations-lodges/tacoma-branch/committees/tacoma-youth-outreach-committee/course-templates/copy2_of_wilderness-week-tacoma/summer-camp-nature-arts-crafts-week-2-tacoma-2026',NULL,'waitlist','day',0,0,NULL,NULL,'scraped','active',90,'mountaineers.org','live','f4b687f0-c71d-403a-951f-327172c81527','summer-camp-nature-arts-crafts-week-2-tacoma','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-2eb5f162-6efb-5d46-bfa4-e5e3d0fbf119','org-b81ef3c2-3888-5339-bd89-a7f6feec0012','sound-life-day-camp-week-7-aquatics','Sound Life Day Camp - Week 7: Aquatics','camp','camp_general',NULL,'Tacoma Christian day camp with daily off-site field trips. Week 7 themed Aquatics with multiple boating and tubing days, a Pike Place Market trip, and Friday swimming. Camp hours 8:15am to 4:30pm with free before-care 7:30 to 8:15am and aftercare 4:30 to 5:30pm. One-time $30 registration fee per camper.',6,13,'all','2026-08-03','2026-08-07',220.0,'per_session','$220/week plus $30 registration','https://www.soundlifedaycamp.com/tacoma',NULL,'open','day',0,0,NULL,NULL,'scraped','active',90,'soundlifedaycamp.com','live','93711424-d27a-4bbe-a117-c9dab77f5b97','sound-life-day-camp-week-7-aquatics','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-67946cb3-fa7e-5f39-aade-f0e0e6766287','org-0b699443-57e1-5de3-a259-580a4a913699','wolf-camp-puyallup-intro-advanced-wilderness-survival','Wolf Camp Puyallup - Intro & Advanced Wilderness Survival','camp','camp_general',NULL,'Combined intro and advanced wilderness survival day camp running concurrently at Clark''s Creek Park South Shelter and Blue Skye Farm. Campers without prerequisites join the intro track while returning campers can take the advanced wilderness survival track. Daily schedule 9:00am to 3:45pm with morning lessons, lunch with games and archery, and afternoon activities. 6:1 student-teacher ratio.',8,15,'all','2026-08-03','2026-08-07',495.0,'per_session','$495 full tuition (sliding scale available)','https://wolfcamp.org/youth/summer-day-camps-for-kids/puyallup-tacoma/',NULL,'open','day',0,0,NULL,NULL,'scraped','active',90,'wolfcamp.org','live','131f1a6f-2e19-42e8-b57b-d214269e0f91','wolf-camp-puyallup-intro-advanced-wilderness-survival','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
