INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-dcfe16a5-3c54-5792-ba47-1da6e6a7ec31','org-5cc37238-3584-5f83-9290-c9a82bfb9111','nike-soccer-camp-at-sofive-covina-aug-3-7-2026','Nike Soccer Camp at Sofive Covina -  (Aug. 3ΓÇô7, 2026)','camp','camp_sports','["soccer"]','Experience elite training this summer at the Nike Soccer Camp at Sofive Covina, powered by the regionally respected playerΓÇædevelopment expertise of Coach Chris Bonawandt and his renowned Los Angeles Soccer Camp organization. Known across the Los Angeles area for producing confident, technically skilled players and running some of the regionΓÇÖs most trusted youth soccer camps, Coach Chris brings his proven training model to Rancho Cucamonga for an unforgettable week of growth and excitement. Hosted at Sofive Covina, a state-of-the-art soccer facility built for fast-paced play and top-tier instruction, this camp offers the perfect environment for players to sharpen their skills and take their game to the next level. Open to boys and girls ages 6ΓÇô16 of all experience levels, the program features a low coach-to-camper ratio, ensuring every athlete receives personalized feedback, quality repetitions, and individual attention. Campers will develop new techniques, strengthen fundamentals, improve decision-making, and build confidence through dynamic drills and competitive play. ΓÇ£At LA Soccer Camps, our goal is simple, we want kids from all backgrounds to have fun, play the game, and continue developing their skills. Each week we focus on one core fundamental each day, like dribbling, turning, passing, receiving, and shooting, so players can really lock in and build confidence. More than anything, we want kids to leave camp smiling, proud of what they learned, and excited to come back the next day.ΓÇ¥ - Chris Bonawandt, Camp Director',6,16,'all','2026-08-03','2026-08-07',310.0,'per_session','$310','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-sofive-covina#session-82124-1217236',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','fa7461db-edf8-4228-bc3f-140f8427b95e','nike-soccer-camp-at-sofive-covina-aug-3-7-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
