INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-b1a5f89c-d562-5b60-8906-9176899dbc1f','org-d997a62d-f789-5279-ba08-28756a8dc4ae','nike-soccer-camp-in-river-forest-aug-3-7-2026','Nike Soccer Camp in River Forest -  (Aug. 3ΓÇô7, 2026)','camp','camp_sports','["soccer"]','Soccer Skill Schools was voted a Top-10 Nike Soccer Camp in 2024 &amp; 2025 by players and parents! Join us for the Nike Soccer Camp in River Forest with Kyle Jones, Director of Soccer Skill Schools. This camp welcomes players of all abilities, ages 6-16, to develop and refine their technical skills in a dynamic, competitive environment. It''s an exceptional opportunity for any player to train under top coaching professionals while having fun and pushing their game to the next level! Soccer Skill Schools'' "Numbers Approach Methodology" brings world-class skill development methods from Brazil, Holland, England, and Spain directly to the Midwest. The Soccer Skill School approach focuses on the individual player by guiding each athlete toward complete mastery of the ball, empowering them to make their own creative decisions, and equipping them with 65+ individual skills to win the one-on-one competitions that determine every game''s outcome. Led by experienced college coaches and current college players, the Soccer Skill Schools staff brings elite-level expertise and mentorship to every session. Training alongside coaches who compete at the collegiate level gives players invaluable insight into what it takes to elevate their game and succeed at the next level! Hear from Coach Kyle Jones: ΓÇ£We create an environment where players are challenged, supported, and inspired every day. Through high-quality coaching and a love for the game, our goal is to help each athlete build confidence, develop their skills, and leave camp better both on and off the field.ΓÇ¥',6,16,'all','2026-08-03','2026-08-07',520.0,'per_session','$520','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-river-forest#session-81931-1216998',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','870e0a51-fd51-4899-a4e3-4483f579b064','nike-soccer-camp-in-river-forest-aug-3-7-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-08907edd-31fa-59d8-bdcd-c4864a565e1d','org-60e599f5-6d03-5088-952f-c5b5ad6db7f7','nike-soccer-camp-in-brooklyn-aug-3-7-2026','Nike Soccer Camp in Brooklyn -  (Aug. 3ΓÇô7, 2026)','camp','camp_sports','["soccer"]','Join us this summer for the Nike Soccer Camp in Brooklyn, a highΓÇæenergy training experience created through a strategic collaboration between Danny Segelin at Brooklyn Force Soccer Club and Max Watson, Head Coach at University of Mount Saint Vincent MenΓÇÖs Soccer Program. Coaches Watson and Segelin will lead the camp alongside staff from both UMSV MenΓÇÖs Soccer and Brooklyn Force, delivering an elite yet accessible environment for young male and female players ages 6ΓÇô14. This dynamic program blends topΓÇælevel technical instruction with fun, competitive play. Campers will work daily on sharpening their first touch, close control, quick passing combinations, creative attacking ideas, and overall confidence on the ball. Whether your child is new to the game or looking to elevate their technical level, this camp offers the perfect mix of focused skill development, smallΓÇæsided competition, and a positive, highΓÇæenergy learning environment, all right at the historic Parade Grounds in Brooklyn.',6,14,'all','2026-08-03','2026-08-07',399.0,'per_session','$399','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-brooklyn-new-york#session-84265-1220166',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','646ba0ed-b87a-4d50-8af0-ecebdda