INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-73be6024-6cda-580a-8548-e3e334472e22','org-47d35f44-4446-5cab-80ff-d1cac4de2fa1','nike-soccer-camp-with-prospect-soccer-academy-4s-ranch-sports-park-aug-3-7-2026-w455','Nike Soccer Camp with Prospect Soccer Academy - 4S Ranch Sports Park -  (Aug. 3ΓÇô7, 2026)','camp','camp_sports','["baseball_softball"]','Join us for another exciting summer at the Nike Soccer Camp with Prospect Soccer Academy in 4S Ranch, San Diego, held at 4S Ranch Sports Park. Led by Coach Harry Forrester and the Prospect Soccer Academy staff, this returning camp welcomes boys and girls ages 6ΓÇô14 of all ability levels for a high-quality training experience focused on technical development, tactical understanding, and overall soccer IQ in a fun and supportive environment.Prospect Soccer Academy is a premier Southern California development program led by former professional players who run a full-time academy dedicated to developing players at every level. With a wealth of playing and coaching experience, the staff delivers a high-energy, player-centered environment built around long-term growth, confidence, and enjoyment of the game.Set at 4S Ranch Sports Park, a top youth soccer facility in San Diego, players train on quality fields in a professional yet welcoming setting. The curriculum blends proven fundamentals with modern, game-based training designed to improve decision-making, technical ability, and performance under pressure.This camp continues to be a trusted favorite for families in the San Diego area, offering young players the chance to learn, compete, and grow under experienced, passionate coaches in a positive and engaging environment. Hear from Co-Owner of Prospect Soccer Academy and Camp Director Harry Forrester: "Our camps are delivered by seasoned professional players and coaches who bring real game experience into every session. Built around a proven, development-first philosophy, we prioritize technical excellence through high-repetition training and game-realistic scenarios such as 1v1 and 2v2, helping players build confidence, decision-making, and creativity under pressure. Just as important is the environment we create, structured, supportive, and professionally led, where players are encouraged to take risks, learn from mistakes, and grow. Our goal is for every player to leave not only as a more complete footballer, but with greater confidence, resilience, and a genuine love for the game.ΓÇ¥ Prospect Soccer Academy will be hosting camps in multiple other locations Click here for more info',6,14,'all','2026-08-03','2026-08-07',365.0,'per_session','$365-$485','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-4s-ranch-sports-park-san-diego',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','03ef4837-dc5c-45df-b5a6-843af0fb1be2','nike-soccer-camp-with-prospect-soccer-academy-4s-ranch-sports-park-aug-3-7-2026-w455','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-de5893dc-9791-5c86-81f7-12c67d4b5065','org-ae068dfc-b126-5bcf-a714-228868f5c8b9','nike-soccer-camp-at-oak-brook-sports-core-day-camp-aug-3-7-2026-nz12','Nike Soccer Camp at Oak Brook Sports Core - Day Camp (Aug. 3ΓÇô7, 2026)','camp','camp_sports','["soccer"]','Join us this summer for the Nike Soccer Camp in Oak Brook, Illinois the new home of the former Elmhurst camps. Directing the camp will be Dave DiTomasso former Head Men''s Soccer Coach at Elmhurst University and Pablo Aguillar head coach of three teams with Empire FC. The camp is designed for boys and girls, of all abilities, ages 6-17. The focus at camp will be to develop athletically, refine their fundamental skills and enhance their technique, players will also get to develop position-specific skills via focused training. An amazing opportunity for any player to learn from a top college coaching staff and supplement their training in a fun and competitive setting!',6,17,'all','2026-08-03','2026-08-07',319.0,'per_session','$319-$439','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-oak-brook',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','fa69740f-2ca5-4bf9-a011-6f7703168ae5','nike-soccer-camp-at-oak-brook-sports-core-day-camp-aug-3-7-2026-nz12','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-7ec3be8c-7f26-5a77-b41f-e412f82551e4','org-8920127e-03c9-539a-9bff-59d0959d40f2','nike-soccer-camp-at-brookwood-school-aug-3-7-2026','Nike Soccer Camp at Brookwood School -  (Aug. 3ΓÇô7, 2026)','camp','camp_sports','["soccer"]','Next Step Training was voted a top 10 Nike Soccer Camp in 2025 by players and parents! Next Step''s soccer camps provide exceptional coaching and a welcoming atmosphere that helps players of all levels grow. With engaging drills, supportive instructors, and a strong emphasis on teamwork, it creates an exciting environment where kids can build confidence, improve their skills, and have a great time on the field.Join us for an amazing week of Nike Soccer Camp at Brookwood School with Camp Director Nicholas Woodruff and Next Step Training for the ultimate soccer training camp! Set against the scenic backdrop of Manchester-by-the-Sea, this camp offers not just first in class soccer training, but an idyllic setting for young athletes to develop their skills. Brookwood SchoolΓÇÖs facilities provide the perfect environment for both beginners and advanced players to immerse themselves in the sport they love. Make friends and memories that last a life time! "At Next Step Soccer, our camps are built around one simple idea, develop the player, not just the session. Every activity is designed to improve how players think, move, and make decisions in the game, while building confidence and a genuine love for soccer. We create a high-energy, supportive environment where players are challenged, coached with purpose, and leave each day better than they arrived, both on and off the field." - Nick Woodruff, Camp Director &amp; Founder, Next Step Training',6,16,'all','2026-08-03','2026-08-07',335.0,'per_session','$335-$455','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-brookwood-school',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','a02166c1-b7e6-4b34-ba18-093755fc14b6','nike-soccer-camp-at-brookwood-school-aug-3-7-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-71ae80fa-1f8c-5339-8115-1025118fe937','org-5cc37238-3584-5f83-9290-c9a82bfb9111','nike-soccer-camp-at-sofive-covina-aug-3-7-2026-jug9','Nike Soccer Camp at Sofive Covina -  (Aug. 3ΓÇô7, 2026)','camp','camp_sports','["soccer"]','Experience elite training this summer at the Nike Soccer Camp at Sofive Covina, powered by the regionally respected playerΓÇædevelopment expertise of Coach Chris Bonawandt and his renowned Los Angeles Soccer Camp organization. Known across the Los Angeles area for producing confident, technically skilled players and running some of the regionΓÇÖs most trusted youth soccer camps, Coach Chris brings his proven training model to Rancho Cucamonga for an unforgettable week of growth and excitement. Hosted at Sofive Covina, a state-of-the-art soccer facility built for fast-paced play and top-tier instruction, this camp offers the perfect environment for players to sharpen their skills and take their game to the next level. Open to boys and girls ages 6ΓÇô16 of all experience levels, the program features a low coach-to-camper ratio, ensuring every athlete receives personalized feedback, quality repetitions, and individual attention. Campers will develop new techniques, strengthen fundamentals, improve decision-making, and build confidence through dynamic drills and competitive play. ΓÇ£At LA Soccer Camps, our goal is simple, we want kids from all backgrounds to have fun, play the game, and continue developing their skills. Each week we focus on one core fundamental each day, like dribbling, turning, passing, receiving, and shooting, so players can really lock in and build confidence. More than anything, we want kids to leave camp smiling, proud of what they learned, and excited to come back the next day.ΓÇ¥ - Chris Bonawandt, Camp Director',6,16,'all','2026-08-03','2026-08-07',310.0,'per_session','$310-$420','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-sofive-covina',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','1aa08851-c269-4dbd-8af3-bb52b32f40b6','nike-soccer-camp-at-sofive-covina-aug-3-7-2026-jug9','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
