INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-06800183-32bf-5fe6-9fbd-21343fd7e1d0','org-2e5217da-a660-56b5-9149-f61217080166','nike-girls-soccer-camp-in-eagle-aug-3-7-2026','Nike Girls Soccer Camp in Eagle -  (Aug. 3ΓÇô7, 2026)','camp','camp_sports','["soccer"]','Each day blends high-level tactical and technical training with competitive gameplay, while intentionally teaching athletes confidence, grit, and resilience. The camp curriculum, designed by Indie Chicas President Allison Gibson, is rooted in self-belief and growth mindset, encouraging campers to train hard, take risks, embrace mistakes, and discover what theyΓÇÖre capable of. Through a fun yet challenging environment, players learn that mistakes are not setbacks, but powerful tools for growth and self-trust. Led by an experienced collegiate coaching staff, this camp fosters a supportive, female-centered space where athletes build skills, leadership, and lasting friendships. Campers leave not only sharper technically, but more confident, motivated, and inspired to bring their learning back to their teams and into all areas of their lives.',4,16,'all','2026-08-03','2026-08-07',155.0,'per_session','$155-$355','https://www.ussportscamps.com/soccer/nike/nike-girls-soccer-camp-eagle',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','42eb8f00-eb90-4279-8708-bea304ae3482','nike-girls-soccer-camp-in-eagle-aug-3-7-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-2df32ce6-3347-5e33-ab50-8917dc92a3c5','org-92346679-8d9a-53fa-b1a5-671c5bc2c6d9','nike-soccer-camp-at-takoma-park-aug-3-7-2026','Nike Soccer Camp at Takoma Park -  (Aug. 3ΓÇô7, 2026)','camp','camp_sports','["soccer"]','Experience an incredible camp at the Nike Soccer Camp in Takoma Park (formerly Washington Adventist University), Maryland, hosted at Ed Wilhelm Soccer Field! Led by WAU MenΓÇÖs Head Coach Daniel Carroll alongside the WAU menΓÇÖs soccer and PhiloSoccer Training coaching staff, this camp delivers far more than elite soccer instruction, it offers a truly transformative experience. The program is built on the belief that a great sports camp should teach not only the game, but also the life skills soccer uniquely develops: challenge, discipline, teamwork, selfΓÇæexpression, resilience, creativity, and sportsmanship. A thoughtfully designed curriculum blends fundamental through advanced soccer skills with both timeΓÇætested and innovative coaching methods, ensuring players grow on and off the field. Through daily training, guided competition, and intentional mentorship, athletes are encouraged to shine, embrace adversity, and step into the best versions of themselves each and every day. This unforgettable soccer training experience helps players elevate confidence, character, and performance while advancing to new heights in soccer excellence. Hear from Camp Director Daniel Carroll: "PhiloSoccer camps are about more than soccer! We believe a true sports camp should deliver and teach players all of the many life skills that the game has to offer, through: challenge, discipline, teamwork, self-expression, adversity, creativity and sportsmanship. Our curriculum is designed to teach fundamental to advanced soccer skills and techniques but also help players shine and step into the best versions of themselves each and every day."',8,16,'all','2026-08-03','2026-08-07',295.0,'per_session','$295-$399','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-takoma-park-md',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','00517d8d-51c3-438c-ac34-48ca52594d79','nike-soccer-camp-at-takoma-park-aug-3-7-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-92816d18-19fc-5934-a2e9-0182aaa7530f','org-71df811a-1009-57c6-a2fb-25d3ac80a606','nike-soccer-camp-with-next-step-training-in-holliston-aug-10-12-2026','Nike Soccer Camp with Next Step Training in Holliston -  (Aug. 10ΓÇô12, 2026)','camp','camp_sports','["soccer"]','Next Step Training was voted a top 10 Nike Soccer Camp in 2025 by players and parents! Next Step''s soccer camps provide exceptional coaching and a welcoming atmosphere that helps players of all levels grow. With engaging drills, supportive instructors, and a strong emphasis on teamwork, it creates an exciting environment where kids can build confidence, improve their skills, and have a great time on the field. Join us for an amazing week of camp at the Nike Soccer Camp with Next Step Training in Holliston, MA. Team up with Camp Director Nicholas Woodruff for the ultimate soccer training camp! Next Step Training was founded in order to provide a unique competitive experience for the BEST local kids in and around the Southeastern Massachusetts/Rhode Island area. The combination of high-level coaching, invite-only environments, and a true club-neutral philosophy makes Next Step one of the most elite supplemental training experiences in New England. The overall goal of each training session is to provide technical, tactical, and mental growth while encouraging players to be creative to help them become the most complete version of themselves. "At Next Step Soccer, our camps are built around one simple idea, develop the player, not just the session. Every activity is designed to improve how players think, move, and make decisions in the game, while building confidence and a genuine love for soccer. We create a high-energy, supportive environment where players are challenged, coached with purpose, and leave each day better than they arrived, both on and off the field." - Nick Woodruff, Camp Director &amp; Founder, Next Step Training',7,17,'all','2026-08-10','2026-08-12',269.0,'per_session','$269-$359','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-next-step-training-holliston',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','9354a8a2-01de-471b-9d74-c9b8fcf77cd1','nike-soccer-camp-with-next-step-training-in-holliston-aug-10-12-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
