INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-4d0c3a75-5cd5-5f68-9026-148b89bc80d9','org-9d4d04c9-fe18-5eb3-81db-38b000162bde','nike-tennis-camp-at-stanford-university-frankie-brennan-aug-10-13-2026','Nike Tennis Camp at Stanford University - Frankie Brennan -  (Aug. 10ΓÇô13, 2026)','camp','camp_sports','["tennis"]','Looking to elevate your game this summer? DonΓÇÖt miss out on our Full-Day Junior Summer Camp! These sessions are designed for players who are ready to take their skills to the next level. Our week-long camp features four dynamic rotations: Serve &amp; Return Courts, Ball Machine Drills, Live Ball Drills, and Conditioning. You''ll receive expert instruction and the chance to compete in high-intensity drills and practice matches.',9,17,'all','2026-08-10','2026-08-13',979.0,'per_session','$979','https://www.ussportscamps.com/tennis/nike/stanford-university-nike-tennis-camp-lele-forood#session-79805-1213754',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','88e84b10-4554-47cd-865f-c37d05a0c6e6','nike-tennis-camp-at-stanford-university-frankie-brennan-aug-10-13-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-2551bb79-ea8a-56d0-8528-0e2b08595266','org-f31ad8f4-137a-582f-a799-3dc26da405bd','nike-tennis-camp-at-university-of-hawaii-manoa-half-day-camp-aug-10-13-2026','Nike Tennis Camp at University of Hawaii, Manoa - Half Day Camp (Aug. 10ΓÇô13, 2026)','camp','camp_sports','["tennis"]','ADULT TENNIS CAMP AT UNIVERSITY OF HAWAII, MANOA We''re excited to also bring you the Adult Tennis Camp at the University of Hawaii at Manoa! Click the link for details. *If you are a returning camper, feel free to sign up via phone at (800) 645-3226 (Mon-Fri 8am-5pm PST) for a much quicker enrollment process*',6,18,'all','2026-08-10','2026-08-13',399.0,'per_session','$399','https://www.ussportscamps.com/tennis/nike/nike-tennis-camp-university-of-hawaii-manoa#session-84737-1220834',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','e2a4a106-95f9-42db-8384-7be6bebf0289','nike-tennis-camp-at-university-of-hawaii-manoa-half-day-camp-aug-10-13-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-7c35d97f-aa3a-56bc-a9b0-024aa29f51a5','org-4a3efbc7-5ece-57c7-8e77-54f84475ee0f','nike-tennis-camp-at-lewis-clark-college-aug-10-13-2026','Nike Tennis Camp at Lewis & Clark College -  (Aug. 10ΓÇô13, 2026)','camp','camp_sports','["tennis"]','Join us for an unforgettable tennis experience for junior players ages 8-17 at the Nike Tennis Camp at Lewis &amp; Clark College in Portland, Oregon. We offer winter, spring and summer sessions, providing young athletes the opportunity to work on their game year-round. This camp combines expert instruction, intensive drilling, and exciting competitive play, ensuring a well-rounded development for every player. Participants will have many opportunities to practice their skills, technique, and engage in friendly competition with peers who share their passion for tennis! Whether you''re a beginner or looking to refine your advanced skills, our camp is designed to challenge and inspire players of all levels. Get ready to hit countless balls, learn from experienced coaches, and make lasting friendships.',13,17,'all','2026-08-10','2026-08-13',799.0,'per_session','$799','https://www.ussportscamps.com/tennis/nike/nike-tennis-camp-at-lewis-clark-college#session-80267-1214621',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','55cf33ad-b739-4f1d-b843-d1b98e7b16ba','nike-tennis-camp-at-lewis-clark-college-aug-10-13-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-4d64e3e5-2ca7-5056-8916-7f97fd1e3589','org-fa56bc85-b165-5fac-8861-87f4435be8c8','nike-baseball-camp-at-edgewood-university-aug-10-13-2026','Nike Baseball Camp at Edgewood University -  (Aug. 10ΓÇô13, 2026)','camp','camp_sports','["baseball_softball"]','Get ready for another outstanding Nike Baseball Camp at Edgewood University in Verona, Wisconsin! After a fantastic 2025 camp, the coaching staff is energized and ready to make 2026 even better. Athletes of all abilities are encouraged to join us this summer to gain valuable baseball experience and create lasting memories. Quality facilities, knowledgeable coaches, and a positive, growth-focused environment continue to define this camp. All baseball fundamentals will be covered, including throwing, running, fielding, batting, bunting, baserunning, and pitching. Along with instruction and drill work, campers will enjoy fun, modified drills and games designed to enhance skill development. Pitchers and catchers wonΓÇÖt want to miss the additional Pitching/Catching Session on Friday the 14thΓÇöa great opportunity to refine mechanics and elevate performance both on the mound and behind the plate.',7,13,'all','2026-08-10','2026-08-13',349.0,'per_session','$349','https://www.ussportscamps.com/baseball/nike/nike-baseball-camp-edgewood-university',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','d18dc173-23d5-46ce-9d10-013917c54a5f','nike-baseball-camp-at-edgewood-university-aug-10-13-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
