INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-1c6f5c77-fe2c-5bdb-8aed-8a5de547e298','org-e6f558a0-65a8-57fd-b64d-d77b8a039758','nike-baseball-camp-at-maimonides-park-directed-by-brooklyn-cyclones-aug-11-13-20','Nike Baseball Camp at Maimonides Park, directed by Brooklyn Cyclones -  (Aug. 11ΓÇô13, 2026)','camp','camp_sports','["baseball_softball"]','This summer, the Brooklyn Cyclones, the High-A Affiliate of the New York Mets and a proud member of the South Atlantic League, are excited to host the Nike Baseball Camp at Maimonides Park in Brooklyn, NY. Whether youΓÇÖre a seasoned player or new to the game, this camp offers a unique opportunity to learn from professional athletes in a top-tier facility. The Cyclones are dedicated to helping players of all levels hone their hitting, fielding, base-running, and overall game knowledge. Campers will get hands-on coaching from experienced pros and leave with invaluable skills to elevate their game. Beyond just baseball, this camp is about building confidence, teamwork, and making lasting friendships. Plus, campers will get the chance to attend a Cyclones game against Wilmington ΓÇô a perfect way to round out an unforgettable experience!',7,14,'all','2026-08-11','2026-08-13',329.0,'per_session','$329','https://www.ussportscamps.com/baseball/nike/nike-baseball-camp-brooklyn-cyclones',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','4d4f41f7-e754-4f98-bf4a-91440e13e2ae','nike-baseball-camp-at-maimonides-park-directed-by-brooklyn-cyclones-aug-11-13-20','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-98a5c853-61c5-54d8-b101-7cac1194d61b','org-fa56bc85-b165-5fac-8861-87f4435be8c8','nike-baseball-camp-at-edgewood-university-aug-10-13-2026-9i81','Nike Baseball Camp at Edgewood University -  (Aug. 10ΓÇô13, 2026)','camp','camp_sports','["baseball_softball"]','Get ready for another outstanding Nike Baseball Camp at Edgewood University in Verona, Wisconsin! After a fantastic 2025 camp, the coaching staff is energized and ready to make 2026 even better. Athletes of all abilities are encouraged to join us this summer to gain valuable baseball experience and create lasting memories. Quality facilities, knowledgeable coaches, and a positive, growth-focused environment continue to define this camp. All baseball fundamentals will be covered, including throwing, running, fielding, batting, bunting, baserunning, and pitching. Along with instruction and drill work, campers will enjoy fun, modified drills and games designed to enhance skill development. Pitchers and catchers wonΓÇÖt want to miss the additional Pitching/Catching Session on Friday the 14thΓÇöa great opportunity to refine mechanics and elevate performance both on the mound and behind the plate.',7,13,'all','2026-08-10','2026-08-13',349.0,'per_session','$349','https://www.ussportscamps.com/baseball/nike/nike-baseball-camp-edgewood-university',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','feb059f5-be69-4a67-a1e6-26702c8747b4','nike-baseball-camp-at-edgewood-university-aug-10-13-2026-9i81','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-cebca028-85da-551d-8965-802af6d5b8f8','org-dda3f7a2-5a16-5e80-9079-3f41b83cf134','nike-baseball-camp-at-worcester-state-university-aug-10-13-2026-k01d','Nike Baseball Camp at Worcester State University -  (Aug. 10ΓÇô13, 2026)','camp','camp_sports','["baseball_softball"]','No matter your skill level, Nike Baseball Camp Worcester State University offers training to help all campers achieve their goals. Our low camper-to-coach ratio ensures campers receive the attention and training they need to improve their game throughout the week. Whether it be long-term or short-term goals you have set for yourself, Directors Phil Price and Jack Rafferty and their coaching staff are determined to help you get a step closer to your accomplishments this summer.',7,8,'all','2026-08-10','2026-08-13',419.0,'per_session','$419','https://www.ussportscamps.com/baseball/nike/nike-baseball-camp-worcester-state-university',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','89001ff1-e675-4d4c-8ab3-0cf768468970','nike-baseball-camp-at-worcester-state-university-aug-10-13-2026-k01d','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-fcf5d281-c9f6-55f4-a0a6-e013c7672beb','org-e6f558a0-65a8-57fd-b64d-d77b8a039758','nike-baseball-camp-at-maimonides-park-directed-by-brooklyn-cyclones-aug-11-13-20-yp15','Nike Baseball Camp at Maimonides Park, directed by Brooklyn Cyclones -  (Aug. 11ΓÇô13, 2026)','camp','camp_sports','["baseball_softball"]','This summer, the Brooklyn Cyclones, the High-A Affiliate of the New York Mets and a proud member of the South Atlantic League, are excited to host the Nike Baseball Camp at Maimonides Park in Brooklyn, NY. Whether youΓÇÖre a seasoned player or new to the game, this camp offers a unique opportunity to learn from professional athletes in a top-tier facility. The Cyclones are dedicated to helping players of all levels hone their hitting, fielding, base-running, and overall game knowledge. Campers will get hands-on coaching from experienced pros and leave with invaluable skills to elevate their game. Beyond just baseball, this camp is about building confidence, teamwork, and making lasting friendships. Plus, campers will get the chance to attend a Cyclones game against Wilmington ΓÇô a perfect way to round out an unforgettable experience!',7,14,'all','2026-08-11','2026-08-13',329.0,'per_session','$329','https://www.ussportscamps.com/baseball/nike/nike-baseball-camp-brooklyn-cyclones',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','9b66bf67-9076-4a37-a5e1-0ccb1bab747d','nike-baseball-camp-at-maimonides-park-directed-by-brooklyn-cyclones-aug-11-13-20-yp15','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-0402d99e-edd0-5ac7-aead-4e54a39436c3','org-49523d68-ec3a-596b-af97-1964ca698154','nike-volleyball-camp-at-avenues-the-world-school-making-the-team-camp-aug-10-13-','Nike Volleyball Camp at Avenues The World School - Making the Team Camp (Aug. 10ΓÇô13, 2026)','camp','camp_sports','["volleyball"]','Join us for a fun and active volleyball camp at Avenues The World School in New York City! Open to boys and girls ages 10ΓÇô17, this camp is a great way for players to spend time on the court, learn new skills, and enjoy the game in a positive, supportive setting. Campers will work with experienced coaches through a mix of drills, games, and team play. Whether trying something new or continuing to build on existing skills, athletes can expect a high-energy camp experience filled with learning, movement, and plenty of volleyball fun.',10,17,'all','2026-08-10','2026-08-13',699.0,'per_session','$699','https://www.ussportscamps.com/volleyball/nike/nike-volleyball-camp-avenues-world-school',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','9c44100a-95e0-4f45-a869-ed88ff0cecc9','nike-volleyball-camp-at-avenues-the-world-school-making-the-team-camp-aug-10-13-','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-48169eaa-5084-55b9-ab51-7a86c7bdf15c','org-a868d244-3794-5fef-a199-53e68d243a3a','nike-soccer-camp-at-ridgefield-academy-aug-10-13-2026-v3v5','Nike Soccer Camp at Ridgefield Academy -  (Aug. 10ΓÇô13, 2026)','camp','camp_sports','["soccer"]','Next Step Training was voted a top 10 Nike Soccer Camp in 2025 by players and parents! Next Step''s soccer camps provide exceptional coaching and a welcoming atmosphere that helps players of all levels grow. With engaging drills, supportive instructors, and a strong emphasis on teamwork, it creates an exciting environment where kids can build confidence, improve their skills, and have a great time on the field. Join us at Nike Soccer Camp this summer at the beautiful Ridgefield Academy in Ridgefield, CT! A yearly favorite that sells out every summer, this camp offers a fun and engaging training experience for players ages 7ΓÇô14. Next Step''s soccer camps provide exceptional coaching and a welcoming atmosphere that helps players of all levels grow. With engaging drills, supportive instructors, and a strong emphasis on teamwork, it creates an exciting environment where kids can build confidence, improve their skills, and have a great time on the field. "At Next Step Soccer, our camps are built around one simple idea, develop the player, not just the session. Every activity is designed to improve how players think, move, and make decisions in the game, while building confidence and a genuine love for soccer. We create a high-energy, supportive environment where players are challenged, coached with purpose, and leave each day better than they arrived, both on and off the field." - Nick Woodruff, Camp Director &amp; Founder, Next Step Training',7,14,'all','2026-08-10','2026-08-13',405.0,'per_session','$405-$565','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-ridgefield-academy',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','7be6ac0b-b72a-48dd-9169-798be537964d','nike-soccer-camp-at-ridgefield-academy-aug-10-13-2026-v3v5','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
