INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-5c48547e-9a11-5146-9073-8da7f10c5cba','org-a67452a9-e724-5911-a8a9-847ca0310ca5','camp-yougottawanna-week-8','Camp Yougottawanna Week 8','camp','camp_general',NULL,'Puyallup Parks and Recreation summer day camp at the Puyallup Activity Center. Sports, games, swim, art, and weekly field trips with Parks staff.',6,12,'all','2026-08-10','2026-08-14',225.0,'per_session','$225','https://secure.rec1.com/WA/puyallup-parks-recreation/catalog',NULL,'open','day',0,0,NULL,NULL,'scraped','active',90,'secure.rec1.com','live','798166ef-e41d-4348-adf8-66cd7f239fce','camp-yougottawanna-week-8','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-ad5ff99b-d6c8-5d6d-b1b3-c459d71bc6b0','org-c6a19cf4-2d29-5bed-b166-354120bb638a','summer-camp-climbing-rock-stars-2-tacoma','Summer Camp - Climbing Rock Stars 2 - Tacoma','camp','camp_general',NULL,'Five-day Tacoma day camp at the Mountaineers Tacoma Program Center for kids in grades 1-7 focused on advancing climbing skills. Identical curriculum to Climbing Rock Stars 1, simply the second instance of the theme. Activities include top-roping, belaying, rappelling, clipping draws, mock-leading, anchor building, and possibly leading sport routes for ready students. Each group gets one outdoor climbing field trip to Exit 38 near North Bend. Friday meets at Point Defiance Park. Camp runs 8:30am to 4:30pm. Led by Sarah Holt.',6,13,'intermediate','2026-08-10','2026-08-14',385.0,'per_session','$385 members / $410 guests','https://www.mountaineers.org/locations-lodges/tacoma-branch/committees/tacoma-youth-outreach-committee/course-templates/copy3_of_summer-camp-rock-ropes-1-tacoma/summer-camp-climbing-rock-stars-2-tacoma-2026',NULL,'waitlist','day',0,0,NULL,NULL,'scraped','active',90,'mountaineers.org','live','3e3d2e9b-e5ed-4002-83e8-79c675c66b03','summer-camp-climbing-rock-stars-2-tacoma','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-bcbfdbbf-0d8c-57bb-9de2-84a4d388e08e','org-c6a19cf4-2d29-5bed-b166-354120bb638a','summer-camp-teen-adventures-backpacking-tacoma','Summer Camp - Teen Adventures: Backpacking - Tacoma','camp','camp_general',NULL,'Four-day teen backpacking adventure for ages 13-17, new and experienced backpackers welcome. Tuesday is at the Tacoma Program Center learning backcountry skills including first aid, navigation, the 10 essentials, Leave No Trace principles, and using backpacking gear. Wednesday through Friday is a multi-day backpacking trip in the wilderness covering 5-7 miles per day with 1,000-2,000 feet of elevation gain, carrying packs that weigh 30-35 pounds. Led by Sarah Holt.',13,17,'all','2026-08-11','2026-08-14',475.0,'per_session','$475 members / $500 guests','https://www.mountaineers.org/locations-lodges/tacoma-branch/committees/tacoma-youth-outreach-committee/course-templates/summer-camp-teen-adventures-intro-backpacking-tacoma/summer-camp-teen-adventures-backpacking-tacoma-2026',NULL,'open','overnight',0,0,NULL,NULL,'scraped','active',90,'mountaineers.org','live','0b287a88-9115-426e-8683-5a81268bf89a','summer-camp-teen-adventures-backpacking-tacoma','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
