INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-99c55598-e30c-551d-8c1e-6f1fc7668eae','org-e9c360f9-e7b3-58b1-a92c-f1e00d926bfc','nike-tennis-camp-in-lake-tahoe-granlibakken-resort-overnight-day-camp-aug-9-14-2','Nike Tennis Camp in Lake Tahoe, Granlibakken Resort - Overnight & Day Camp (Aug. 9ΓÇô14, 2026)','camp','camp_sports','["tennis"]','Set against the backdrop of Lake Tahoe, the Nike Tennis Camp at Granlibakken Resort offers a focused yet fun training environment for boys and girls ages 9ΓÇô18. Campers work closely with an experienced coaching staff dedicated to developing strong fundamentals, refining technique, and improving pointΓÇæplay decision making. Instruction balances skill development with competitive drills and match play, giving players the structure and repetition needed to make real progress on court. With personalized coaching and a supportive camp atmosphere, athletes leave Tahoe not only more confident and capable players, but with memories shaped by great tennis, fresh mountain air, and a true summer camp experience. Camp options include Full Day, Extended Day, and Overnight sessions, allowing campers to fully immerse themselves in training while enjoying everything Granlibakken and Lake Tahoe have to offer. Families wanting to stay at Granlibakken Resort can reserve rooms at a discounted rate using either the link or promo code below! Link: Granlibakken Resort Booking Link Promo Code: NKECMP CLICK HERE TO VIEW ALL NIKE CAMPS AT GRANLIBAKKEN RESORT, LAKE TAHOE',9,18,'all','2026-08-09','2026-08-14',945.0,'per_session','$945','https://www.ussportscamps.com/tennis/nike/lake-tahoe-nike-tennis-camp-granlibakken-resort#session-78817-1212102',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','d9d0117a-5122-463f-b1b3-1093386311d3','nike-tennis-camp-in-lake-tahoe-granlibakken-resort-overnight-day-camp-aug-9-14-2','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
