INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-f9f8af0c-fd7a-5452-bbe9-c7a683434d30','org-1168263d-72ed-584f-8d98-572c7930d676','nike-volleyball-camp-at-avenues-the-world-school-serving-passing-clinic-aug-14-2','Nike Volleyball Camp at Avenues The World School - Serving & Passing Clinic (Aug. 14, 2026)','camp','camp_sports','["volleyball"]','Join us for a fun and active volleyball camp at Avenues The World School in New York City! Open to boys and girls ages 10ΓÇô17, this camp is a great way for players to spend time on the court, learn new skills, and enjoy the game in a positive, supportive setting. Campers will work with experienced coaches through a mix of drills, games, and team play. Whether trying something new or continuing to build on existing skills, athletes can expect a high-energy camp experience filled with learning, movement, and plenty of volleyball fun.',10,17,'all','2026-08-14','2026-08-14',109.0,'per_session','$109','https://www.ussportscamps.com/volleyball/nike/nike-volleyball-camp-avenues-world-school',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','73de2996-338d-45f1-83a6-eb8a64f82746','nike-volleyball-camp-at-avenues-the-world-school-serving-passing-clinic-aug-14-2','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-835a80f6-093f-57fb-92f8-113ecfa46343','org-0a84abe5-d181-5deb-ad08-8bdfae9ed931','nike-soccer-camp-in-moorestown-aug-10-14-2026','Nike Soccer Camp in Moorestown -  (Aug. 10ΓÇô14, 2026)','camp','camp_sports','["soccer"]','Join Barry Lynch and his coaching staff at the Nike Soccer Camp in Moorestown. Located at Moorestown High School in Moorestown, NJ, this camp offers the perfect blend of training and gameplay. The focus at camp will be on player development, each camper will refine their technique, learn new skills, compete in games and drills, have fun, and make new friends. This youth soccer camp provides the perfect blend of instruction and fun! Make friends and create memories with our team that will last a lifetime! Sure to be a summer highlight, these camps offer a unique opportunity for aspiring soccer players aged 5-16. Throughout the week campers learn new skills, perfect techniques, increase game knowledge, make new friends and have fun playing soccer!',5,16,'all','2026-08-10','2026-08-14',285.0,'per_session','$285-$395','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-moorestown-new-jersey',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','e9b1601b-860c-4fd9-94d4-83f4c81ba11b','nike-soccer-camp-in-moorestown-aug-10-14-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-b7303af0-efcb-56ef-9339-abc34818ba8f','org-928d67d5-3bb8-569d-a127-f957e5d79207','nike-soccer-camp-in-issaquah-aug-10-14-2026','Nike Soccer Camp in Issaquah -  (Aug. 10ΓÇô14, 2026)','camp','camp_sports','["soccer"]','Rich Schreiner was voted a Top-10 Nike Soccer Camp Director in 2025 by players and parents! The Nike Soccer Camp at Central Park Fields in Issaquah, WA, will be supervised by Seattle University''s coaching staff and players. It offers an All-Skills option catering to players aged 6-12 of all abilities. All Skills campers will acquire new abilities and nurture their love for the game. Elite Performance participants will concentrate on technical and tactical training, aiming to enhance their performance. This presents an exceptional opportunity for young soccer enthusiasts to refine their skills under the guidance of experienced and enthusiastic coaches in a delightful and inclusive setting.',5,12,'all','2026-08-10','2026-08-14',299.0,'per_session','$299-$439','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-seattle-university-issaquah',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','debe8f7c-00e0-4338-ab32-4538df4bc1f2','nike-soccer-camp-in-issaquah-aug-10-14-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-2ffddea9-88d5-5094-9c39-f27e33b40f71','org-de5ee70b-fc18-5379-b496-9de4fdc9510c','nike-soccer-camp-at-glendale-sports-complex-aug-10-14-2026','Nike Soccer Camp at Glendale Sports Complex -  (Aug. 10ΓÇô14, 2026)','camp','camp_sports','["soccer"]','So Cal Youth Sports was voted a top 10 Nike Soccer Camp in 2025 by players and parents! Join us for an amazing week of camp at Nike Soccer Camp at Glendale Sports Complex in Glendale, CA. Team up with Camp Director Matthew Bambrick for the ultimate soccer training camp! The soccer camp is built around a nano-sided games approach, where players learn through fast-paced, highΓÇæengagement game formats rather than standing in lines. This method gives athletes more touches, more decisions, and more meaningful learning in real game contexts. With an individualΓÇæfirst coaching philosophy, the camp prioritizes developing each playerΓÇÖs confidence, understanding, and ownership of their game while improving decisionΓÇæmaking through guided play and live scenarios. The camp provides a fun, inclusive, and energizing environment where players feel confident to compete and improve. Campers experience a competition format that blends learning, competition, and shared moments, culminating in a full camp tournament. Beyond technical development, the program emphasizes lasting values of character, love of the game, and longΓÇæterm growth, helping players develop not just for the week of camp, but for the years ahead. Hear from Camp Director Matt Bambrick: "This isnΓÇÖt a traditional camp. We use NanoGames and real game-based coaching to develop smarter, more confident players. By focusing on the individual first, every player builds decision-making, connection, and a deeper love for the game. The focus doesn''t stop at your child as a player but also on developing a rounded person. Great people make great players."',5,14,'all','2026-08-10','2026-08-14',349.0,'per_session','$349-$479','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-glendale-sports-complex',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','1a3e5b25-5527-4576-8157-d2c3b2bb13a6','nike-soccer-camp-at-glendale-sports-complex-aug-10-14-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-cb74611f-a7b5-5aec-86e2-cc56d61cc363','org-291d8eec-5b17-5452-8f9d-341a6c7e7427','nike-soccer-camp-in-gaithersburg-aug-10-14-2026','Nike Soccer Camp in Gaithersburg -  (Aug. 10ΓÇô14, 2026)','camp','camp_sports','["soccer"]','Join us for an amazing week of camp at the Nike Soccer Camp in Gaithersburg, Maryland, hosted at Laytonia Recreational Park! Led by WAU MenΓÇÖs Head Coach Daniel Carroll alongside the WAU menΓÇÖs soccer and PhiloSoccer Training coaching staff, this camp delivers far more than elite soccer instruction, it offers a truly transformative experience. The program is built on the belief that a great sports camp should teach not only the game, but also the life skills soccer uniquely develops: challenge, discipline, teamwork, selfΓÇæexpression, resilience, creativity, and sportsmanship. A thoughtfully designed curriculum blends fundamental through advanced soccer skills with both timeΓÇætested and innovative coaching methods, ensuring players grow on and off the field. Hear from Camp Director Daniel Carroll: "PhiloSoccer camps are about more than soccer! We believe a true sports camp should deliver and teach players all of the many life skills that the game has to offer, through: challenge, discipline, teamwork, self-expression, adversity, creativity and sportsmanship. Our curriculum is designed to teach fundamental to advanced soccer skills and techniques but also help players shine and step into the best versions of themselves each and every day."',8,16,'all','2026-08-10','2026-08-14',280.0,'per_session','$280-$399','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-gaithersburg-md',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','089af28b-db99-4631-aeff-ce91963cba55','nike-soccer-camp-in-gaithersburg-aug-10-14-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-fba2cb3c-3688-595f-8de4-fe136cd396d4','org-860d6f36-8d39-5abd-8243-139ef512c185','nike-soccer-camp-in-libertyville-aug-10-14-2026-oout','Nike Soccer Camp in Libertyville -  (Aug. 10ΓÇô14, 2026)','camp','camp_sports','["soccer"]','Soccer Skill Schools was voted a Top-10 Nike Soccer Camp in 2024 &amp; 2025 by players and parents! Join us for the Nike Soccer Camp in Libertyville with Kyle Jones, Director of Soccer Skill Schools. This camp welcomes players of all abilities, ages 6-16, to develop and refine their technical skills in a dynamic, competitive environment. It''s an exceptional opportunity for any player to train under top coaching professionals while having fun and pushing their game to the next level! Soccer Skill Schools'' "Numbers Approach Methodology" brings world-class skill development methods from Brazil, Holland, England, and Spain directly to the Midwest. The Soccer Skill School approach focuses on the individual player by guiding each athlete toward complete mastery of the ball, empowering them to make their own creative decisions, and equipping them with 65+ individual skills to win the one-on-one competitions that determine every game''s outcome. Led by experienced college coaches and current college players, the Soccer Skill Schools staff brings elite-level expertise and mentorship to every session. Training alongside coaches who compete at the collegiate level gives players invaluable insight into what it takes to elevate their game and succeed at the next level! Hear from Coach Kyle Jones: ΓÇ£We create an environment where players are challenged, supported, and inspired every day. Through high-quality coaching and a love for the game, our goal is to help each athlete build confidence, develop their skills, and leave camp better both on and off the field.ΓÇ¥',6,16,'all','2026-08-10','2026-08-14',529.0,'per_session','$529','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-libertyville-il',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','c6484597-7ea0-4e55-9f9d-78b58fd96f9d','nike-soccer-camp-in-libertyville-aug-10-14-2026-oout','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
