INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-449566a1-a858-5c1d-a81e-0d8e29111beb','org-a212931a-b6e7-5f60-90b4-604caa84aed4','nike-soccer-camp-at-charles-river-school-aug-17-20-2026','Nike Soccer Camp at Charles River School -  (Aug. 17ΓÇô20, 2026)','camp','camp_sports','["soccer"]','Join us this summer for the ultimate soccer experience at the Nike Soccer Camp at Charles River School, nestled in the scenic town of Dover, Massachusetts, just minutes from the heart of Boston. Whether you''re a beginner eager to learn the basics or an experienced player aiming to take your skills to the next level, our camp offers the perfect environment for players ages 7-16. A Step Ahead (ASA) Nike Soccer Camps are designed for a player looking to improve their game and soccer IQ. Emphasis is placed on fundamental development, shooting, offense/defense, team play, and more. Instruction is available to boys and girls, playing at all levels, from beginner to advanced. Players are evaluated on the first day and placed in groups on age and ability. Improve your skills and meet new friends this summer at the Nike Soccer Camp at Charles River School!',7,16,'all','2026-08-17','2026-08-20',415.0,'per_session','$415','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-charles-river-school#session-81232-1216051',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','42e77749-ad35-4916-8942-650579f93a76','nike-soccer-camp-at-charles-river-school-aug-17-20-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
