INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-936e431e-226c-59eb-b6a8-d9ebb74a49df','org-008d9b99-9a78-58c4-96de-33ff84229622','nike-tennis-camp-at-lewis-clark-college-aug-17-20-2026','Nike Tennis Camp at Lewis & Clark College -  (Aug. 17ΓÇô20, 2026)','camp','camp_sports','["tennis"]','Join us for an unforgettable tennis experience for junior players ages 8-17 at the Nike Tennis Camp at Lewis &amp; Clark College in Portland, Oregon. We offer winter, spring and summer sessions, providing young athletes the opportunity to work on their game year-round. This camp combines expert instruction, intensive drilling, and exciting competitive play, ensuring a well-rounded development for every player. Participants will have many opportunities to practice their skills, technique, and engage in friendly competition with peers who share their passion for tennis! Whether you''re a beginner or looking to refine your advanced skills, our camp is designed to challenge and inspire players of all levels. Get ready to hit countless balls, learn from experienced coaches, and make lasting friendships.',8,17,'all','2026-08-17','2026-08-20',799.0,'per_session','$799','https://www.ussportscamps.com/tennis/nike/nike-tennis-camp-at-lewis-clark-college#session-80268-1214622',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','24e4b24c-3685-4c99-b5d0-6d715249e874','nike-tennis-camp-at-lewis-clark-college-aug-17-20-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-77fbd0f8-8d7d-5b4a-9878-33a2442b9ce7','org-a212931a-b6e7-5f60-90b4-604caa84aed4','nike-soccer-camp-at-charles-river-school-aug-17-20-2026-e8eu','Nike Soccer Camp at Charles River School -  (Aug. 17ΓÇô20, 2026)','camp','camp_sports','["soccer"]','Join us this summer for the ultimate soccer experience at the Nike Soccer Camp at Charles River School, nestled in the scenic town of Dover, Massachusetts, just minutes from the heart of Boston. Whether you''re a beginner eager to learn the basics or an experienced player aiming to take your skills to the next level, our camp offers the perfect environment for players ages 7-16. A Step Ahead (ASA) Nike Soccer Camps are designed for a player looking to improve their game and soccer IQ. Emphasis is placed on fundamental development, shooting, offense/defense, team play, and more. Instruction is available to boys and girls, playing at all levels, from beginner to advanced. Players are evaluated on the first day and placed in groups on age and ability. Improve your skills and meet new friends this summer at the Nike Soccer Camp at Charles River School!',7,16,'all','2026-08-17','2026-08-20',415.0,'per_session','$415','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-charles-river-school',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','f591a0e9-4806-4093-a3ec-94b9b2bcd58d','nike-soccer-camp-at-charles-river-school-aug-17-20-2026-e8eu','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
