INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-78b4197e-da75-59c9-82a5-ed0da99e773d','org-eb67b7d9-3db5-5ff7-9824-91917a1ee644','gig-harbor-day-camp','Gig Harbor Day Camp','camp','camp_general',NULL,'Gig Harbor Day Camp offers a summer of outdoor fun for kids ages 6 to 12. Campers spend their days swimming, hiking, doing arts and crafts, playing field games, and exploring nature on the YMCA property. Weekly themes keep activities fresh, and trained counselors lead small groups so every camper gets attention. Registration is by week, so families can pick the dates that work for their summer schedule.',6,12,'all','2026-06-22','2026-08-21',NULL,NULL,'Varies by week','https://www.ymcapkc.org/locations/tom-taylor-family-ymca',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,NULL,'live','a480d9d4-1d57-4ddd-8b17-728143e7b946','gig-harbor-day-camp','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-c457649f-2b26-5fce-866d-12e71958508a','org-e0617848-2d14-5c5e-bc89-648cf0d1ac95','sahale-outdoors-nature-camp','Sahale Outdoors Nature Camp','camp','camp_general',NULL,'Sahale Outdoors runs nature day camps for kids who want to spend their summer outside. Campers learn wilderness skills, identify plants and animals, build forts, cook over a fire, and play group games in the woods. Counselors are trained naturalists who keep groups small and the pace flexible. Campers should come prepared to get muddy and tired in the best possible way. Sessions run from the org base in Fife and at field locations across the south Puget Sound area.',6,13,'beginner','2026-06-29','2026-08-21',NULL,NULL,NULL,'https://sahaleoutdoors.org/',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,NULL,'live','c20b3a3c-1392-4cf7-9d5d-7d87a51ade89','sahale-outdoors-nature-camp','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
