INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-edae966b-2c9d-5156-bd6c-c185c3aca5bc','org-4af9676a-9ca9-5950-90dd-fd1eeb3e6039','nike-soccer-camp-in-moorestown-aug-17-21-2026','Nike Soccer Camp in Moorestown -  (Aug. 17ΓÇô21, 2026)','camp','camp_sports','["soccer"]','Join Barry Lynch and his coaching staff at the Nike Soccer Camp in Moorestown. Located at Moorestown High School in Moorestown, NJ, this camp offers the perfect blend of training and gameplay. The focus at camp will be on player development, each camper will refine their technique, learn new skills, compete in games and drills, have fun, and make new friends. This youth soccer camp provides the perfect blend of instruction and fun! Make friends and create memories with our team that will last a lifetime! Sure to be a summer highlight, these camps offer a unique opportunity for aspiring soccer players aged 5-16. Throughout the week campers learn new skills, perfect techniques, increase game knowledge, make new friends and have fun playing soccer!',5,16,'all','2026-08-17','2026-08-21',285.0,'per_session','$285-$395','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-moorestown-new-jersey',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','b1901624-53d9-4021-8430-90a0f9e9a6e5','nike-soccer-camp-in-moorestown-aug-17-21-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-fbb99a57-4703-509a-96cb-184673ba10ef','org-044d938e-f670-5c81-8ffb-f41480060561','nike-soccer-camp-in-west-seattle-all-skills-iv-aug-17-21-2026','Nike Soccer Camp in West Seattle - All Skills IV (Aug. 17ΓÇô21, 2026)','camp','camp_sports','["soccer"]','Rich Schreiner was voted a Top-10 Nike Soccer Camp Director in 2025 by players and parents! Join us for an exciting opportunity to elevate your game at the Nike Soccer Camp in West Seattle.. Supervised by the experienced coaching staff and players of Seattle University, this camp offers young soccer enthusiasts the chance to sharpen their skills in a dynamic, inclusive environment. Whether you''re looking to improve technical abilities, tactical understanding, or team coordination, you''ll be guided by passionate coaches in one of Seattle''s most vibrant communities. Don''t miss this chance to train like a pro, learn from the best, and enjoy the beautiful Pacific Northwest surroundings. This camp was held at Georgetown Playfield in 2023 but returned to Delridge Playfield in 2024 and 2025. This summer, we are offering three weeks at Del Ridge and one week at Hiawatha Playfield (July 13-17)',5,12,'all','2026-08-17','2026-08-21',339.0,'per_session','$339-$469','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-seattle-delridge-playfields',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','479c5925-bf8a-4177-a026-8dc04a0959e0','nike-soccer-camp-in-west-seattle-all-skills-iv-aug-17-21-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
