INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-7c9e7e50-b48c-53f9-9ef7-8c3eb4d985db','org-0995674e-4a18-5f9b-8df1-87a07c5d7844','nike-volleyball-camp-at-community-wellness-center-with-volleyball-elite-training-ugkr','Nike Volleyball Camp at Community Wellness Center with Volleyball Elite Training - All Skills Academy (Aug. 2ΓÇô23, 2026)','camp','camp_sports','["volleyball"]','Come elevate your game with the Volleyball Elite Training coaches and get the opportunity to be coached by LOVB Atlanta and Atlanta Vibe players! Our volleyball camp offers a fun and competitive environment where athletes will receive personalized coaching, improve their techniques, and engage in team-building activities. We will focus on developing key skills such as serving, passing, setting, hitting, blocking, and defensive strategies.',9,14,'all','2026-08-02','2026-08-23',165.0,'per_session','$165','https://www.ussportscamps.com/volleyball/nike/nike-volleyball-camp-community-wellness-center',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','288ddad3-f1ba-484a-8e2e-9a6ac5705f3b','nike-volleyball-camp-at-community-wellness-center-with-volleyball-elite-training-ugkr','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-8a0cd20b-c3c8-587e-b6eb-7cecb488b24a','org-eb67b7d9-3db5-5ff7-9824-91917a1ee644','pearl-street-ymca-mid-week-camp-color-blast','Pearl Street YMCA Mid Week Camp - Color Blast','camp','camp_general',NULL,'Tuesday through Thursday partial-week option at Pearl Street YMCA, Week 10 (Color Blast theme). Campers ages 5 to 12 join classic camp games, group activities, and a colorful theme finale to the summer. Check-in 8:45 am, check-out 4 pm. Extended care available 7 to 8:30 am and 4:30 to 6 pm.',5,12,'all','2026-08-25','2026-08-27',189.0,'per_session','$189 members, $236 community members','https://www.ymcapkc.org/camps/summer-day-camp/pearl-street-family-ymca',NULL,'open','day',0,1,NULL,NULL,'scraped','active',60,NULL,'live','ef6823db-6250-4971-bdd8-719ac8e40c6d','pearl-street-ymca-mid-week-camp-color-blast','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
