INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-011f1006-8bab-5d66-a892-18bd6c59cf26','org-eb67b7d9-3db5-5ff7-9824-91917a1ee644','pearl-street-ymca-all-week-camp-tropical-paradise','Pearl Street YMCA All Week Camp - Tropical Paradise','camp','camp_general',NULL,'Week 1 of Pearl Street YMCA Summer Day Camp. Campers ages 5 to 12 spend Monday through Friday in age-based groups led by counselors and CITs. The week features tropical-themed games, swimming at least once, crafts, and small and large group activities. All-Week campers age 7 and up also pick a Specialty Camp (sports, climbing, arts, gymnastics, and similar) that meets 1 to 2:30 pm Monday through Thursday. Check-in 8:45 am, check-out 4 pm, with optional extended care 7 to 8:30 am and 4:30 to 6 pm. Pack a nut-free lunch.',5,12,'all','2026-06-22','2026-08-28',247.0,'per_session','$247 members, $352 community members','https://www.ymcapkc.org/camps/summer-day-camp/pearl-street-family-ymca',NULL,'open','day',0,1,NULL,NULL,'scraped','active',60,NULL,'live','d6a7f33c-16d2-4701-9f26-4fb5fe8fa90f','pearl-street-ymca-all-week-camp-tropical-paradise','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
INSERT INTO programs (id,organization_id,slug,name,program_type,activity_category,categories,description,age_min,age_max,skill_level,session_start_date,session_end_date,price,price_type,price_text,registration_url,registration_deadline,availability_status,day_or_overnight,lunch_included,aftercare_available,schedule_text,hero_photo_key,record_source,record_status,confidence_score,source_domain,url_health_status,legacy_camp_id,legacy_slug,created_at,last_verified_at,updated_at) VALUES ('prog-7e938564-cc1e-5cab-acf8-3b69f952a0a2','org-be602e5f-89fd-5d7d-9976-dbe9d6bb555d','fablab-education-summer-camps-2026','FABLAB Education Summer Camps 2026','camp','coding_stem',NULL,'FABLAB Education runs week-long summer camps in Tacoma for kids interested in making, building, and design. Campers rotate through hands-on projects in 3D printing, laser cutting, electronics, robotics, and woodworking. Each week has a theme, and campers take home the projects they build. Camps are led by working makers and educators who guide kids through the design process from sketch to finished piece. Full scholarships available for Tacoma youth via Tacoma Creates.',7,14,'all','2026-06-22','2026-08-28',NULL,NULL,NULL,'https://www.fablabeducation.org/program/day-camps/',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,NULL,'live','249a51b0-ab46-4bde-be3e-fd41d75e0c1b','fablab-education-summer-camps-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
