,275.0,'per_session','$275','https://www.ussportscamps.com/soccer/nike/nike-soccer-camp-northbrook#session-85096-1221321',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','e680ab52-7d13-48ab-aef8-57f7eccf9065','nike-soccer-camp-in-northbrook-nov-23-25-2026','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
