,'2026-11-27','2026-11-29',229.0,'per_session','$229','https://www.ussportscamps.com/soccer/nike/nike-indoor-soccer-camp-hub-sports-rancho-solano#session-82837-1218213',NULL,'open','day',0,0,NULL,NULL,'scraped','active',60,'ussportscamps.com','live','658ff1e0-44c3-4b3e-a06d-b331f242b1f5','nike-indoor-soccer-camp-with-hub-sports-at-rancho-solano-prep-school-thanksgivin','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z','2026-06-14T23:10:30Z');
